window.PACK={"book":{"id":"diwan-abufiras","title":"ديوان أبو فراس الحمداني","type":"diwan","author":"أبو فراس الحمداني (ت ٣٥٧هـ)","source":"الموسوعة الشعرية / المكتبة الشاملة عبر مشروع OpenITI","optional":true,"era":"abbasi","packVersion":"58c288ca6993"},"items":[{"id":"diwan-abufiras:1","bookId":"diwan-abufiras","type":"poem","seq":1,"chapter":"البحر: مجزوء الرمل","title":"صاحب لما أساء","page":"","text":"صاحب لما أساء … أتبع الدلو الرشاء\nرب داء لا أرى من … ه سوى الصبر شفاء\nأحمد الله على ما … سر من أمري وساء"},{"id":"diwan-abufiras:2","bookId":"diwan-abufiras","type":"poem","seq":2,"chapter":"البحر: مخلع البسيط","title":"كان قضيبا له انثناء","page":"","text":"كان قضيبا له انثناء … وكان بدرا له ضياء\nفزاده ربه عذارا … تم به الحسن والبهاء\nكذلك الله كل وقت … يزيد في الخلق ما يشاء"},{"id":"diwan-abufiras:3","bookId":"diwan-abufiras","type":"poem","seq":3,"chapter":"البحر: متقارب تام","title":"أيا سيدا عمني جوده ،","page":"","text":"أيا سيدا عمني جوده ، … بفضلك نلت السنى والسناء\nوكم قد أتيتك من ليلة ! … فنلت الغنى وسمعت الغناء"},{"id":"diwan-abufiras:4","bookId":"diwan-abufiras","type":"poem","seq":4,"chapter":"البحر: كامل تام","title":"أقناعة ، من بعد طول جفاء ،","page":"","text":"أقناعة ، من بعد طول جفاء ، … بدنو طيف من حبيب ناء !\nبأبي وأمي شادن قلنا له : … نفديك بالأمات والآباء\nرشأ إذا لحظ العفيف بنظرة … كانت له سببا إلى الفحشاء\nوجناته تجني على عشاقه … ببديع ما فيها من اللألآء\nبيض علتها حمرة فتوردت … مثل المدام خلطتها بالماء\nفكأنما برزت لنا بغلالة … بيضاء تحت غلالة حمراء\nكيف اتقاء لحاظه ؛ وعيوننا … طرق لأسهمها إلى الأحشاء ؟\nصبغ الحيا خديه لون مدامعي … فكأنه يبكي بمثل بكائي\nكيف اتقاء جآذر يرميننا … بظبى الصوارم من عيون ظباء ؟\nيا رب تلك المقلة النجلاء ، … حاشاك مما ضمنت أحشائي ؟\nجازيتني بعدا بقربي في الهوى … ومنحتني غدرا بحسن وفائي\nجادت عراصك يا شآم سحابة … عراضة من أصدق الأنواء !\nبلد المجانة والخلاعة والصبا … ومحل كل فتوة وفتاء\nأنواع زهر والتفاف حدائق … وصفاء ماء واعتدال هواء\nوخرائد مثل الدمى يسقيننا … كأسين من لحظ ومن صهباء\nوإذا أدرن على الندامى كأسها … غنيننا شعر ابن أوس الطائي\nفارقت ، حين شخصت عنها ، لذتي … وتركت أحوال السرور ورائي\nونزلت من بلد ' الجزيرة ' منزلا … خلوا من الخلطاء والندماء\nفيمر عندي كل طعم طيب … من ريقها ويضيق كل فضاء\nألشام لا بلد الجزيرة لذتي … و' قويق ' لا ماء ' الفرات ' منائي\nوأبيت مرتهن الفؤاد بمنبج الس … وداء لا ' بالرقة ' البيضاء\nمن مبلغ الندماء : أني بعدهم … أمسي نديم كواكب الجوزاء ؟\nولقد رعيت فليت شعري من رعى … منكم على بعد الديار إخائي ؟\nفحم الغبي وقلت غير ملجلج : … إني لمشتاق إلى العلياء\nوصناعتي ضرب السيوف وإنني … متعرض في الشعر بالشعراء\nوالله يجمعنا بعز دائم … وسلامة موصولة ببقاء"},{"id":"diwan-abufiras:5","bookId":"diwan-abufiras","type":"poem","seq":5,"chapter":"البحر: متقارب تام","title":"أما يردع الموت أهل النهى","page":"","text":"أما يردع الموت أهل النهى … ويمنع عن غيه من غوى !\nأما عالم ، عارف بالزمان … يروح ويغدو قصير الخطا\nفيا لاهيا ، آمنا ، والحمام … إليه سريع ، قريب المدى\nيسر بشيء كأن قد مضى ، … ويأمن شيئا كأن قد أتى\nإذا ما مررت بأهل القبور … تيقنت أنك منهم غدا\nوأن العزيز ، بها ، والذليل … سواء إذا أسلما للبلى\nغريبين ، ما لهما مؤنس ، … وحيدين ، تحت طباق الثرى\nفلا أمل غير عفو الإله … ولا عمل غير ما قد مضى\nفإن كان خيرا فخيرا تنال ؛ … وإن كان شرا فشرا يرى"},{"id":"diwan-abufiras:6","bookId":"diwan-abufiras","type":"poem","seq":6,"chapter":"البحر: مجزوء الرجز","title":"كأنما تساقط الثلج","page":"","text":"كأنما تساقط الثلج … ج بعيني من رأى\nأوراق ورد أبض … والناس في شاذكلى"},{"id":"diwan-abufiras:7","bookId":"diwan-abufiras","type":"poem","seq":7,"chapter":"البحر: متقارب تام","title":"أتزعم أنك خدن الوفاء","page":"","text":"أتزعم أنك خدن الوفاء … وقد حجب الترب من قد حجب\nفإن كنت تصدق فيما تقول … فمت قبل موتك مع من تحب\nوإلا فقد صدق القائلون : … ما بين حي وميت نسب\nعقيلتي استلبت من يدي … ولما أبعها ولما أهب\nوكنت أقيك ، إلى أن رمتك … يد الدهر من حيث لم أحتسب\nفما نفعتني تقاتي عليك … ولا صرفت عنك صرف النوب\nفلا سلمت مقلة لم تسح … ولا بقيت لمة لم تشب\nيعزون عنك وأين العزاء ! ؟ … ولكنها سنة تستحب\nولو رد بالرزء ما تستحق … لما كان لي في حياة أرب"},{"id":"diwan-abufiras:8","bookId":"diwan-abufiras","type":"poem","seq":8,"chapter":"البحر: متقارب تام","title":"أسيف الهدى ، وقريع العرب","page":"","text":"أسيف الهدى ، وقريع العرب … علام الجفاء وفيم الغضب ؟\nوما بال كتبك قد أصبحت … تنكبني مع هذي النكب\nوأنت الكريم ، وأنت الحليم ، … وأنت العطوف ، وأنت الحدب\nومازلت تسبقني بالجميل … وتنزلني بالجناب الخصب\nوتدفع عن حوزتي الخطوب ، … وتكشف عن ناظري الكرب\nوإنك للجبل المشمخ … ر لي بل لقومك بل للعرب\nعلى تستفاد ، ومال يفاد ، … وعز يشاد ، ونعمى ترب\nوما غض مني هذا الإسار … ولكن خلصت خلوص الذهب\nففيم يقرعني بالخمو … ل مولى به نلت أعلى الرتب ؟\nوكان عتيدا لدي الجواب ، … ولكن لهيبته لم أجب\nفأشكر ما كنت في ضجرتي ، … وأني عتبتك فيمن عتب !\nفألا رجعت فأعتبتني ، … وصيرت لي ولقولي الغلب !\nفلا تنسبن إلي الخمول … أقمت عليك فلم أغترب\nوأصبحت منك فإن كان فضل … وبيني وبينك فوق النسب !\nوما شككتني فيك الخطوب … ولا غيرتني فيك النوب\nوأسكن ما كنت في ضجرتي … وأحلم ما كنت عند الغضب\nوإن خراسان إن أنكرت … علاي فقد عرفتها ' حلب '\nومن أين ينكرني الأبعدون … أمن نقص جد أمن نقص أب ؟ !\nألست وإياك من أسرة ، … وبيني وبينك قرب النسب !\nوداد تناسب فيه الكرام ، … وتربية ومحل أشب !\nونفس تكبر إلا عليك … وترغب إلاك عمن رغب !\nفلا تعدلن ، فداك ابن عم … ك لا بل غلامك - عما يجب\nوأنصف فتاك فإنصافه … من الفضل والشرف المكتسب\nوكنت الحبيب وكنت القريب … ليالي أدعوك من عن كثب\nفلما بعدت بدت جفوة … ولاح من الأمر ما لا أحب\nفلو لم أكن بك ذا خبرة … لقلت : صديقك من لم يغب"},{"id":"diwan-abufiras:9","bookId":"diwan-abufiras","type":"poem","seq":9,"chapter":"البحر: مجزوء الكامل","title":"لله برد ما أش","page":"","text":"لله برد ما أش … د ومنظر ما كان أعجب\nجاء الغلام بناره … حمراء في جمر تلهب\nفكأنما جمع الحل … ي فمحرق منها ومذهب\nثم انطفت فكأنها … ما بيننا ند مشعب"},{"id":"diwan-abufiras:10","bookId":"diwan-abufiras","type":"poem","seq":10,"chapter":"البحر: متقارب تام","title":"تقر دموعي بشوقي إليك","page":"","text":"تقر دموعي بشوقي إليك … ويشهد قلبي بطول الكرب\nوإني لمجتهد في الجحود ، … ولكن نفسي تأبى الكذب\nوإني عليك لجاري الدموع ، … وإني عليك لصب وصب\nوما كنت أبقي على مهجتي … لو أني انتهيت إلى ما يجب\nولكن سمحت لها بالبقاء … رجاء اللقاء على ما تحب\nويبقي اللبيب له عدة … لوقت الرضا في أوان الغضب"},{"id":"diwan-abufiras:11","bookId":"diwan-abufiras","type":"poem","seq":11,"chapter":"البحر: متقارب تام","title":"وما أنس لا أنس يوم المغار","page":"","text":"وما أنس لا أنس يوم المغار … محجبة لفظتها الحجب\nدعاك ذووها بسوء الفعال … لما لا تشاء ، وما لا تحب\nفوافتك تعثر في مرطها ، … وقد رأت الموت من عن كثب\nوقد خلط الخوف لما طلع … ت دل الجمال بذل الرعب\nتسارع في الخطو لا خفة ، … وتهتز في المشي لا من طرب\nفلما بدت لك فوق البيوت … بدا لك منهن جيش لجب\nفكنت أخاهن إذ لا أخ … وكنت أباهن إذ ليس أب\nوما زلت مذ كنت تأتي الجميل … وتحمي الحريم ، وترعى النسب\nوتغضب حتى إذا ما ملكت … أطعت الرضا ، وعصيت الغضب\nفولين عنك يفدينها ، … ويرفعن من ذيلها ما انسحب\nينادين بين خلال البيو … ت : لا يقطع الله نسل العرب\nأمرت - وأنت المطاع الكريم - … ببذل الأمان ورد السلب\nوقد رحن من مهجات القلوب … بأوفر غنم وأغلى نشب\nفإن هن يابن السراة الكرام ، … رددن القلوب رددنا النهب"},{"id":"diwan-abufiras:12","bookId":"diwan-abufiras","type":"poem","seq":12,"chapter":"البحر: مجزوء الكامل","title":"الشعر ديوان العرب ،","page":"","text":"الشعر ديوان العرب ، … أبدا ، وعنوان النسب\nلم أعد فيه مفاخري … ومديح آبائي النجب\nومقطعات ربما … حليت منهن الكتب\nلا في المديح ولا الهجاء … ء ولا المجون ولا اللعب"},{"id":"diwan-abufiras:13","bookId":"diwan-abufiras","type":"poem","seq":13,"chapter":"البحر: مجزوء الكامل","title":"لن للزمان ، وإن صعب","page":"","text":"لن للزمان ، وإن صعب … وإذا تباعد فاقترب\nلا تكذبن ، من غالب ال … أيام كان لها الغلب"},{"id":"diwan-abufiras:14","bookId":"diwan-abufiras","type":"poem","seq":14,"chapter":"البحر: طويل","title":"ألا إنما الدنيا مطية راكب","page":"","text":"ألا إنما الدنيا مطية راكب … علا راكبوها ظهر أعوج أحدبا\nشموس متى أعطتك طوعا زمامها … فكن للأذى من عقها مترقبا"},{"id":"diwan-abufiras:15","bookId":"diwan-abufiras","type":"poem","seq":15,"chapter":"البحر: بسيط تام","title":"من كان أنفق في نصر الهدى نشبا","page":"","text":"من كان أنفق في نصر الهدى نشبا … فأنت أنفقت فيه النفس والنشبا\nيذكي أخوك شهاب الحرب معتمدا … فيستضيء ، ويغشى جدك اللهبا"},{"id":"diwan-abufiras:16","bookId":"diwan-abufiras","type":"poem","seq":16,"chapter":"البحر: طويل","title":"أتزعم ، يا ضخم اللغاديد ، أننا","page":"","text":"أتزعم ، يا ضخم اللغاديد ، أننا … ونحن أسود الحرب لا نعرف الحربا\nفويلك ؛ من للحرب إن لم نكن لها ؟ … ومن ذا الذي يمسي ويضحي لها تربا ؟\nومن ذا يلف الجيش من جنباته ؟ … ومن ذا يقود الشم أو يصدم القلبا ؟\nوويلك ؛ من أردى أخاك ' بمرعش ' … وجلل ضربا وجه والدك العضبا ؟\nوويلك من خلى ابن أختك موثقا ؟ … وخلاك باللقان تبتدر الشعبا ؟\nأتوعدنا بالحرب حتى كأننا … وإياك لم يعصب بها قلبنا عصبا ؟\nلقد جمعتنا الحرب من قبل هذه … فكنا بها أسدا ؛ وكنت بها كلبا\nفسل ' بردسا ' عنا أباك وصهره … وسل آل ' برداليس ' أعظمكم خطبا !\nوسل قرقواسا والشميشق صهره ، … وسل سبطه البطريق أثبتكم قلبا\nوسل صيدكم آل الملاين إننا … نهبنا ببيض الهند عزهم نهبا !\nوسل آل ' بهرام ' وآل ' بلنطس ' … وسل آل ' منوال ' الجحاجحة الغلبا !\nوسل ' بالبرطسيس ' العساكر كلها … وسل ' بالمنسطرياطس ' الروم والعربا\nألم تفنهم قتلا وأسرا سيوفنا … وأسد الشرى الملأى وإن جمدت رعبا\nبأقلامنا أجحرت أم بسيوفنا ؟ … وأسد الشرى قدنا إليك أم الكتبا ؟\nتركناك في بطن الفلاة تجوبها … كما انتفق اليربوع يلتثم التربا\nتفاخرنا بالطعن والبضرب في الوغى … لقد أوسعتك النفس يابن استها كذبا\nرعى الله أوفانا إذا قال ذمة … وأنفذنا طعنا ، وأثبتنا قلبا\nوجدت أباك العلج لما خبرته … أقلكم خيرا ، وأكثركم عجبا"},{"id":"diwan-abufiras:17","bookId":"diwan-abufiras","type":"poem","seq":17,"chapter":"البحر: وافر تام","title":"ندل على موالينا ونجفو","page":"","text":"ندل على موالينا ونجفو … ونعتبهم وإن لنا الذنوبا\nبأقوال يجانبن المعاني … وألسنة يخالفن القلوبا"},{"id":"diwan-abufiras:18","bookId":"diwan-abufiras","type":"poem","seq":18,"chapter":"البحر: وافر تام","title":"أبت عبراته إلا انسكابا","page":"","text":"أبت عبراته إلا انسكابا … ونار ضلوعه إلا التهابا\nومن حق الطلول علي ألا … أغب من الدموع لها سحابا\nوما قصرت في تسآل ربع ، … ولكني سألت فما أجابا\nرأيت الشيب لاح فقلت : أهلا ! … وودعت الغواية والشبابا\nوما إن شبت من كبر ، ولكن … رأيت من الأحبة ما أشابا\nبعثن من الهموم إلي ركبا … وصيرن الصدود لها ركابا\nألم ترنا أعز الناس جارا … وأمنعهم ؛ وأمرعهم جنابا ؟ !\nلنا الجبل المطل على نزار … حللنا النجد منه والهضابا\nتفضلنا الأنام ولا نحاشى … ونوصف بالجميل ؛ ولا نحابى\nوقد علمت ' ربيعة ' بل ' نزار ' … بأنا الرأس والناس الذنابى\nفلما أن طغت سفهاء ' كعب ' … فتحنا بيننا للحرب بابا\nمنحناها الحرائب غير أنا … إذا جارت منحناها الحرابا\nولما ثار ' سيف الدين ' ثرنا … كما هيجت آسادا غضابا\nأسنته ، إذا لاقى طعانا ، … صوارمه ، إذا لاقى ضرابا\nدعانا - والأسنة مشرعات - … فكنا ، عند دعوته ، الجوابا\nصنائع فاق صانعها ففاقت ، … وغرس طاب غارسه ، فطابا\nوكنا كالسهام ؛ إذا أصابت … مراميها فراميها أصابا\n … ونكبن ' الصبيرة ' و' القبابا '\nوجاوزن ' البدية ' صاديات ؛ … يلاحظن السراب ؛ ولا سرابا\nعبرن ' بماسح ' والليل طفل … وجئن إلى سلمية حين شابا\nفما شعروا بها إلا ثباتا … دوين الشد نصطخب اصطخابا\n … به الأرواح تنتهب انتهابا\nتنادوا ، فانبرت ، من كل فج ، … سوابق ينتجبن لنا انتجابا\nوقاد ندي بن جعفر من عقيل … شعوبا ، قد أسلن به الشعابا\nفما كانوا لنا إلا أسارى … وما كانت لنا إلا نهابا\nكأن ' ندي بن جعفر ' قاد منهم … هدايا لم يرغ عنها ثوابا\nوشدوا رأيهم ببني قريع ، … فخابوا - لا أبا لهم - وخابا\nولما اشتدت الهيجاء كنا … أشد مخالبا ، وأحد نابا\nوأمنع جانبا ؛ وأعز جارا ؛ … وأوفى ذمة ؛ وأقل عابا\nسقينا بالرماح بني ' قشير ' … ببطن ' الغنثر ' السم المذابا\nوسقناهم إلى ' الحيران ' سوقا … كما نستاق آبالا صعابا\nونكبنا ' الفرقلس ' لم نرده … كأن بنا عن الماء اجتنابا\nوملن عن الغوير وسرن حتى … وردن عيون ' تدمر ' و' الحبابا '\nوأمطرن ' الجباة ' بمرجحن … ولكن بالطعان المر صابا\nوجزن الصحصحان يخدن وخدا … ويجتبن الفلاة بنا اجتيابا\nقرينا ' بالسماوة ' من ' عقيل ' … سباع الأرض والطير السغابا\nو' بالصباح ' و' الصباح ' عبد … قتلنا ، من لبابهم اللبابا\nتركنا في بيوت بني ' المهنا ' … نوادب ينتحبن بها انتحابا\nشفت فيها بنو بكر حقودا … وغادرت ' الضباب ' بها ضبابا\nوأبعدنا لسوء الفعل كعبا … وأدنينا لطاعتها ' كلابا '\nوشردنا إلى الجولان طيئا … وجنبنا ' سماوتها ' جنابا\nسحاب ما أناخ على عقيل … وجر على جوارهم ذنابا\nوملنا بالخيول إلى نمير … تجاذبنا أعنتها جذابا\n … يعز على العشيرة أن يصابا\nوما ضاقت مذاهبه ، ولكن … يهاب ، من الحمية ، أن يهابا\nويأمرنا فنكفيه الأعادي … همام لو يشاء كفى ونابا\nفلما أيقنوا أن لا غياث … دعوه للمغوثة فاستجابا\nوعاد إلى الجميل لهم ؛ فعادوا … وقد مدوا لصارمه الرقابا\nأمر عليهم خوفا وأمنا … أذاقهم به أريا وصابا\nأحلهم الجزيرة بعد يأس … أخو حلم إذا ملك العقابا\n … وأرضهم اغتصبناها اغتصابا\nولو شئنا حميناها البوادي … كما تحمي أسود الغاب غابا\nأنا ابن الضاربين الهام قدما … إذا كره المحامون الضرابا\nألم تعلم ؟ ومثلك قال حقا : … بأني كنت أثقبها شهابا !"},{"id":"diwan-abufiras:19","bookId":"diwan-abufiras","type":"poem","seq":19,"chapter":"البحر: وافر تام","title":"أتعجب أن ملكنا الأرض قسرا","page":"","text":"أتعجب أن ملكنا الأرض قسرا … وأن تمسي وسائدنا الرقاب ؟ !\nوتربط في مجالسنا المذاكي … وتبرك بين أرجلنا الركاب ؟\nفهذا العز أثبته العوالي … وهذا الملك مكنه الضراب\nوأمثال القسي من المطايا … يجب غراسها الخيل العراب\nفقصرا ! إن حالا ملكتنا … لحال لا تذم ولا تعاب"},{"id":"diwan-abufiras:20","bookId":"diwan-abufiras","type":"poem","seq":20,"chapter":"البحر: كامل تام","title":"احذر مقاربة اللئام ! فإنه","page":"","text":"احذر مقاربة اللئام ! فإنه … ينبيك ، عنهم في الأمور ، مجرب\nقوم ، إذا أيسرت ، كانوا إخوة … وإذا تربت ، تفرقوا وتجنبوا\nاصبر على ريب الزمان فإنه … بالصبر تدرك كل ما تتطلب"},{"id":"diwan-abufiras:21","bookId":"diwan-abufiras","type":"poem","seq":21,"chapter":"البحر: طويل","title":"قناتي على ما تعهدان صليبة ،","page":"","text":"قناتي على ما تعهدان صليبة ، … وعودي ، على ما تعلمان صليب\nصبور على طي الزمان ونشره ؛ … وإن ظهرت للدهر في ندوب\nوإن فتى لم يكسر الأسر قلبه … وخوض المنايا جده لنجيب"},{"id":"diwan-abufiras:22","bookId":"diwan-abufiras","type":"poem","seq":22,"chapter":"البحر: طويل","title":"أقر له بالذنب ؛ والذنب ذنبه","page":"","text":"أقر له بالذنب ؛ والذنب ذنبه … ويزعم أني ظالم ، فأتوب\nويقصدني بالهجر علما بأنه … إلي ، على ما كان منه ، حبيب\nومن كل دمع في جفوني سحابة … ومن كل وجد في حشاي لهيب"},{"id":"diwan-abufiras:23","bookId":"diwan-abufiras","type":"poem","seq":23,"chapter":"البحر: طويل","title":"أساء فزادته الإساءة حظوة ،","page":"","text":"أساء فزادته الإساءة حظوة ، … حبيب ، على ما كان منه ، حبيب\nيعد علي العاذلون ذنوبه … ومن أين للوجه المليح ذنوب ؟\nفيا أيها الجاني ، ونسأله الرضا … ويا أيها الجاني ، ونحن نتوب !\nلحى الله من يرعاك في القرب وحده … ومن لا يحوط الغيب حين تغيب"},{"id":"diwan-abufiras:24","bookId":"diwan-abufiras","type":"poem","seq":24,"chapter":"البحر: طويل","title":"أبيت كأني للصبابة صاحب ،","page":"","text":"أبيت كأني للصبابة صاحب ، … وللنوم مذ بان الخليط ، مجانب\nوما أدعي أن الخطوب تخيفني … لقد خبرتني بالفراق النواعب\nولكنني ما زلت أرجو وأتقي … وجد وشيك البين والقلب لاعب\nوماهذه في الحب أول مرة … أساءت إلى قلبي الظنون الكواذب\nعلي لربع ' العامرية ' وقفة … تمل علي الشوق والدمع كاتب\nفلا ، وأبي العشاق ، ما أنا عاشق … إذا هي لم تلعب بصبري الملاعب\nومن مذهبي حب الديار لأهلها … وللناس فيما يعشقون مذاهب\nعتادي لدفع الهم نفس أبية … وقلب على ما شئت منه مصاحب\nحسود على الأمر الذي هو عائب … وخوص كأمثال القسي نجائب\nتكاثر لوامي على ما أصابني … كأن لم تنب إلا بأسري النوائب\nيقولون : ' لم ينظرعواقب أمره ' … ومثلي من تجري عليه العواقب\nألألم يعلم الذلان أن بني الوغى … كذاك ، سليب بالرماح وسالب\nأرى ملء عيني الردى فأخوضه … إذ الموت قدامي وخلفي المعايب\nوإن وراء الحزم فيها ودونه … مواقف تنسى دونهن التجارب\nوأعلم قوما لو تتعتعت دونها … لأجهضني بالذم منهم عصائب\nومضطغن لم يحمل السر قلبه … تلفت ثم اغتابني ، وهو هائب\nتردى رداء الذل لما لقيته … كما تتردى بالغبار العناكب\nومن شرفي أن لا يزال يعيبني … حسود على الأمر الذي هو عاتب\nرمتني عيون الناس حتى أظنها … ستحسدني ، في الحاسدين ، الكواكب\nفلست أرى إلا عدوا محاربا ، … وآخر خير منه عندي المحارب\nويرجون إدراك العلا بنفوسهم … ولم يعلموا أن المعالي مواهب\nفكم يطفئون المجد والله موقد … وكم ينقصون الفضل والله واهب\nوهل يدفع الإنسان ما هو واقع … وهل يعلم الإنسان ما هو كاسب ؟\nوهل لقضاء الله في الخلق غالب … وهل لقضاء الله في الخلق هارب ؟\n … ولا ذنب لي إن حاربتني المطالب\nوهل يرتجي للأمر إلا رجاله … ويأتي بصوب المزن إلا السحائب ! ؟\nوعندي صدق الضرب في كل معرك … وليس علي إن نبون المضارب\nإذا كان ' سيف الدولة ' الملك كافلي … فلا الحزم مغلوب ولا الخصم غالب\nإذا الله لم يحرزك مما تخافه ، … علي لسيف الدولة القرم أنعم\nولا سابق مما تخيلت سابق ، … ولا صاحب مما تخيرت صاحب\nأأجحده إحسانه في ، إنني … لكافر نعمى ، إن فعلت ، موارب\nلعل القوافي عقن عما أردته ، … فلا القول مردود ولا العذر ناضب\nولا شك قلبي ساعة في اعتقاده … ولا شاب ظني قط فيه الشوائب\nتؤرقني ذكرى له وصبابة ، … وتجذبني شوقا إليه الجواذب\nولي أدمع طوعى إذا ما أمرتها ، … وهن عواص في هواه ، غوالب\nفلا تخش ' سيف الدولة ' القرم أنني … سواك إلى خلق من الناس راغب\nفلا تلبس النعمى وغيرك ملبس ، … ولا تقبل الدنيا وغيرك واهب\nولا أنا ، من كل المطاعم ، طاعم … ولا أنا ، من كل المشارب ، شارب\nولا أنا راض إن كثرن مكاسبي ، … إذا لم تكن بالعز تلك المكاسب\nولا السيد القمقام عندي بسيد … إذا استنزلته عن علاه الرغائب\nأيعلم ما نلقى ؟ نعم يعلمونه … على النأي أحباب لنا وحبائب\nأأبقى أخي دمعا ، أذاق كرى أخي ؟ … أآب أخي بعدي ، من الصبرآئب ؟\nبنفسي وإن لم أرض نفسي لراكب … يسائل عني كلما لاح راكب\nقريح مجاري الدمع مستلب الكرى … يقلقله هم من الشوق ناصب\nأخي لا يذقني الله فقدان مثله ! … وأين له مثل ، وأين المقارب ؟\nتجاوزت القربى المودة بيننا ، … فأصبح أدنى ما يعد المناسب\nألا ليتني حملت همي وهمه ، … وأن أخي ناء عن الهم عازب\nفمن لم يجد بالنفس دون حبيبه … فما هو إلا ماذق الود كاذب\nأتاني ، مع الركبان ، أنك جازع ، … وغيرك يخفى عنه لله واجب\nوما أنت ممن يسخط الله فعله … وإن أخذت منك الخطوب السوالب\nوإني لمجزاع ، خلا أن عزمة … تدافع عني حسرة وتغالب\nورقبة حساد صبرت لوقعها … لها جانب مني وللحرب جانب\nفكم من حزين مثل حزني وواله … ولكنني وحدي الحزين المراقب\nولست ملوما إن بكيتك من دمي … إذا قعدت عني الدموع السواكب\nألا ليت شعري هل أبيتن ليلة … تناقل بي فيها إليك الركائب ؟"},{"id":"diwan-abufiras:25","bookId":"diwan-abufiras","type":"poem","seq":25,"chapter":"البحر: طويل","title":"أراني وقومي فرقتنا مذاهب ،","page":"","text":"أراني وقومي فرقتنا مذاهب ، … وإن جمعتنا في الأصول المناسب\nفأقصاهم أقصاهم من مساءتي ، … وأقربهم مما كرهت الأقارب\nغريب وأهلي حيث ما كان ناظري ، … وحيد وحولي من رجالي عصائب\nنسيبك من ناسبت بالود قلبه … وجارك من صافيته لا المصاقب\nوأعظم أعداء الرجال ثقاتها … وأهون من عاديته من تحارب\nوشر عدويك الذي لا تحارب ، … وخير خليليك الذي لا تناسب\nلقد زدت بالأيام والناس خبرة … وجربت حتى هذبتني التجارب\nوما الذنب إلا العجز يركبه الفتى ، … وما ذنبه إن طارته المطالب\nومن كان غير السيف كافل رزقه … فللذل منه لا محالة جانب\nوما أنس دار ليس فيها مؤانس ، … وما قرب قوم ليس فيهم مقارب ! ؟"},{"id":"diwan-abufiras:26","bookId":"diwan-abufiras","type":"poem","seq":26,"chapter":"البحر: طويل","title":"أما لجميل عندكن ثواب ،","page":"","text":"أما لجميل عندكن ثواب ، … ولا لمسيء عندكن متاب ؟\nلقد ضل من تحوي هواه خريدة ، … وقد ذل من تقضي عليه كعاب\nولكنني - والحمد لله - حازم … أعز إذا ذلت لهن رقاب\nولا تملك الحسناء قلبي كله … وإن شملتها رقة وشباب\nوأجري فلا أعطي الهوى فضل مقودي ، … وأهفو ولا يخفى علي صواب\nإذا الخل لم يهجرك إلا ملالة ، … فليس له إلا الفراق عتاب\nإذا لم أجد من خلة ما أريده … فعندي لأخرى عزمة وركاب\nوليس فراق ما استطعت ، فإن يكن … فراق على حال فليس إياب\nصبور ولو لم تبق مني بقية … قؤول ولو أن السيوف جواب\nوقور وأحداث الزمان تنوشني ، … وفي كل يوم لفتة وخطاب\nوألحظ أحوال الزمان بمقلة … بها الصدق صدق والكذاب كذاب\nبمن يثق الإنسان فيما ينوبه … ومن أين للحر الكريم صحاب ؟\nوقد صار هذا الناس إلا أقلهم … ذئابا على أجسادهن ثياب\nتغابيت عن قومي فظنوا غباوة … بمفرق أغبانا حصى وتراب\nولو عرفوني حق معرفتي بهم ، … إذا علموا أني شهدت وغابوا\nوما كل فعال يجازى بفعله ، … ولا كل قوال لدي يجاب\nورب كلام مر فوق مسامعي … \nإلى الله أشكو أننا بمنازل … تحكم في آسادهن كلاب\nتمر الليالي ليس للنفع موضع … لدي ، ولا للمعتفين جناب\nولا شد لي سرج على ظهر سابح ، … ولا ضربت لي بالعراء قباب\nولا برقت لي في اللقاء قواطع … ولا لمعت لي في الحروب حراب\nستذكر أيامي ' نمير ' و' عامر ' … و' كعب ' على علاتها و' كلاب '\nأنا الجار لا زادي بطيء عليهم … ولا دون مالي للحوادث باب\nولا أطلب العوراء منهم أصيبها ، … ولا عورتي للطالبين تصاب\nوأسطو وحبي ثابت في صدورهم … وأحلم عن جهالهم وأهاب\nبني عمنا ما يصنع السيف في الوغى … إذا فل منه مضرب وذباب ؟\n … شداد على غير الهوان صلاب\nبني عمنا نحن السواعد والظبى … ويوشك يوما أن يكون ضراب\n … حريون أن يقضى لهم ويهابوا\nفعن أي عذر إن دعوا ودعيتم … أبيتم ، بني أعمامنا ، وأجابوا ؟\nوما أدعي ، ما يعلم الله غيره … رحاب ' علي ' للعفاة رحاب\nوأفعاله للراغبين كريمة … وأمواله للطالبين نهاب\nولكن نبا منه بكفي صارم … وأظلم في عيني منه شهاب\nوأبطأ عني ، والمنايا سريعة ، … وللموت ظفر قد أطل وناب\n … ولا نسب بين الرجال قراب\nفأحوط للإسلام أن لا يضيعني … ولي عنه فيه حوطة ومناب\nولكنني راض على كل حالة … ليعلم أي الحالتين سراب\nوما زلت أرضى بالقليل محبة … لديه وما دون الكثير حجاب\nوأطلب إبقاء على الود أرضه ، … وذكرى منى في غيرها وطلاب\nكذاك الوداد المحض لا يرتجى له … ثواب ولا يخشى عليه عقاب\nوقد كنت أخشى الهجر والشمل جامع … وفي كل يوم لقية وخطاب\nفكيف وفيما بيننا ملك قيصر … وللبحر حولي زخرة وعباب\nأمن بعد بذل النفس فيما تريده … أثاب بمر العتب حين أثاب ؟\nفليتك تحلو ، والحياة مريرة ، … وليتك ترضى والأنام غضاب\nوليت الذي بيني وبينك عامر … وبيني وبين العالمين خراب"},{"id":"diwan-abufiras:27","bookId":"diwan-abufiras","type":"poem","seq":27,"chapter":"البحر: مجزوء الرمل","title":"إن في الأسر لصبا","page":"","text":"إن في الأسر لصبا … دمعه في الخد صب\nهو في الروم مقيم ، … وله في الشام قلب\nمستجد لم يصادف … عوضا ممن يحب"},{"id":"diwan-abufiras:28","bookId":"diwan-abufiras","type":"poem","seq":28,"chapter":"البحر: وافر تام","title":"زماني كله غضب وعتب","page":"","text":"زماني كله غضب وعتب … وأنت علي والأيام إلب\nوعيش العالمين لديك سهل ، … وعيشي وحده بفناك صعب\nوأنت وأنت دافع كل خطب ، … مع الخطب الملم علي خطب\nإلى كم ذا العقاب وليس جرم … وكم ذا الإعتذار وليس ذنب ؟\nفلا بالشام لذ بفي شرب … ولا في الأسر رق علي قلب\nفلا تحمل على قلب جريح … به لحوادث الأيام ندب\nأمثلي تقبل الأقوال فيه ؟ … ومثلك يستمر عليه كذب ؟\nجناني ما علمت ، ولي لسان … يقد الدرع والإنسان عضب\nوزندي ، وهو زندك ، ليس يكبو … وناري ، وهي نارك ، ليس تخبو\nوفرعي فرعك الزاكي المعلى … وأصلي أصلك الزاكي وحسب\n' لإسمعيل ' بي وبنيه فخر … وفي إسحق بي وبنيه عجب\nوأعمامي ' ربيعة ' وهي صيد … وأخوالي بلصفر وهي غلب\nوفضلي تعجز الفضلاء عنه … لأنك أصله والمجد ترب\nفدت نفسي الأمير ، كأن حظي … وقربي عنده ، ما دام قرب\nفلما حالت الأعداء دوني ، … وأصبح بيننا بحر و' درب '\nظللت تبدل الأقوال بعدي … ويبلغني اغتيابك ما يغب\nفقل ما شئت في فلي لسان … مليء بالثناء عليك رطب\nوعاملني بإنصاف وظلم … تجدني في الجميع كما تحب"},{"id":"diwan-abufiras:29","bookId":"diwan-abufiras","type":"poem","seq":29,"chapter":"البحر: طويل","title":"لقد علمت قيس بن عيلان أننا","page":"","text":"لقد علمت قيس بن عيلان أننا … بنا يدرك الثأر الذي قل طالبه\nوأنا نزعنا الملك من عقر داره … وننتهك القرم الممنع جانبه\nوأنا فتكنا بالأغر ابن رائق … عشية دبت بالفساد عقاربه\nأخذنا لكم بالثار ثار عمارة ، … وقد نام لم ينهد إلى الثأر صاحبه"},{"id":"diwan-abufiras:30","bookId":"diwan-abufiras","type":"poem","seq":30,"chapter":"البحر: رجز تام","title":"وزائر حببه إغبابه","page":"","text":"وزائر حببه إغبابه … طال على رغم السرى اجتنابه\nوافاه دهر عصل أنيابه … واجتاب بطنان العجاج جابه\nيدأب ما رد الزمان دابه … وأرفدت خيراته ورابه\nوافى أمام هطله ربابه … باك حزين ، رعده انتحابه\nجاءت به ، مسيلة أهدابه ، … رائحة هبوبها هبابه\nذيالة ذلت لها صعابه … ركب حيا كان الصبا ركابه\nحتى إذا ما اتصلت أسبابه … وضربت على الثرى عقابه\nوضربت على الربا قبابه … وامتد في أرجائه أطنابه\nوتبع انسجامه انسكابه … وردف اصطفاقه اضطرابه\nكأنما قد حملت سحابه … ركن شروري واصطفت هضابه\nجلى على وجه الثرى كتابه … وشرقت بمائها شعابه\nوحليت بنورها رحابه … كأنه لما انجلى منجابه\nولم يؤمن فقده إيابه … شيخ كبير عاده شبابه"},{"id":"diwan-abufiras:31","bookId":"diwan-abufiras","type":"poem","seq":31,"chapter":"البحر: طويل","title":"ولا تصفن الحرب عندي فإنها","page":"","text":"ولا تصفن الحرب عندي فإنها … طعامي مذ بعت الصبا وشرابي\nوقد عرفت وقع المسامير مهجتي … وشقق عن زرق النصول إهابي\nولججت في حلو الزمان ومره ، … وأنفقت من عمري بغير حساب"},{"id":"diwan-abufiras:32","bookId":"diwan-abufiras","type":"poem","seq":32,"chapter":"البحر: سريع","title":"من لي بكتمان هوى شادن","page":"","text":"من لي بكتمان هوى شادن … عيني له عون على قلبي ؟\nعرضت صبري وسلوى له … فاستشهدا في طاعة الحب"},{"id":"diwan-abufiras:33","bookId":"diwan-abufiras","type":"poem","seq":33,"chapter":"البحر: طويل","title":"لبسنا رداء الليل ، والليل راضع","page":"","text":"لبسنا رداء الليل ، والليل راضع … إلى أن تردى رأسه بمشيب\nوبتنا كغصني بانة عابثتهما … إلى الصبح ريحا شمأل وجنوب\nبحال ترد الحاسدين بغيظهم … وتطرف عنا عين كل رقيب\nإلى أن بدا ضوء الصباح كأنه … مبادي نصول في عذار خضيب\nفيا ليل قد فارقت غير مذمم ، … ويا صبح قد أقبلت غير حبيب"},{"id":"diwan-abufiras:34","bookId":"diwan-abufiras","type":"poem","seq":34,"chapter":"البحر: مجزوء الوافر","title":"ولما أن جعلت الل","page":"","text":"ولما أن جعلت الل … ه لي سترا من النوب\nرمتني كل حادثة … فأخطتني ولم تصب"},{"id":"diwan-abufiras:35","bookId":"diwan-abufiras","type":"poem","seq":35,"chapter":"البحر: وافر تام","title":"مسيء محسن طورا وطورا ،","page":"","text":"مسيء محسن طورا وطورا ، … فما أدري عدوي أم حبيبي\nيقلب مقلة ، ويدير طرفا ، … به عرف البريء من المريب\nوبعض الظالمين ، وإن تناهى ، … شهي الظلم ، مغتفر الذنوب"},{"id":"diwan-abufiras:36","bookId":"diwan-abufiras","type":"poem","seq":36,"chapter":"البحر: طويل","title":"ندبت لحسن الصبر قلب نجيب","page":"","text":"ندبت لحسن الصبر قلب نجيب … وناديت للتسليم خير مجيب\nولم يبق مني غير قلب مشيع … وعود على ناب الزمان صليب\nوقد علمت أمي بأن منيتي … بحد سنان أو بحد قضيب\nكما علمت ؛ من قبل أن يغرق آبنها ، … بمهلكه في الماء ، أم شبيب\nتحملت ، خوف العار ، أعظم خطة … وأملت نصرا كان غير قريب\nوللعار خلى رب غسان ملكه … وفارق دين الله غير مصيب\nولم يرتغب في العيش ' عيسى بن مصعب ' … ولا خف خوف الحرب قلب حبيب\nرضيت لنفسي : ' كان غير موفق ' … ولم ترض نفسي : كان غير نحيب"},{"id":"diwan-abufiras:37","bookId":"diwan-abufiras","type":"poem","seq":37,"chapter":"البحر: سريع","title":"يا عيد ! ما عدت بمحبوب","page":"","text":"يا عيد ! ما عدت بمحبوب … على معنى القلب ، مكروب\nيا عيد ! قد عدت على ناظر ، … عن كل حسن فيك ، محجوب\nيا وحشة الدار التي ربها … أصبح في أثواب مربوب\nقد طلع العيد على أهله … بوجه لا حسن ولا طيب\nما لي وللدهر وأحداثه … لقد رماني بالأعاجيب"},{"id":"diwan-abufiras:38","bookId":"diwan-abufiras","type":"poem","seq":38,"chapter":"البحر: وافر تام","title":"رددت على بني قطن بسيفي","page":"","text":"رددت على بني قطن بسيفي … أسيرا غير مرجو الإياب\nسررت بفكه حيي نمير ، … وسؤت بني ' ربيعة ' و' الضباب '\nوما أبغي سوى شكري ثوابا … وإن الشكر من خير الثواب\nفهل مثن علي فتى نمير … بحلي عنه قد بني ' كلاب '"},{"id":"diwan-abufiras:39","bookId":"diwan-abufiras","type":"poem","seq":39,"chapter":"البحر: بسيط تام","title":"وعلة لم تدع قلبا بلا ألم","page":"","text":"وعلة لم تدع قلبا بلا ألم … سرت إلى طلب العليا وغاربها\nهل تقبل النفس عن نفس فأفديه ؟ … الله يعلم ما تغلو علي بها\nلئن وهبتك نفسا لا نظير لها … فما سمحت بها إلا لواهبها"},{"id":"diwan-abufiras:40","bookId":"diwan-abufiras","type":"poem","seq":40,"chapter":"البحر: كامل تام","title":"فعل الجميل ولم يكن من قصده","page":"","text":"فعل الجميل ولم يكن من قصده … فقبلته وقرنته بذنوبه\nولرب فعل جاءني من فاعل … أحمدته وذممت من يأتي به"},{"id":"diwan-abufiras:41","bookId":"diwan-abufiras","type":"poem","seq":41,"chapter":"البحر: متقارب تام","title":"فديتك ، ما الغدر من شيمتي","page":"","text":"فديتك ، ما الغدر من شيمتي … قديما ولا الهجر من مذهبي !\nوهبني ؛ كما تدعي ؛ مذنبا ! … أما تقبل العذر من مذنب ؟\nوأولى الرجال ، بعتب ، أخ … يكر العتاب على معتب"},{"id":"diwan-abufiras:42","bookId":"diwan-abufiras","type":"poem","seq":42,"chapter":"البحر: سريع","title":"ألزمني ذنبا بلا ذنب","page":"","text":"ألزمني ذنبا بلا ذنب … ولج في الهجران والعتب\nأحاول الصبر على هجره … والصبر محظور على الصب\nوأكتم الوجد ، وقد أصبحت … عيناي عينين على القلب\nقد كنت ذا صبر وذا سلوة … فاستشهدا في طاعة الحب"},{"id":"diwan-abufiras:43","bookId":"diwan-abufiras","type":"poem","seq":43,"chapter":"البحر: سريع","title":"ياليل ؛ ما أغفل ، عما بي ،","page":"","text":"ياليل ؛ ما أغفل ، عما بي ، … حبائبي فيك وأحبابي\nيا ليل ، نام الناس عن موضع … ناء ، على مضجعه نابي\nهبت له ريح شامية … متت إلى القلب بأسباب\nأدت رسالات حبيب لنا … فهمتها من بين أصحابي"},{"id":"diwan-abufiras:44","bookId":"diwan-abufiras","type":"poem","seq":44,"chapter":"البحر: مجزوء الكامل","title":"أبنيتي ، لا تحزني","page":"","text":"أبنيتي ، لا تحزني … كل الأنام إلى ذهاب\nأبنيتي ، صبرا جمي … لا للجليل من المصاب !\nنوحي علي بحسرة ! … من خلف سترك والحجاب\nقولي إذا ناديتني ، … وعييت عن رد الجواب :\nزين الشباب ، ' أبو فرا … س ، لم يمتع بالشباب !"},{"id":"diwan-abufiras:45","bookId":"diwan-abufiras","type":"poem","seq":45,"chapter":"البحر: خفيف تام","title":"وقفتني على الأسى والنحيب","page":"","text":"وقفتني على الأسى والنحيب … مقلتا ذلك الغزال الربيب\nكلما عادني السلو ؛ رماني … غنج ألحاظه بسهم مصيب\nفاترات قواتل ، فاتنات ، … فاتكات سهامها في القلوب\nهل لصب متيم من معين ؟ … ولداء مخامر من طبيب ؟\nأيها المذنب المعاتب حتى … خلت أن الذنوب كانت ذنوبي\nكن كما شئت من وصال وهجر … غير قلبي عليك غير كئيب\nلك جسم الهوى ، وثغر الأقاحي ، … ونسيم الصبا ، وقد القضيب\nقد جحدت الهوى ولكن أقرت … سيمياء الهوى ولحظ المريب\nأنا في حالتي وصال وهجر … من جوى الحب في عذاب مذيب\nبين قرب منغص بصدود … ووصال منغص برقيب\nيا خليلي ، خلياني ودمعي … إن في الدمع راحة المكروب\nما تقولان في جهاد محب … وقف القلب في سبيل الحبيب ؟\nهل من الظاعنين مهد سلامي … للفتى الماجد الأريب الأديب ؟\nابن عمي الداني على شحط دار … والقريب المحل غير قريب\nخالص الود ، صادق الوعد ، أنسي … في حضوري محافظ في مغيبي\nكل يوم يهدي إلي رياضا … جادها فكره بغيث سكوب\nواردات بكل أنس وبر … وافدات بكل حسن وطيب\n' يابن نصر ' وقيت بؤس الليالي … وصروف الردى ، وكرب الخطوب\nبان صبري لما تأمل طرفي : … بان صبري ببين ظبي ربيب"},{"id":"diwan-abufiras:46","bookId":"diwan-abufiras","type":"poem","seq":46,"chapter":"البحر: بسيط تام","title":"يا ضارب الجيش بي في وسط مفرقه","page":"","text":"يا ضارب الجيش بي في وسط مفرقه … لقد ضربت بنفس الصارم الغضب\nلا تحرز الدرع عني نفس صاحبها … ولا أجير ذمام البيض واليلب\nولا أعود برمحي غير منحطم … ولا أروح بسيفي غير مختضب\nحتى تقول لك الأعداء راغمة … ' أضحى ابن عمك هذا فارس العرب '\nهيهات لا أجحد النعماء منعمها … خلفت ' يابن أبي الهيجاء ' في أبي ؟\nيا من يحاذر أن تمضي علي يد … ما لي أراك لبيض الهند تسمح بي ؟\nوأنت بي من أضن الناس كلهم … فكيف تبذلني للسمر والقضب ؟\nما زلت أجهله فضلا وأنكره … نعمى ، وأوسع من عجب ومن عجب\nحتى رأيتك بين الناس مجتنبا … تثني علي بوجه غير متئب\nفعندها ، وعيون الناس ترمقني … علمت أنك لم تخطىء ولم أصب"},{"id":"diwan-abufiras:47","bookId":"diwan-abufiras","type":"poem","seq":47,"chapter":"البحر: كامل تام","title":"ومعود للكر في حمس الوغى ،","page":"","text":"ومعود للكر في حمس الوغى ، … غادرته ؛ والفر من عاداته\nحمل القناة على أغر سميذع ، … دخال ما بين الفتى وقناته\nلا أطلب الرزق الذليل مناله … فوت الهوان أذل من مقناته\nعلقت بنات الدهر ، تطرق ساحتي … لما فضلت بنيه في حالاته\nفالحرب ترميني ببيض رجالها … والدهر يطرقني بسود بناته"},{"id":"diwan-abufiras:48","bookId":"diwan-abufiras","type":"poem","seq":48,"chapter":"البحر: طويل","title":"وما هو إلا أن جرت بفراقنا","page":"","text":"وما هو إلا أن جرت بفراقنا … يد الدهر حتى قيل ، من هو حارث ؟\nيذكرنا بعد الفراق عهوده ، … وتلك عهود قد بلين رثائث"},{"id":"diwan-abufiras:49","bookId":"diwan-abufiras","type":"poem","seq":49,"chapter":"البحر: طويل","title":"ألا ليت قومي ، والأماني مثيرة ،","page":"","text":"ألا ليت قومي ، والأماني مثيرة ، … شهودي ، والأرواح غير لوابث\nغداة تناديني الفوارس ؛ والقنا … ترد إلى حد الظبا كل ناكث\n' أحارث ' إن لم تصدر الرمح قانيا … ولم تدفع الجلى فلست ' بحارث '"},{"id":"diwan-abufiras:50","bookId":"diwan-abufiras","type":"poem","seq":50,"chapter":"البحر: مجزوء الرجز","title":"قامت إلى جارتها","page":"","text":"قامت إلى جارتها … تشكو ، بذل وشجا\nأما ترين ، ذا الفتى ؟ … مر بنا ما عرجا\nإن كان ما ذاق الهوى ، … فلا نجوت ، إن نجا"},{"id":"diwan-abufiras:51","bookId":"diwan-abufiras","type":"poem","seq":51,"chapter":"البحر: سريع","title":"جارية ، كحلاء ، ممشوقة ،","page":"","text":"جارية ، كحلاء ، ممشوقة ، … في صدرها : حقان من عاج\nشجا فؤادي طرفها الساجي ، … وكل ساج طرفه شاج"},{"id":"diwan-abufiras:52","bookId":"diwan-abufiras","type":"poem","seq":52,"chapter":"البحر: وافر تام","title":"ألا أبلغ سراة ' بني كلاب '","page":"","text":"ألا أبلغ سراة ' بني كلاب ' … إذا ندبت نوادبهم صباحا\nجزيت سفيههم سوءءا بسوء … فلا حرجا أتيت ولا جناحا\nقتلت فتى بني عمرو بن عبد … وأوسعهم على الضيفان ساحا\nقتلت معودا علل العشايا ، … تخيرت العبيد له اللقاحا\nولست أرى فسادا في فساد … يجر على طريقته صلاحا"},{"id":"diwan-abufiras:53","bookId":"diwan-abufiras","type":"poem","seq":53,"chapter":"البحر: وافر تام","title":"عجبت ، وقد لقيت بني ' كلاب '","page":"","text":"عجبت ، وقد لقيت بني ' كلاب ' … وأرواح الفوارس تستباح\nوكيف رددت غرب الجيش عنهم … وقد أخذت مآخذها الرماح"},{"id":"diwan-abufiras:54","bookId":"diwan-abufiras","type":"poem","seq":54,"chapter":"البحر: كامل تام","title":"أ' أبا العشائر ' لا محلك دارس","page":"","text":"أ' أبا العشائر ' لا محلك دارس … بين الضلوع ، ولا مكانك نازح\nإني لأعلم بعد موتك أنه … ما مر للأسراء يوم صالح"},{"id":"diwan-abufiras:55","bookId":"diwan-abufiras","type":"poem","seq":55,"chapter":"البحر: بسيط تام","title":"وقد أروح ، قرير العين ، مغتبطا","page":"","text":"وقد أروح ، قرير العين ، مغتبطا … بصاحب مثل نصل السيف وضاح\nعذب الخلائق ، محمود طرائقه ، … عف المسامع ، حتى يرغم اللاحي\nلما رأى لحظاتي في عوارضه ، … فيما أشاءمن الريحان والراح\nلاث اللثام على وجه أسرته … كأنها قمر أو ضوء مصباح"},{"id":"diwan-abufiras:56","bookId":"diwan-abufiras","type":"poem","seq":56,"chapter":"البحر: وافر تام","title":"عدتني عن زيارتكم عواد","page":"","text":"عدتني عن زيارتكم عواد … أقل مخوفها سمر الرماح\nوإن لقاءها ليهون عندي ، … إذا كان الوصول إلى نجاح\nولكن بيننا بين وهجر … أأرجو بعد ذلك من صلاح ؟\nأقمت ، ولو أطعت رسيس شوقي … ركبت إليك أعناق الرياح"},{"id":"diwan-abufiras:57","bookId":"diwan-abufiras","type":"poem","seq":57,"chapter":"البحر: وافر تام","title":"تبسم ، إذ تبسم ، عن أقاح","page":"","text":"تبسم ، إذ تبسم ، عن أقاح … وأسفر ، حين أسفر ، عن صباح\nوأتحفني بكأس من رضاب ، … وكأس من جنى خد وراح\nفمن لألاء غرته صباحي … ومن صهباء ريقته اصطباحي\nفلا تعجل إلى تسريح روحي … فموتي فيك أيسر من سراحي\nأغص بذكره ، أبدا ، بريقي … وأشرق منه بالماء القراح\nوتمنعني مراقبة الأعادي … غدوي للزيارة أو رواحي\nولو أني أملك فيه أمري … ركبت إليه أعناق الرياح"},{"id":"diwan-abufiras:58","bookId":"diwan-abufiras","type":"poem","seq":58,"chapter":"البحر: خفيف تام","title":"لم أؤاخذك بالجفاء ، لأني ،","page":"","text":"لم أؤاخذك بالجفاء ، لأني ، … واثق منك بالوفاء الصحيح\nفجميل العدو غير جميل ، … وقبيح الصديق غير قبيح"},{"id":"diwan-abufiras:59","bookId":"diwan-abufiras","type":"poem","seq":59,"chapter":"البحر: وافر تام","title":"علونا ' جوشنا ' بأشد منه ،","page":"","text":"علونا ' جوشنا ' بأشد منه ، … وأثبت عند مشتجر الرماح\nبجيش جاش ، بالفرسان ، حتى … ظننت ، البر بحرا من سلاح\nوألسنة من العذبات حمر … تخاطبنا بأفواه الرماح\nوأروع ، جيشه ليل بهيم ، … وغرته عمود من صباح\nصفوح عند قدرته كريم … قليل الصفح ما بين الصفاح\nفكان ثباته للقلب قلبا … وهيبته جناحا للجناح"},{"id":"diwan-abufiras:60","bookId":"diwan-abufiras","type":"poem","seq":60,"chapter":"البحر: مجزوء الرمل","title":"أقبلت كالبدر تسعى ،","page":"","text":"أقبلت كالبدر تسعى ، … غلسا ، نحوي ، براح\nقلت : أهلا بفتاة ، … حملت نور الصباح\nعللي بالكأس من أص … بح منها غير صاح"},{"id":"diwan-abufiras:61","bookId":"diwan-abufiras","type":"poem","seq":61,"chapter":"البحر: وافر تام","title":"أيلحاني ، على العبرات ، لاح","page":"","text":"أيلحاني ، على العبرات ، لاح … وقد يئس العواذل من صلاحي\nتملكني الهوى بعد التأبي ، … وروضني الهوى بعد الجماح\nأسكرى اللحظ طيبة الثنايا … أفترى اللحظ ، جائلة الوشاح\nرمتني نحو دارك كل عنس … وصلت لها غدوي بالرواح\nتطاول فضل نسعتها ، وقلت … فضول زمامها ، عند المراح\nحملن إليك صبا ذا ارتياح … بقربك ، أو مساعد ذي ارتياح\nأخا عشرين ، شيب عارضيه … مريض اللحظ في الحدق الصحاح\nنزحن من الرصافة عامدات … أخف الفارسين إلى الصياح\nإذا ما عن لي أرب بأرض ، … ركبت له ، ضمينات النجاح\nولي عند العداة ، بكل أرض ، … ديون في كفالات الرماح\nإذا التفت علي سراة قومي … ولاقينا الفوارس في الصباح\nيخف بها إلى الغمرات طود … بنات السبق تحت بني الكفاح\nتكدر نقعه ، والجو صاف ، … وأظلم وقته ، واليوم صاح\nوكل معذل في الحي آب … على العذال ؛ عصاء اللواحي"},{"id":"diwan-abufiras:62","bookId":"diwan-abufiras","type":"poem","seq":62,"chapter":"البحر: وافر تام","title":"ديون في كفالات الرماح","page":"","text":"ديون في كفالات الرماح … وأكباد مكلمة النواحي\nوحزن ، لا نفاذ له ؛ ودمع … يلاحي ، في الصبابة ، كل لاح\nأتدري ما أروح به وأغدو ، … فتاة الحي حي بني رباح ؟\nألا يا هذه ، هل من مقيل … لضيفان الصبابة ، أو رواح ؟\nفلولا أنت ، ما قلقت ركابي … فتاة الحي حي بني رباح ؟\nومن جراك ، أوطنت الفيافي … وفيك غذيت ألبان اللقاح\nرمتك من الشآم بنا مطايا … قصار الخطو ، دامية الصفاح\nتجول نسوعها ، وتبيت تسري … إلى غراء ، جائلة الوشاح\nإذا لم تشف ، بالغدوات ، نفسي … ولا هبت إلى نجد رياحي !\nيلاحي ، في الصبابة ، كل لاح … وقد هبت لنا ريح الصباح :\nلقد أخذ السرى والليل منا ، … فهل لك أن تريح بجو راح ؟\nفقلت لهم على كره : أريحوا … ولا هبت إلى نجد رياحي !\nإرادة أن يقال أبو فراس ، … على الأصحاب ، مأمون الجماح\nوكم أمر أغالب فيه نفسي … ركبت ، مكان أدنى للنجاح\nيلاحي ، في الصبابة ، كل لاح … وآسو كل خل بالسماح\nوإنا غير أثام لنحوي … جمام الماء ، والمرعى المباح\nوإنا غير أثام لنحوي … منيع الدار ، والمال المراح\nلأملاك البلاد ، علي ، طعن … يحل عزيمة الدرع الوقاح\nويوم ، للكماة به اعتناق ، … ولكن التصافح بالصفاح\nوما للمال يروي عن ذويه … ويصبح في الرعاديد الشحاح\nلنا منه ، وإن لويت قليلا ، … \nوحزن ، لا نفاد له ، ودمع … أتدري ما أروح به وأغدو ،\nتراه ، إذا الكماة الغلب شدوا … أشد الفارسين إلى الكفاح\nأتاني من بني ورقاء قول … ألذ جنى من الماء القراح\nوأطيب من نسيم الروض حفت … به اللذات من روح وراح\nوتبكي في نواحيه الغوادي … بأدمعها ، وتبسم عن أقاح\nعتابك يابن عم بغير جرم … وإنا غير بخال لنحمي\nوما أرضى انتصافا من سواكم … وأغضي منك عن ظلم صراح\nأظنا ؟ إن بعض الظن إثم ! … أمزحا ؟ رب جد في مزاح !\nإذا لم يثن غرب الظن ظن … بسطت العذر في الهجر المباح\nأأترك في رضاك مديح قومي … أصاحب كل خل بالتجافي\nوهم أصل لهذا الفرع طابت … وكم أمر أغالب فيه نفسي\nبقاء البيض عمر الشمل فيهم … وحط السيف أعمار اللقاح\nأعز العالمين حمى وجارا ، … وأكرم مستغاث مستماح\nأريتك يابن عم بأي عذر ؟ … عدوت عن الصواب ؛ وأنت لاح\nوإنا غير بخال لنحمي … كفعلك ؛ أم بأسرتنا افتتاحي\nوهل في نظم شعري من طريف … لمغدى في مكانك ؛ أو مراح ؟\nأمن كعب نشا بحر العطايا … \nوصاحب كل خل مستبيح … وتبكي في نواحيه الغوادي\nوهذا السيل من تلك الغوادي … وهذي السحب من تلك الرياح\nوآسو كل خل بالسماح … أفي مدحي لقومي من جناح ؟\nيلاحي ، في الصبابة ، كل لاح … ومن أضحى امتداحهم امتداحي ؟\nولست ، وإن صبرت على الرزايا … ألا حي أسرتي ، وبهم ألاحي\nولو أني اقترحت على زماني … لكنتم ، يا ' بني ورقا ' اقتراحي"},{"id":"diwan-abufiras:63","bookId":"diwan-abufiras","type":"poem","seq":63,"chapter":"البحر: طويل","title":"تمنيتم أن تفقدوني ، وإنما","page":"","text":"تمنيتم أن تفقدوني ، وإنما … تمنيتم أن تفقدوا العز أصيدا\nأما أنا أعلى من تعدون همة ؟ … وإن كنت أدنى من تعدون مولدا\nإلى الله أشكو عصبة من عشيرتي … يسيئون لي في القول ، غيبا ومشهدا\nوإن حاربوا كنت المجن أمامهم … وإن ضاربوا كنت المهند واليدا\nوإن ناب خطب ، أو ألمت ملمة ، … جعلت لهم نفسي ، وما ملكت فدا\nيودون أن لا يبصروني ، سفاهة ، … ولو غبت عن أمر تركتهم سدى\nفعالي لهم ، لو أنصفوا في جمالها … وحظ لنفسي اليوم وهو لهم غدا\nفلا تعدوني نعمة ، فمتى غدت … فأهلي بها أولى وإن أصبحوا عدا"},{"id":"diwan-abufiras:64","bookId":"diwan-abufiras","type":"poem","seq":64,"chapter":"البحر: بسيط تام","title":"يا طول شوقي إن قالوا : الرحيل غدا ،","page":"","text":"يا طول شوقي إن قالوا : الرحيل غدا ، … لا فرق الله فيما بيننا أبدا\nيا من أصافيه في قرب وفي بعد … ومن أخالصه إن غاب أو شهدا\nراع الفراق فؤادا كنت تؤنسه … وذر بين الجفون الدمع والسهدا\nلا يبعد الله شخصا لا أرى أنسا … ولا تطيب لي الدنيا إذا بعدا\nأضحى وأضحيت في سر وفي علن … أعده والدا إذ عدني ولدا\nما زال ينظم في الشعر مجتهدا … فضلا وأنظم فيه الشعر مجتهدا\nحتى اعترفت وعزتني فضائله ، … وفات سبقا وحاز الفضل منفردا\nإن قصر الجهد عن إدراك غايته … فأعذر الناس من أعطاك ما وجدا\nأبقى لنا الله مولانا ؛ ولا برحت … أيامنا ، أبدا ، في ظله جددا\nلا يطرق النازل المحذور ساحته … ولا تمد إليه الحادثات يدا\nالحمد لله حمدا دائما أبدا … أعطاني الدهر ما لم يعطه أحدا"},{"id":"diwan-abufiras:65","bookId":"diwan-abufiras","type":"poem","seq":65,"chapter":"البحر: كامل تام","title":"أهدى إلي صبابة وكآبة","page":"","text":"أهدى إلي صبابة وكآبة … فأعادني كلف الفؤاد عميدا\nإن الغزالة والغزالة أهدتا … وجها إليك ، إذا طلعت ، وجيدا"},{"id":"diwan-abufiras:66","bookId":"diwan-abufiras","type":"poem","seq":66,"chapter":"البحر: طويل","title":"إلى الله أشكو ما أرى من عشائر","page":"","text":"إلى الله أشكو ما أرى من عشائر … إذا ما دنونا زاد جاهلهم بعدا\nوإنا لتثنينا عواطف حلمنا … عليهم ، وإن ساءت طرائقهم جدا\nويمنعنا ظلم العشيرة أننا … إلى ضرها ، لو نبتغي ضرها ، أهدى\nوإنا إذا شئنا بعاد قبيلة … جعلنا عجالا دون أهلهم نجدا\nولو عرفت هذي العشائر رشدها … إذا جعلتنا دون أعدائها سدا\nولكن أراها ، أصلح الله حالها … وأخلقها بالرشد - قد عدمت رشدا\nإلى كم نرد البيض عنهم صواديا … ونثني صدور الخيل قد ملئت حقدا\nونغلب بالحلم الحمية منهم … ونرعى رجالا ليس نرعى لهم عهدا\nأخاف على نفسي وللحرب سورة … بوادر أمر لا نطيق لها ردا\nوجولة حرب يهلك الحلم دونها … وصولة بأس تجمع الحر والعبدا\nوإنا لنرمي الجهل بالجهل مرة … إذا لم نجد منه على حالة بدا"},{"id":"diwan-abufiras:67","bookId":"diwan-abufiras","type":"poem","seq":67,"chapter":"البحر: مجزوء الكامل","title":"يا معجبا بنجومه","page":"","text":"يا معجبا بنجومه … لا النحس منك ولا السعاده\nالله ينقص ما يشا … ء وفي يد الله الزيادة\nدع ما أريد وما تري … د ، فإن لله الإرادة"},{"id":"diwan-abufiras:68","bookId":"diwan-abufiras","type":"poem","seq":68,"chapter":"البحر: طويل","title":"دعوناك ، والهجران دونك ؛ دعوة","page":"","text":"دعوناك ، والهجران دونك ؛ دعوة … أتاك بها بقظان فكرك لا البرد ؟\nفأصبحت ما بين العدو وبيننا … تجاري بك الخيل المسومة الجرد\nأتيناك ، أدنى ما نجيبك ، جهدنا ، … فأهون سير الخيل من تحتنا الشد\nبكل ، نزاري أتتك بشخصه … عوائد من حاليك ليس لها رد\nنباعدهم وقتا كما يبعد العدا … ونكرمهم وقتا كما يكرم الوفد\nوندنو دنوا لا يولد جرأة … ونجفو جفاء لا يولده زهد\nأفضت عليه الجود من قبل هذه … وأفضل منه ما يؤمله بعد\nوحمر سيوف لا تجف لها ظبى … بأيدي رجال لا يحط لها لبد\nوزرق تشق البرد عن منهج العدا … وتسكن منهم أينما سكن الحقد\nومصطحبات قارب الركض بينها … ولكن بها عن غيرها أبدا بعد\nنشردهم ضربا كما شرد القطا … وننظمهم طعنا كما نظم العقد\nلئن خانك المقدور فيما نويته … فما خانك الركض المواصل والجهد\nتعاد كما عودت ، والهام صخرها ، … ويبنى بها المجد المؤثل والحمد\nففي كفك الدنيا وشيمتك العلا … وطائرك الأعلى وكوكبك السعد"},{"id":"diwan-abufiras:69","bookId":"diwan-abufiras","type":"poem","seq":69,"chapter":"البحر: طويل","title":"أيا عاتبا ، لا أحمل ، الدهر ، عتبه","page":"","text":"أيا عاتبا ، لا أحمل ، الدهر ، عتبه … علي ولا عندي لأنعمه جحد\nسأسكت إجلالا لعلمك أنني … إذا لم تكن خصمي لي الحجج اللد"},{"id":"diwan-abufiras:70","bookId":"diwan-abufiras","type":"poem","seq":70,"chapter":"البحر: مجزوء الرمل","title":"نبوة الإدلال ليست ،","page":"","text":"نبوة الإدلال ليست ، … عندنا ، ذنبا يعد\nقل لمن ليس له عه … د ، لنا عهد وعقد\nجملة تغني عن التف … صيل : ' مالي عنك بد '\nإن تغيرت فما غي … ر منا لك عهد"},{"id":"diwan-abufiras:71","bookId":"diwan-abufiras","type":"poem","seq":71,"chapter":"البحر: طويل","title":"عطفت على عمرو بن تغلب بعدما","page":"","text":"عطفت على عمرو بن تغلب بعدما … تعرض مني جانب لهم صلد\nولا خير في هجر العشيرة لامريء … يروح على ذم العشيرة أو يغدو\nولكن دنو لا يولد هجرة ، … وهجر رفيق لا يصاحبه زهد\nنباعدهم طورا ؛ كما يبعد العدا ؛ … ونكرمهم طورا كما يكرم الوفد"},{"id":"diwan-abufiras:72","bookId":"diwan-abufiras","type":"poem","seq":72,"chapter":"البحر: طويل","title":"لقد كنت أشكو البعد منك وبيننا","page":"","text":"لقد كنت أشكو البعد منك وبيننا … بلاد إذا ما شئت قربها الوخد\nفكيف وفيما بيننا ملك ' قيصر ' … ولا أمل يحيي النفوس ولا وعد !"},{"id":"diwan-abufiras:73","bookId":"diwan-abufiras","type":"poem","seq":73,"chapter":"البحر: مجزوء الكامل","title":"هل للفصاحة ، والسما","page":"","text":"هل للفصاحة ، والسما … حة والعلى عني محيد\nإذ أنت سيدي الذي … ربيتني وأبي سعيد\nفي كل يوم أستفي … د من العلاء ، وأستزيد\nويزيد في إذا رأي … تك في الندى خلق جديد"},{"id":"diwan-abufiras:74","bookId":"diwan-abufiras","type":"poem","seq":74,"chapter":"البحر: طويل","title":"دعوتك للجفن القريح المسهد","page":"","text":"دعوتك للجفن القريح المسهد … لدي ، وللنوم القليل المشرد\nوما ذاك بخلا بالحياة ، وإنها … لأول مبذول لأول مجتد\nوما الأسر مما ضقت ذرعا بحمله … وما الخطب مما أن أقول له : قد\nوما زل عني أن شخصا معرضا … لنبل العدى ؛ إن لم يصب ؛ فكأن قد\nولكنني أختار موت بني أبي … على صهوات الخيل ، غير موسد\nوتأبى وآبى أن أموت موسدا … بأيدي النصارى موت أكمد أكبد\nنضوت على الأيام ثوب جلادتي ؛ … ولكنني لم أنض ثوب التجلد\nوما أنا إلا بين أمر ، وضده … يجدد لي ، في كل يوم مجدد\nفمن حسن صبر بالسلامة واعدي ، … ومن ريب دهر بالردى ، متوعدي\nأقلب طرفي بين خل مكبل … وبين صفي بالحدد مصفد\nدعوتك ، والأبواب ترتج دوننا ، … فكن خير مدعو وأكرم منجد\nفمثلك من يدعى لكل عظيمة … ومثلي من يفدى بكل مسود\nأناديك لا أني أخاف من الردى … ولا أرتجي تأخير يوم إلى غد\nوقد حطم الخطي واخترم العدى … وفلل حد المشرفي المهند\nولكن أنفت الموت في دارغربة ، … بأيدي النصارى الغلف ميتة أكمد\nفلا تترك الأعداء حولي ليفرحوا … ولا تقطع التسآل عني ، وتقعد\nولا تقعدن ، عني ، وقد سيم فديتي ، … فلست عن الفعل الكريم بمقعد\nفكم لك عندي من أياد وأنعم ؟ … رفعت بها قدري وأكثرت حسدي\nتشبث بها أكرومة قبل فوتها ، … وقم في خلاصي صادق العزم واقعد\nفإن مت بعد اليوم عابك مهلكي … معاب الزراريين ، مهلك معبد\nهم عضلوا عنه الفداء فأصبحوا … يهدون أطراف القريض المقصد\nولم يك بدعا هلكه ؛ غير أنهم … يعابون إذ سيم الفداء وما فدي\nفلا كان كلب الروم أرأف منكم … وأرغب في كسب الثناء المخلد\nولا يبلغ الأعداء أن يتناهضوا … وتقعد عن هذا العلاء المشيد\nأأضحوا على أسراهم بي عودا ، … وأنتم على أسراكم غير عود ؟ !\nمتى تخلف الأيام مثلي لكم فتى … طويل نجاد السيف رحب المقلد ؟\nمتى تلد الأيام مثلي لكم فتى … شديدا على البأساء ، غير ملهد ؟\nفإن تفتدوني تفتدوا شرف العلا ، … وأسرع عواد إليها ، معود\nوإن تفتدوني تفتدوا لعلاكم … فتى غير مردود اللسان أو اليد\nيطاعن عن أعراضكم ؛ بلسانه … ويضرب عنكم بالحسام المهند\nفما كل من شاء المعالي ينالها ، … ولا كل سيار إلى المجد يهتدي\nأقلني ! أقلني عثرة الدهر إنه … رماني بسهم ، صائب النصل ، مقصد\nولو لم تنل نفسي ولاءك لم أكن … لأوردها ، في نصره ، كل مورد\nولا كنت ألقى الألف زرقا عيونها … بسبعين فيهم كل أشأم أنكد\nفلا ، وأبي ، ما ساعدان كساعد ، … ولا وأبي ، ما سيدان كسيد\nولا وأبي ، ما يفتق الدهر جانبا … فيرتقه ، إلا بأمر مسدد\nوإنك للمولى ، الذي بك أقتدي ، … وإنك للنجم الذي بك أهتدي\nوأنت الذي عرفتني طرق العلا ، … وأنت الذي أهديتني كل مقصد\nوأنت الذي بلغتني كل رتبة ، … مشيت إليها فوق أعناق حسدي\nفيا ملبسي النعمى التي جل قدرها … لقد أخلقت تلك الثياب فجدد\nألم تر أني ، فيك صافحت حدها … وفيك شربت الموت غير مصرد\nيقولون : جنب عادة ما عرفتها ، … شديد على الإنسان ما لم يعود\nفقلت : أما والله لا قال قائل : … شهدت له في الحرب ألأم مشهد\nولكن سألقاها ، فإما منية … هي الظن ، أو بنيان عز موطد\nولم أدر أن الدهر في عدد العدا ؛ … وأن المنايا السود يرمين عن يد\nبقيت ابن عبد الله تحمى من الردى ، … ويفديك منا سيد بعد سيد\nبعيشة مسعود ؛ وأيام سالم … ونعمة مغبوط ؛ وحال محسد\nولايحرمني الله قربك ! إنه … مرادي من الدنيا ؛ وحظي ؛ وسؤددي"},{"id":"diwan-abufiras:75","bookId":"diwan-abufiras","type":"poem","seq":75,"chapter":"البحر: طويل","title":"لمن جاهد الحساد أجر المجاهد","page":"","text":"لمن جاهد الحساد أجر المجاهد … وأعجز ما حاولت إرضاء حاسد\nولم أر مثلي اليوم أكثر حاسدا ؛ … كأن قلوب الناس لي قلب واجد\nألم ير هذا الناس غيري فاضلا ؟ … ولم يظفر الحساد قبلي بماجد ؟ !\nأرى الغل من تحت النفاق ، وأجتني … من العسل الماذي سم الأساود\nوأصبر ، ما لم يحسب الصبر ذلة ، … وألبس ، للمذموم ، حلة حامد\nقليل اعتذار ، من يبيت ذنوبه … طلاب المعالي واكتساب المحامد\nوأعلم إن فارقت خلا عرفته ، … وحاولت خلا أنني غير واجد\nوهل غض مني الأسر إذ خف ناصري … وقل على تلك الأمور مساعدي\nألا لا يسر الشامتون ، فإنها … موارد آبائي الأولى ، ومواردي\nوكم من خليل ، حين جانبت زاهدا … إلى غيره عاودته غير زاهد !\nوماكل أنصاري من الناس ناصري … ولا كل أعضادي ، من الناس عاضدي\nوهل نافعي إن عضني الدهر مفردا … إذا كان لي قوم طوال السواعد\nوهل أنا مسرور بقرب أقاربي … إذا كان لي منهم قلوب الأباعد ؟\nأيا جاهدا ، في نيل ما نلت من علا … رويدك ! إني نلتها غير جاهد\nلعمرك ، ما طرق المعالي خفية … ولكن بعض السير ليس بقاصد\nويا ساهد العينين فيما يريبني ، … ألا إن طرفي في الأذى غير ساهد\nغفلت عن الحساد ، من غير غفلة ، … وبت طويل النوم عن غير راقد\nخليلي ، ما أعددتما لمتيم … أسير لدى الأعداء جافي المراقد ؟\nفريد عن الأحباب صب ، دموعه … مثان ، على الخدين ، غير فرائد\nإذا شئت جاهرت العدو ، ولم أبت … أقلب فكري في وجوه المكائد\nصبرت على اللأواء ، صبر آبن حرة ، … كثير العدا فيها ، قليل المساعد\nفطاردت ، حتى أبهر الجري أشقري ، … وضاربت حتى أوهن الضرب ساعدي\nوكنا نرى أن لم يصب ، من تصرمت … مواقفه عن مثل هذي الشدائد\nجمعت سيوف الهند ، من كل بلدة ، … وأعددت للهيجاء كل مجالد\nوأكثرت للغارات بيني وبينهم … بنات البكيريات حول المزاود\nإذا كان غير الله للمرء عدة ، … أتته الرزايا من وجوه الفوائد\nفقد جرت الحنفاء حتف حذيفة … وكان يراها عدة للشدائد\nوجرت منايا مالك بن نويرة … عقيلته الحسناء ؛ أيام ' خالد '\nوأردى ذؤابا في بيوت عتيبة ، … أبوه وأهلوه ؛ بشدو القصائد\nعسى الله أن يأتي بخير ؛ فإن لي … عوائد من نعماه ، غير بوائد\nفكم شالني من قعر ظلماء لم يكن … لينقذني من قعرها حشد حاشد\nفإن عدت يوما ؛ عاد للحرب والعلا … وبذل الندى والجود أكرم عائد\nمرير على الأعداء ، لكن جاره … إلى خصب الأكناف عذب الموارد\nمشهى بأطراف النهار وبينها … له ما تشهى ، من طريف وتالد\nمنعت حمى قومي وسدت عشيرتي … وقلدت أهلي غر هذي القلائد\nخلائق لا يوجدن في كل ماجد ، … ولكنها في الماجد ابن الأماجد"},{"id":"diwan-abufiras:76","bookId":"diwan-abufiras","type":"poem","seq":76,"chapter":"البحر: هزج","title":"سلام رائح ، غاد ،","page":"","text":"سلام رائح ، غاد ، … على ساكنة الوادي\nعلى من حبها الهادي ، … إذا ما زرت ، والحادي\nأحب البدو ، من أجل … غزال ، فيهم باد\nألا يا ربة الحلي ، … على العاتق والهادي\nلقد أبهجت أعدائي … وقد أشمت حسادي\nبسقم ما له شاف ، … وأسر ما له فاد\nفإخواني وندماني … وعذالي عوادي\nفما أنفك عن ذكراك … في نوم وتسهاد\nبشوق منك معتاد … وطيف غير معتاد\nألا يا زائر الموص … ل حي ذلك النادي\nفبالموصل إخواني ، … وبالموصل أعضادي\nفقل للقوم يأتون … ي من مثنى وأفراد\nفعندي خصب زوار … وعندي ري وراد\nوعندي الظل ممدودا … على الحاضر والبادي\nألا لا يقعد العجز … بكم عن منهل الصادي\nفإن الحج مفروض … مع الناقة والزاد\nكفاني سطوة الدهر … جواد نسل أجواد\nنماه خير آباء … نمتهم خير أجداد\nفما يصبو إلى أرض … سوى أرضي وروادي\nوقاه الله ، فيما عا … ش ، شر الزمن العادي"},{"id":"diwan-abufiras:77","bookId":"diwan-abufiras","type":"poem","seq":77,"chapter":"البحر: مجزوء الكامل","title":"وزيارة من غير وعد ،","page":"","text":"وزيارة من غير وعد ، … في ليلة طرقت بسعد\nبات الحبيب إلى الصبا … ح معانقي خدا لخد\nيمتار في وناظري … ما شئت من خمر وورد\nقد كان مولاي الأج … ل ، فصيرته الراح عبدي\nليست بأول منة … مشكورة للراح عندي\nليس جودا عطية بسؤال … قد يهز السؤال غير الجواد\nإنما الجود ما أتاك ابتداء … لم تذق فيه ذلة الترداد"},{"id":"diwan-abufiras:78","bookId":"diwan-abufiras","type":"poem","seq":78,"chapter":"البحر: طويل","title":"ولما تخيرت الأخلاء لم أجد","page":"","text":"ولما تخيرت الأخلاء لم أجد … صبورا على حفظ المودة والعهد\nسليما على طي الزمان ونشره … أمينا على النجوى صحيحا على البعد\nولما أساء الظن بي من جعلته … وإياي مثل الكف نيطت إلى الزند\nحملت على ضني به سوء ظنه … وأيقنت أني بالوفا أمة وحدي\nوأني على الحالين في العتب والرضى … مقيم على ما كان يعرف من ودي"},{"id":"diwan-abufiras:79","bookId":"diwan-abufiras","type":"poem","seq":79,"chapter":"البحر: مجزوء الكامل","title":"وإذا يئست من الدن","page":"","text":"وإذا يئست من الدن … ورغبت في فرط البعاد\nأرجو الشهادة في هوا … ك لأن قلبي في جهاد"},{"id":"diwan-abufiras:80","bookId":"diwan-abufiras","type":"poem","seq":80,"chapter":"البحر: سريع","title":"يا جاحدا فرط غرامي به ،","page":"","text":"يا جاحدا فرط غرامي به ، … ولست بالناسي ولا الجاحد\nأقررت في الحب بما تدعي ، … فلست محتاجا إلى شاهد"},{"id":"diwan-abufiras:81","bookId":"diwan-abufiras","type":"poem","seq":81,"chapter":"البحر: بسيط تام","title":"بتنا نعلل من ساق أغن لنا","page":"","text":"بتنا نعلل من ساق أغن لنا … بخمرتين من الصهباء والخد\nكأنه حين أذكى نار وجنته … سكرا وأسبل فضل الفاحم الجعد\nيعد ماء عناقيد بطرته … بماء ما حملت خداه من ورد"},{"id":"diwan-abufiras:82","bookId":"diwan-abufiras","type":"poem","seq":82,"chapter":"البحر: كامل تام","title":"إني منعت من المسيسر إليكم","page":"","text":"إني منعت من المسيسر إليكم … ولو استطعت لكنت أول وارد\nأشكو ، وهل أشكو جناية منعم … غيظ العدو به ، وكبت الحاسد ؟\nقد كنت عدتي التي أسطو بها … ويدي إذا اشتد الزمان وساعدي\nفرميت منك بغير ما أملته … والمرء يشرق بالزلال البارد\nلكن أتت دون السرور مساءة … وصلت لها كف القبول بساعد\nفصبرت كالولد التقي ؛ لبره … أغضى على ألم لضرب الوالد\nونقضت عهدا كيف لي بوفائه … وسقيت دونك كأس هم صارد"},{"id":"diwan-abufiras:83","bookId":"diwan-abufiras","type":"poem","seq":83,"chapter":"البحر: طويل","title":"وداع دعاني ، والأسنة دونه ،","page":"","text":"وداع دعاني ، والأسنة دونه ، … صببت عليه بالجواب جوادي\nجنبت إلى مهري المنيعي مهره … وجللت منه بالنجيع نجادي"},{"id":"diwan-abufiras:84","bookId":"diwan-abufiras","type":"poem","seq":84,"chapter":"البحر: سريع","title":"قولا لهذا السيد الماجد","page":"","text":"قولا لهذا السيد الماجد … قول حزين ، مثله ، فاقد\nهيهات ! ما في الناس من خالد … لا بد من فقد ومن فاقد\nكن المعزى ، لا المعزى به ، … إن كان لا بد من الواحد"},{"id":"diwan-abufiras:85","bookId":"diwan-abufiras","type":"poem","seq":85,"chapter":"البحر: بسيط تام","title":"أوصيك بالحزن ، لا أوصيك بالجلد","page":"","text":"أوصيك بالحزن ، لا أوصيك بالجلد … جل المصاب عن التعنيف والفند\nإني أجلك أن تكفى بتعزية … عن خير مفتقد ، يا خير مفتقد\nهي الرزية إن ضنت بما ملكت … منها الجفون فما تسخو على أحد\nبي مثل ما بك من جزن ومن جزع … وقد لجأت إلى صبر ، فلم أجد\nلم ينتقصني بعدي عنك من حزن ، … هي المواساة في قرب وفي بعد\nلأشركنك في اللأواء إن طرقت … كما شركتك في النعماء والرغد\nأبكي بدمع له من حسرتي مدد ، … وأستريح إلى صبر بلا مدد\nولا أسوغ نفسي فرحة أبدا ، … وقد عرفت الذي تلقاه من كمد\nوأمنع النوم عيني أن يلم بها … علما بإنك موقوف على السهد\nيا مفردا بات يبكي لا معين له ، … أعانك الله بالتسليم والجلد\nهذا الأسير المبقى لا فداء له … يفديك بالنفس والأهلين والولد"},{"id":"diwan-abufiras:86","bookId":"diwan-abufiras","type":"poem","seq":86,"chapter":"البحر: مجزوء الكامل","title":"ولقد علمت ، وما علم","page":"","text":"ولقد علمت ، وما علم … ت ، وإن أقمت على صدوده\nأن الغزالة والغزا … ل ، لفي ثناياه وجيده"},{"id":"diwan-abufiras:87","bookId":"diwan-abufiras","type":"poem","seq":87,"chapter":"البحر: مجزوء الكامل","title":"لا تطلبن دنو دا","page":"","text":"لا تطلبن دنو دا … ر من حبيب ، أو معاشر\nأبقى لأسباب المود … ة أن تزور ولا تجاور"},{"id":"diwan-abufiras:88","bookId":"diwan-abufiras","type":"poem","seq":88,"chapter":"البحر: مجزوء الكامل","title":"الآن حين عرفت رش","page":"","text":"الآن حين عرفت رش … دي ، فاغتديت على حذر\nونهيت نفسي فانتهت ، … وزجرت قلبي فانزجر\nولقد أقام ، على الضلا … لة ، ثم أذعن ، واستمر\nهيهات ، لست ' أبا فرا … س ' إن وفيت لمن غدر !"},{"id":"diwan-abufiras:89","bookId":"diwan-abufiras","type":"poem","seq":89,"chapter":"البحر: مجزوء الكامل","title":"إن زرت ( خرشنة ) أسيرا","page":"","text":"إن زرت ( خرشنة ) أسيرا … فلكم أحطت بها مغيرا\nولقد رأيت النار تن … تهب المنازل والقصورا\nولقد رأيت السبي يج … لب نحونا حوا ، وحورا\nنختار منه الغادة ال … حسناء ، والظبي الغريرا\nإن طال ليلي في ذرا … ك فقد نعمت به قصيرا\nولئن لقيت الحزن في … ك فقد لقيت بك السرورا\nولئن رميت بحادث ، … فلألفين له صبورا\nصبرا لعل الله يف … تح بعده فتحا يسيرا\nمن كان مثلي لم يبت … إلا أسيرا ، أو أميرا\nليست تحل سراتنا … إلا الصدور أو القبورا"},{"id":"diwan-abufiras:90","bookId":"diwan-abufiras","type":"poem","seq":90,"chapter":"البحر: طويل","title":"إذا شئت أن تلقى أسودا قساورا ،","page":"","text":"إذا شئت أن تلقى أسودا قساورا ، … لنعماهم الصفو الذي لن يكدرا\nيلاقيك ، منا ، كل قرم ، سميذع ، … يطاعن حتى يحسب الجون أشقرا\nبدولة سيف الله طلنا على الورى … وفي عزه صلنا على من تجبرا\nقصدنا على الأعداء ، وسط ديارهم … بضرب يرى من وقعه الجو أغبرا\nفسائل كلابا يوم غزوة بالس … ألم يتركوا النسوان في القاع حسرا\nوسائل نميرا ، يوم سار إليهم ، … ألم يوقنوا بالموت ، لما تنمرا ؟\nوسائل عقيلا ، حين لاذت بتدمر ، … ألم نقرها ضربا يقد السنورا\nوسائل قشيرا ، حين جفت حلوقها ، … ألم نسقها كأسا ، من الموت ، أحمرا\nوفي طيىء ، لما أثارت سيوفه … كماتهم ، مرأى لمن كان مبصرا\nوكلب غداة استعصموا بجبالهم ، … رماهم بها ، شعثا ، شوازب ، ضمرا\nفأشبع من أبطالهم كل طائر ، … وذئب غدا يطوي البسيطة أعفرا"},{"id":"diwan-abufiras:91","bookId":"diwan-abufiras","type":"poem","seq":91,"chapter":"البحر: سريع","title":"إرث لصب فيك قد زدته ،","page":"","text":"إرث لصب فيك قد زدته ، … على بلايا أسره ، أسرا\nقد عدم الدنيا ولذاتها ؛ … لكنه ما عدم الصبرا\nفهو أسير الجسم في بلدة ، … وهو أسير القلب في أخرى !"},{"id":"diwan-abufiras:92","bookId":"diwan-abufiras","type":"poem","seq":92,"chapter":"البحر: بسيط تام","title":"وشادن ، من بني كسرى ، شغفت به","page":"","text":"وشادن ، من بني كسرى ، شغفت به … لو كان أنصفني في الحب ما جارا\nإن زار قصر ليلي في زيارته … وإن جفاني أطال الليل أعمارا\nكأنما الشمس بي في القوس نازلة … إن لم يزرني وفي الجوزاء إن زار"},{"id":"diwan-abufiras:93","bookId":"diwan-abufiras","type":"poem","seq":93,"chapter":"البحر: طويل","title":"وكنت ، إذا ما ساءني ، أو أساءني","page":"","text":"وكنت ، إذا ما ساءني ، أو أساءني … لطفت بقلبي أو يقيم له عذرا\nوأكره إعلام الوشاة بهجره … فأعتبه سرا ، وأشكره جهرا\nوهبت لضني سوء ظني ، ولم أدع ، … على حاله ، قلبي يسر له شرا"},{"id":"diwan-abufiras:94","bookId":"diwan-abufiras","type":"poem","seq":94,"chapter":"البحر: وافر تام","title":"دع العبرات تنهمر انهمارا ،","page":"","text":"دع العبرات تنهمر انهمارا ، … ونار الوجد تستعر استعارا\nأتطفأ حسرتي ، وتقر عيني ، … ولم أوقد ، مع الغازين ، نارا ؟\nرأيت الصبر أبعد ما يرجى ، … إذا ما الجيش بالغازين سارا\nوأعددت الكتائب معلمات … تنادي ، كل آن ، بي : سعارا\nوقد ثقفت للهيجاء رمحي ، … وأضمرت المهاري والمهارا\nوكان إذا دعانا الأمر حفت … بنا الفتيان ، تبتدر ابتدارا\nبخيل لا تعاند من عليها ، … وقوم لا يرون الموت عارا\nوراء القافلين بكل أرض ، … وأول من يغير ، إذا أغارا\nستذكرني ، إذا طردت ، رجال ، … دفقت الرمح بينهم مرارا\nوأرض ، كنت أملؤها خيولا ، … وجو ، كنت أرهقه غبارا\nلعل الله يعقبني صلاحا … قويما ، أو يقليني العثارا\nفأشفي من طعان الخيل صدرا … وأدرك من صروف الدهر ثارا\nأقمت على ' الأمير ' ، وكنت ممن … يعز عليه فرقته ، اختيارا\nإذا سار ' الأمير ' ، فلا هدوا … لنفسي أو يؤوب ، ولا قرارا\nأكابد بعده هما ، وغما ، … ونوما ، لا ألذ به غرارا\nوكنت به أشد ذوي بطشا ، … وأبعدهم ، إذا ركبوا ، مغارا\nأشق ، وراءه ، الجيش المعبا ، … وأخرق ، بعده ، الرهج المثارا\nإذا بقي الأمير قرير عين … فديناه ، اختيارا ، لا اضطرار\nأب بر ، ومولى ، وابن عم ، … ومستند ، إذا ما الخطب جارا\nيمد على أكابرنا جناحا ، … ويكفل ، في مواطننا ، الصغارا\nأراني الله طلعته ، سريعا ، … وأصحبه السلامة ، حيث سارا\nوبلغه أمانيه جميعا ، … وكان له من الحدثان جارا"},{"id":"diwan-abufiras:95","bookId":"diwan-abufiras","type":"poem","seq":95,"chapter":"البحر: طويل","title":"وما نعمة مشكورة ، قد صنعتها","page":"","text":"وما نعمة مشكورة ، قد صنعتها … إلى غير ذي شكر ، بمانعتي أخرى\nسآتي جميلا ، ما حييت ، فإنني … إذا لم أفد شكرا ، أفدت به أجرا"},{"id":"diwan-abufiras:96","bookId":"diwan-abufiras","type":"poem","seq":96,"chapter":"البحر: مجزوء الكامل","title":"إن لم تجاف عن الذنو","page":"","text":"إن لم تجاف عن الذنو … ب ، وجدتها فينا كثيره\nلكن عادتك الجمي … لة أن تغض على بصيره"},{"id":"diwan-abufiras:97","bookId":"diwan-abufiras","type":"poem","seq":97,"chapter":"البحر: هزج","title":"لقد نافسني الدهر","page":"","text":"لقد نافسني الدهر … بتأخيري عن الحضرة\nفما ألقى من العل … ة ما ألقى من الحسرة"},{"id":"diwan-abufiras:98","bookId":"diwan-abufiras","type":"poem","seq":98,"chapter":"البحر: مجزوء الرجز","title":"وجلنار مشرق ،","page":"","text":"وجلنار مشرق ، … على أعالي شجره\nكأن في رؤوسه ، … أصفره ، وأحمره\nقراضة من ذهب … في خرق معصفره"},{"id":"diwan-abufiras:99","bookId":"diwan-abufiras","type":"poem","seq":99,"chapter":"البحر: وافر تام","title":"وقوفك في الديار عليك عار ،","page":"","text":"وقوفك في الديار عليك عار ، … وقد رد الشباب المستعار\nأبعد الأربعين محرمات : … تماد في الصبابة ، واغترار ؟ ! . .\nنزعت عن الصبا ، إلا بقايا ، … يحفدها ، على الشيب ، العقار\nوقال الغانيات : ( سلا ، غلاما ، … فكيف به ، وقد شاب العذار ؟ '\nوما أنسى الزيارة منك ، وهنا ، … وموعدنا ' معان ' و' الحيار '\nوطال الليل بي ، ولرب دهر … نعمت به ، لياليه قصار\nوندماني : السريع إلى لقائي ، … على عجل ، وأقداحي الكبار\nعشقت بها عواري الليالي … ' أحق الخيل بالركض المعار\nوكم من ليلة لم أرو منها … حننت لها ، وأرقني ادكار !\nقضاني الدين ماطله ، ووافى ، … إلي بها ، الفؤاد المستطار\nفبت أعل خمرا من رضاب … لها سكر وليس لها خمار\nإلى أن رق ثوب الليل عنا … وقالت : ' قم ! فقد برد السوار !\nوولت تسرق اللحظات نحوي … على فرق كما التفت الصوار\nدنا ذاك الصباح ، فلست أدري … أشوق كان منه ؟ أم ضرار ؟\nوقد عاديت ضوء الصبح حتى … لطرفي ، عن مطالعه ، ازورار\nومضطغن يراود في عيبا … سيلقاه ، إذا سكنت وبار\nوأحسب أنه سيجر حربا … على قوم ذنوبهم صغار\nكما خزيت ب ' راعيها ' ' نمير ' ، … وجر على ' بني أسد ' ' يسار '\nوكم يوم وصلت بفجر ليل … كأن الركب تحتهما صدار ؟\nإذا انحسر الظلام امتد آل … كأنا دره ، وهو البحار\nيموج على النواظر ، فهو ماء … ويلفح بالهواجر فهو نار\nإذا ما العز أصبح في مكان … سموت له ، وإن بعد المزار\nمقامي ، حيث لا أهوى ، قليل … ونومي ، عند من أقلي غرار\nأبت لي همتي ، وغرار سيفي ، … وعزمي ، والمطية ، والقفار\nونفس ، لا تجاورها الدنايا ، … وعرض ، لا يرف عليه عار\nوقوم ، مثل من صحبوا ، كرام … وخيل ، مثل من حملت ، خيار\nوكم بلد شتتناهن فيه … ضحى ، وعلا منابره الغبار\nوخيل ، خف جانبها ، فلما … ذكرنا بينها نسي الفرار\nوكم ملك ، نزعنا الملك عنه ، … وجبار ، بها دمه جبار ؟\nوكن إذا أغرنا على ديار … رجعن ، ومن طرائدها الديار\nفقد أصبحن والدنيا جميعا … لنا دار ، ومن تحويه جار\nإذا أمست نزار لنا عبيدا … فإن الناس كلهم ' نزار '"},{"id":"diwan-abufiras:100","bookId":"diwan-abufiras","type":"poem","seq":100,"chapter":"البحر: كامل تام","title":"ويد يراها الدهر غير ذميمة ،","page":"","text":"ويد يراها الدهر غير ذميمة ، … تمحو إساءته إلي وتغفر\nأهدت إلي مودة من صاحب … تزكو المودة في ثراه ، وتثمر\nعلقت يدي منه بعلق مضنة … مما يصان على الزمان ويدخر\nإني عليك ' أبا حصين ' ، عاتب … والحر يحتمل الصديق ، ويصبر\nوإذا وجدت على الصديق شكوته … سرا إليه وفي المحافل أشكر\nما بال شعري لا ترد جوابه ؟ … سحبان عندك باقل ، لا أعذر"},{"id":"diwan-abufiras:101","bookId":"diwan-abufiras","type":"poem","seq":101,"chapter":"البحر: رجز تام","title":"كأنما الماء عليه الجسر","page":"","text":"كأنما الماء عليه الجسر … درج بياض خط فيه سطر\nكأننا ، لما استتب العبر ، … أسرة ' موسى ' يوم شق"},{"id":"diwan-abufiras:102","bookId":"diwan-abufiras","type":"poem","seq":102,"chapter":"البحر: خفيف تام","title":"قد عرفنا مغزاك ، يا عيار","page":"","text":"قد عرفنا مغزاك ، يا عيار … وتلظت ، كما أردت ، النار\nلم أزل ثابتا على الهجر حتى … خف صبري ، وقلت الأنصار\nوإذا أحدث الحبيبان أمرا … كان فيه على المحب الخيار"},{"id":"diwan-abufiras:103","bookId":"diwan-abufiras","type":"poem","seq":103,"chapter":"البحر: وافر تام","title":"أيا أم الأسير ، سقاك غيث ،","page":"","text":"أيا أم الأسير ، سقاك غيث ، … بكره منك ، ما لقي الأسير !\nأيا أم الأسير ، سقاك غيث ، … تحير ، لا يقيم ولا يسير !\nأيا أم الأسير ، سقاك غيث ، … إلى من بالفدا يأتي البشير ؟\nأيا أم الأسير ، لمن تربى … وقد مت ، الذوائب والشعور ؟\nإذا ابنك سار في بر وبحر ، … فمن يدعو له ، أو يستجير ؟\nحرام أن يبيت قرير عين ! … ولوم أن يلم به السرور !\nتحير ، لا يقيم ولا يسير ! … ولا ولد ، لديك ، ولا عشير\nوغاب حبيب قلبك عن مكان ، … ملائكة السماء به حضور\nليبكك كل يوم صمت فيه … مصابرة وقد حمي الهجير\nليبكك كل ليل قمت فيه … إلى أن يبتدي الفجر المنير !\nليبكك كل مضطهد مخوف … أجرتيه ، وقد قل المجير !\nليبكك كل مسكين فقير … أغثتيه ، وما في العظم زير\nأيا أماه ، كم هم طويل … مضى بك لم يكن منه نصير ! ؟\nأيا أماه ، كم سر مصون … بقلبك ، مات ليس له ظهور\nأيا أماه ، كم بشرى بقربي … أتتك ، ودونها الأجل القصير\nإلى من أشتكي ؟ ولمن أناجي ، … إذا ضاقت بما فيها الصدور ؟\nبأي دعاء داعية أوقى ؟ … بأي ضياء وجه أستنير ؟\nوقد مت ، الذوائب والشعور ؟ … بمن يستفتح الأمر العسير ؟\nنسلى عنك : أنا عن قليل ، … إلى ما صرت في الأخرى ، نصير"},{"id":"diwan-abufiras:104","bookId":"diwan-abufiras","type":"poem","seq":104,"chapter":"البحر: طويل","title":"أراك عصي الدمع شيمتك الصبر ،","page":"","text":"أراك عصي الدمع شيمتك الصبر ، … أما للهوى نهي عليك ولا أمر ؟\nبلى أنا مشتاق وعندي لوعة ، … ولكن مثلي لا يذاع له سر !\nإذا الليل أضواني بسطت يد الهوى … وأذللت دمعا من خلائقه الكبر\nتكاد تضيء النار بين جوانحي … إذا هي أذكتها الصبابة والفكر\nمعللتي بالوصل ، والموت دونه ، … إذا مت ظمآنا فلا نزل القطر !\nحفظت وضيعت المودة بيننا … وأحسن ، من بعض الوفاء لك ، العذر\nوما هذه الأيام إلا صحائف … لأحرفها ، من كف كاتبها بشر\nبنفسي من الغادين في الحي غادة … هواي لها ذنب ، وبهجتها عذر\nتروغ إلى الواشين في ، وإن لي … لأذنا بها ، عن كل واشية ، وقر\nبدوت ، وأهلي حاضرون ، لأنني … أرى أن دارا ، است من أهلها ، قفر\nوحاربت قومي في هواك ، وإنهم … وإياي ، لولا حبك ، الماء والخمر\nفإن كان ما قال الوشاة ولم يكن … فقد يهدم الإيمان ما شيد الكفر\nوفيت ، وفي بعض الوفاء مذلة … لآنسة في الحي شيمتها الغدر\nوقور ، وريعان الصبا يستفزها ، … فتأرن ، أحيانا ، كما يأرن المهر\nتسائلني : ' من أنت ؟ ' ، وهي عليمة ، … وهل بفتى مثلي على حاله نكر ؟\nفقلت ، كما شاءت ، وشاء لها الهوى : … قتيلك ! قالت : أيهم ؟ فهم كثر\nفقلت لها : ' لو شئت لم تتعنتي ، … ولم تسألي عني وعندك بي خبر !\nفقالت : ' لقد أزرى بك الدهر بعدنا ! … فقلت : ' معاذ الله ! بل أنت لا الدهر ،\nوما كان للأحزان ، لولاك ، مسلك … إلى القلب ؛ لكن الهوى للبلى جسر\nوتهلك بين الهزل والجد مهجة … إذا ما عداها البين عذبها الهجر\nفأيقنت أن لا عز ، بعدي ، لعاشق ؛ … وأن يدي مما علقت به صفر\nوقلبت أمري لا أرى لي راحة ، … إذا البين أنساني ألح بي الهجر\nفعدت إلى حكم الزمان وحكمها ، … لها الذنب لا تجزى به ولي العذر\nكأني أنادي دون ميثاء ظبية … على شرف ظمياء جللها الذعر\nتجفل حينا ، ثم تدنو كأنما … تنادي طلا ، بالواد ، أعجزه الحضر\nفلا تنكريني ، يابنة العم ، إنه … ليعرف من أنكرته البدو والحضر\nولا تنكريني ، إنني غير منكر … إذا زلت الأقدام ؛ واستنزل النضر\nوإني لجرار لكل كتيبة … معودة أن لا يخل بها النصر\nوإني لنزال بكل مخوفة … كثير إلى نزالها النظر الشزر\nفأظمأ حتى ترتوي البيض والقنا … وأسغب حتى يشبع الذئب والنسر\nولا أصبح الحي الخلوف بغارة ، … ولا الجيش ما لم تأته قبلي النذر\nويا رب دار ، لم تخفني ، منيعة … طلعت عليها بالردى ، أنا والفجر\nوحي رددت الخيل حتى ملكته … هزيما وردتني البراقع والخمر\nوساحبة الأذيال نحوي ، لقيتها … فلم يلقها جهم اللقاء ، ولا وعر\nوهبت لها ما حازه الجيش كله … ورحت ، ولم يكشف لأثوابها ستر\nولا راح يطغيني بأثوابه الغنى … ولا بات يثنيني عن الكرم\nوما حاجتي بالمال أبغي وفوره ؟ … إذا لم أفر عرضي فلا وفر الوفر\nأسرت وما صحبي بعزل ، لدى الوغى ، … ولا فرسي مهر ، ولا ربه غمر !\nولكن إذا حم القضاء على أمرىء … فليس له بر يقيه ، ولا بحر !\nوقال أصيحابي : ' الفرار أوالردى ؟ ' … فقلت : هما أمران ، أحلاهما مر\nولكنني أمضي لما لا يعيبني ، … وحسبك من أمرين خيرهما الأسر\nيقولون لي : ' بعت السلامة بالردى ' … فقلت : أما والله ، ما نالني خسر\nوهل يتجافى عني الموت ساعة ، … إذا ما تجافى عني الأسر والضر ؟\nهو الموت ، فاختر ما علا لك ذكره ، … فلم يمت الإنسان ما حيي الذكر\nولا خير في دفع الردى بمذلة … كما ردها ، يوما بسوءته ' عمرو '\nيمنون أن خلوا ثيابي ، وإنما … علي ثياب ، من دمائهم حمر\nوقائم سيفي ، فيهم ، اندق نصله … وأعقاب رمح فيهم حطم الصدر\nسيذكرني قومي إذا جد جدهم ، … ' وفي الليلة الظلماء ، يفتقد البدر '\nفإن عشت فالطعن الذي يعرفونه … وتلك القنا ، والبيض والضمر الشقر\nوإن مت فالإنسان لا بد ميت … وإن طالت الأيام ، وانفسح العمر\nولو سد غيري ، ما سددت ، اكتفوا به ؛ … وما كان يغلو التبر ، لو نفق الصفر\nونحن أناس ، لا توسط عندنا ، … لنا الصدر ، دون العالمين ، أو القبر\nتهون علينا في المعالي نفوسنا ، … ومن خطب الحسناء لم يغلها المهر\nأعز بني الدنيا ، وأعلى ذوي العلا ، … وأكرم من فوق التراب ولا فخر"},{"id":"diwan-abufiras:105","bookId":"diwan-abufiras","type":"poem","seq":105,"chapter":"البحر: مجزوء المتقارب","title":"لأيكمم أذكر ؟","page":"","text":"لأيكمم أذكر ؟ … وفي أيكم أفكر ؟\nوكم لي على بلدتي ، … بكاء ومستعبر ؟\nففي حلب عدتي ، … وعزي ، والمفخر\nوفي ' منبج ' ، من رضا … ه ، أنفس ما أذخر\nومن حبه زلفة ، … بها يكرم المحشر\nوأصبية ، كالفراخ ، … أكبرهم أصغر\nوقوم ألفناهم ، … وغصن الصبا أخضر\nيخيل لي أمرهم … كأنهم حضر\nفحزني لا ينقضي ، … ودمعي ما يفتر\nوما هذه أدمعي ، … ولا ذا الذي أضمر\nولكن أداري الدموع ، … وأستر ما أستر\nمخافة قول الوشا … ة ، مثلك لا يصبر\nأيا غفلتا ، كيف لا … أرجي الذي أحذر ؟\nوماذا القنوط الذي … أراه فأستشعر ؟\nأما من بلاني به ، … على كشفه أقدر ؟\nبلى ، إن لي سيدا … مواهبه أكثر\nوإني غزير الذنوب ، … وإحسانه أغزر\nبذنبي أوردتني ، … ومن فضلك المصدر"},{"id":"diwan-abufiras:106","bookId":"diwan-abufiras","type":"poem","seq":106,"chapter":"البحر: خفيف تام","title":"مغرم ، مؤلم ، جريح ، أسير","page":"","text":"مغرم ، مؤلم ، جريح ، أسير … إن قلبا ، يطيق ذا ، لصبور\nوكثير من الرجال حديد ، … وكثير من القلوب صخور\nقل لمن حل بالشآم طليقا ، … بأبي قلبك الطليق الأسير\nأنا أصبحت لا أطيق حراكا ، … كيف أصبحت أنت يا ' منصور ' ؟"},{"id":"diwan-abufiras:107","bookId":"diwan-abufiras","type":"poem","seq":107,"chapter":"البحر: هزج","title":"أتتني عنك أخبار ،","page":"","text":"أتتني عنك أخبار ، … وبانت منك أسرار\nولاحت لي ، من السلو … ة ، آيات وآثار\nأراها منك بالقلب ، … وللأحشاء أبصار\nإذا ما برد الحب … فما تسخنه النار"},{"id":"diwan-abufiras:108","bookId":"diwan-abufiras","type":"poem","seq":108,"chapter":"البحر: خفيف تام","title":"قمر ، دون حسنه الأقمار ،","page":"","text":"قمر ، دون حسنه الأقمار ، … وكثيب من النقا ، مستعار\nوغزال فيه نفار ، ولا بد … ع فمن شيمة الظباء النفار\nلا أعاصيه في اجتراح المعاصي ، … في هوى مثله تطيب النار\nقد حذرت الملاح دهرا ، ولكن … ساقني ، نحو حبه ، المقدار\nكم أردت السلو فاستعطفتني … رقية من رقاك يا عيار"},{"id":"diwan-abufiras:109","bookId":"diwan-abufiras","type":"poem","seq":109,"chapter":"البحر: مجتث","title":"يا معشر الناس ! هل لي","page":"","text":"يا معشر الناس ! هل لي … مما لقيت مجير ؟\nأصاب غرة قلبي … هذا الغزال الغرير\nفعمر ليلي طويل ، … وعمر نومي قصير\nأسرت مني فؤادي ، … يفديك ذاك الأسير"},{"id":"diwan-abufiras:110","bookId":"diwan-abufiras","type":"poem","seq":110,"chapter":"البحر: خفيف تام","title":"سبق الناس ، في الهوى ، منصور","page":"","text":"سبق الناس ، في الهوى ، منصور … فسواه مكلف ، مغرور\nلحق العود ، ناعما ، فثناه … وهو صعب ، على سواه ، عسير\nإن حب الصبا ، وإن طال ، لا يق … دح فيه ، على الدهور ، دثور\nفهو في أضلع الصغير صغير ، … وهو في أضلع الكبير كبير"},{"id":"diwan-abufiras:111","bookId":"diwan-abufiras","type":"poem","seq":111,"chapter":"البحر: طويل","title":"أيحلو ، لمن لا صبر ينجده ، صبر","page":"","text":"أيحلو ، لمن لا صبر ينجده ، صبر … إذا ما انقضى فكر ألم به فكر ؟\nأممعنة في العذل ، رفقا بقلبه ! … أيحمل ذا قلب ، ولو أنه صخر ؟\nعذيري من اللائي يلمن على الهوى … أما في الهوى ، لو ذقن طعم الهوى عذر ؟\nأطلن عليه اللوم حتى تركنه … وساعته شهر ، وليلته دهر\nومنكرة ما عاينت من شحوبه … ولا عجب ، ما عاينته ، ولا نكر\nويحمد في العضب البلى وهو قاطع … ويحسن في الخيل المسمومة ، الضمر\nوقائلة : ' ماذا دهاك ' ؟ تعجبا … فقلت لها : ' يا هذه أنت والدهر ! '\nأبالبين ؟ أم بالهجر ؟ أم بكليهما … تشارك ، فيما ساءني ، البين والهجر ؟\nيذكرني نجدا حبيب ، بأرضها ، … أيا صاحبي نجواي ، هل ينفع الذكر ؟\nنطاولت الكثبان ، بيني وبينه ، … وباعد ، فيما بيننا ، البلد القفر\nمفاوز لا يعجزن صاحب همة ، … وإن عجزت ، عنها ، الغريرية الصبر\nكأن سفينا ، بين فيد وحاجر ، … يحف به ، من آل قيعانه ، بحر\nعداني عنه : ذود أعداء منهل ، … كثير إلى وراده النظر الشزر\nوسمر أعاد ، تلمع البيض بينهم ، … وبيض أعاد ، في أكفهم السمر\nوقوم ، متى ما ألقهم روي القنا ، … وأرض متى ما أغزها شبع النسر\nوخيل يلوح الخير بين عيونها ، … ونصل ، متى ما شمته نزل النصر\nإذا ما الفتى أذكى مغاورة العدى … فكل بلاد حل ساحتها ثغر\nويوم ، كأن الأرض شابت لهوله ، … قطعت بخيل حشو فرسانها صبر ،\nتسير على مثل الملاء منشرا ، … وآثارها طرز لأطرافها حمر\nأشيعه والدمع من شدة الأسى ، … على خده نظم ، وفي نحره نثر\nوعدت ، وقلبي في سجاف غبيطه ، … ولي لفتات ، نحو هودجه ، كثر\nوفيمن حوى ذاك الحجيج خريدة … لها دون عطف الستر من صونها ستر\nوفي الكم كف يراها عديلها ، … وفي الخدر وجه ليس يعرفه الخدر\nفهل عرفات عارفات بزورها ؟ … وهل شعرت تلك المشاعر والحجر ؟\nأما اخضر من بطنان مكة ما ذوى ؟ … أما أعشب الوادي أما أنبت الصخر ؟\nسقى الله قوما ، حل رحلك فيهم ، … سحائب ، لا قل جداها ، ولا نزر !"},{"id":"diwan-abufiras:112","bookId":"diwan-abufiras","type":"poem","seq":112,"chapter":"البحر: بسيط تام","title":"كيف السبيل إلى طيف يزاوره","page":"","text":"كيف السبيل إلى طيف يزاوره … والنوم ، في جملة الأحباب ، هاجره ؟\nالحب آمره ، والصون زاجره ، … والصبر أول ما تأتي أواخره\nأنا الذي إن صبا أو شفه غزل … فللعفاف ، وللتقوى مآزره\nوأشرف الناس أهل الحب منزلة ، … وأشرف الحب ما عفت سرائره\nما بال ليلي لا تسري كواكبه ، … وطيف عزة لا يعتاد زائره ؟\nمن لا ينام ، فلا صبر يؤازره … ولا خيال ، على شحط ، يزاوره\nيا ساهرا ، لعبت أيدي الفراق به … فالصبر خاذله ، والدمع ناصره\nإن الحبيب الذي هام الفؤاد به ، … ينام عن طول ليل ، أنت ساهره\nما أنس لا أنس ، يوم البين ، موقفنا … والشوق ينهى البكى عني ويأمره\nوقولها ، ودموع العين واكفة : … هذا الفراق الذي كنا نحاذره\nهل أنت ، يا رفقة العشاق ، مخبرتي … عن الخليط الذي زمت أباعره ؟\nوهل رأيت ، أمام الحي ، جارية … كالجؤذر الفرد ، تقفوه جآذره ؟\nوأنت ، يا راكبا ، يزجي مطيته … يستطرق الحي ليلا ، أو يباكره\nإذا وصلت فعرض بي وقل لهم : … هل واعد الوعد يوم البين ذاكره ؟\nما أعجب الحب يمسي طوع جارية … في الحي من عجزت عنه مساعره\nويتقي الحي من جاء وغادية … كيف الوصول إذا ما نام سامره ؟\nيا أيها العاذل الراجي إنابته ، … والحب قد نشبت فيه أظافره ،\nلا تشغلن ؛ فما تدري بحرقته ، … أأنت عاذله ؟ أم أنت عاذره ؟\nوراحل أوحش الدنيا برحلته ، … وإن غدا معه قلبي يسايره\nهل أنت مبلغه عني بأن له … ودا ، تمكن في قلبي يجاوره ؟\nوأنني من صفت منه سرائره ، … وصح باطنه ، منه ، وظاهره ؟\nوما أخوك الذي يدنو به نسب ، … لكن أخوك الذي تصفو ضمائره\nوأنني واصل من أنت واصله ، … وأنني هاجر من أنت هاجره\nولست واجد شيء أنت عادمه ، … ولست غائب شيء أنت حاضره\nوافى كتابك ، مطويا على نزه ، … يحار سامعه فيه ، وناظره\nفالعين ترتع فيما خط كاتبه ، … والسمع ينعم فيما قال شاعره\nفإن وقفت ، أمام الحي أنشده ، … ود الخرائد لو تقنى جواهره\n' أبا الحصين ' وخير القول أصدقه ، … أنت الصديق الذي طابت مخابره\nلولا اعتذار أخلائي بك انصرفوا … بوجه خزيان لم تقبل معاذره\nأين الخليل الذي يرضيك باطنه ، … مع الخطوب ، كما يرضيك ظاهره ؟\nأما الكتاب ، فإني لست أقرؤه … إلا تبادر من دمعي بوادره\nيجري الجمان ، كما يجري الجمان به ، … وينشر الدر ، فوق الدر ، ناثره\nأنا الذي لا يصيب الدهر عترته ، … ولا يبيت على خوف مجاوره\nيمسي وكل بلاد حلها وطن ، … وكل قوم ، غدا فيهم ، عشائره\nوما تمد له الأطناب في بلد ، … إلا تضعضع باديه وحاضره\nلي التخير ، مشتطا ومنتصفا ، … وللأفاضل ، بعدي ، ما أغادره\nوكيف تنتصف الأعداء من رجل … ألعز أوله ، والمجد آخره\nزاكي الأصول ، كريم النبعتين ؛ ومن … زكت أوائله طابت أواخره\nفمن ' سعيد بن حمدان ' ولادته ، … ومن ' علي بن عبد الله ' سائره !\nألقائل ، الفاعل ، المأمون نبوته … والسيد الأيد ، الميمون طائره\nبنى لنا العز ، مرفوعا دعائمه ، … وشيد المجد ، مشتدا مرائره\nفما فضائلنا إلا فضائله ، … ولا مفاخرنا إلا مفاخره\nلقد فقدت أبي ، طفلا ، فكان أبي ، … من الرجال ، كريم العود ، ناضره\nفهو ابن عمي دنيا ، حين أنسبه … لكنه لي مولى لا أناكره\nما زال لي نجوة ، مما أحاذره ، … لا زال ، في نجوة ، مما يحاذره\n … منه ، وعمر للإسلام عامره\nهذا كتاب مشوق القلب مكتئب … لم يأل ناظمه ، جهدا ، وناثره\nوقد سمحت غداة البين ، مبتدئا … من الجواب ، بوعد أنت ذاكره\nبقيت ، ماغردت ورق الحمام ، وما … استهل من مونق الوسمي باكره\nحتى تبلغ أقصى ما تؤمله ، … من الأمور ، وتكفى ما تحاذره"},{"id":"diwan-abufiras:113","bookId":"diwan-abufiras","type":"poem","seq":113,"chapter":"البحر: طويل","title":"وظبي غرير ، في فؤادي كناسه ،","page":"","text":"وظبي غرير ، في فؤادي كناسه ، … إذا اكتنس العين الفلاة وحورها\nتقر له بيض الظباء وأدمها … ويحكيه ، في بعض الأمور ، غريرها\nفمن خلقه لباتها ونحورها ، … ومن خلقه عصيانها ونفورها"},{"id":"diwan-abufiras:114","bookId":"diwan-abufiras","type":"poem","seq":114,"chapter":"البحر: طويل","title":"ألا ما لمن أمسى يراك وللبدر ،","page":"","text":"ألا ما لمن أمسى يراك وللبدر ، … وما لمكان أنت فيه وللقطر\nتجللت بالتقوى ، وأفردت بالعلا ، … وأهلت للجلى ، وحليت بالفخر\nوقلدتني ، لما ابتدأت بمدحتي ، … يدأ لا أوفي شكرها ، أبد الدهر\nفإن أنا لم أمنحك صدق مودتي … فما لي إلى المجد المؤثل من عذر\nأيا بن الكرام الصيد ، جاءت كريمة : … ' أيا بن الكرام الصيد والسادة الغر '\nفضلت بها أهل القريض ، فأصبحت … تحية أهل البدو ، مؤنسة الحضر\nومثلك معدوم النظير من الورى … وشعرك معدوم الشبيه من الشعر\nكأن على ألفاظه ، ونظامه … بدائع ما حاك الربيع من الزهر\nتنفس فيه الروض فاخضل بالندى … وهب نسيم الروض يخبر بالفجر\nإلى الله أشكو من فراقك لوعة ، … طويت لها ، مني الضلوع ، على جمر\nوحسرة مرتاح إذا اشتاق قلبه ، … تعلل بالشكوى وعاد إلى الصبر\nفعد يا زمان القرب ، في خير عيشة ، … وأنعم بال ، ما بدا كوكب دري ،\nوعش ' يابن نصر ' ما استهلت غمامة ، … تروح إلى عز وتغدو على نصر"},{"id":"diwan-abufiras:115","bookId":"diwan-abufiras","type":"poem","seq":115,"chapter":"البحر: خفيف تام","title":"مستجير الهوى بغير مجير ،","page":"","text":"مستجير الهوى بغير مجير ، … ومضام الهوى بغير نصير\nما لمن وكل الهوى مقلتيه … بانسكاب وقلبه بزفير ؟ !\nفهو ما بين عمر ليل طويل ، … يتلظى ، وعمر نوم قصير\nلا أقول : المسير أر ق عيني ! … قد تناهى البلاء ، قبل المسير !\nيا كثيبا ، من تحت غصن رطيب ، … يتثنى ، من تحت بدر منير !\nشد ما غيرتك بعدي ، الليالي … يا قليل الوفا ، قليل النظير\nلك وصفي ، وفيك شعري ؛ ولا أع … رف وصف المؤارة العيسجور\nولقلبي من حسن وجهك شغل … عن هوى قاصرات تلك القصور\nقد منحت الرقاد عين خلي … بات خلوا مما يجن ضميري\nلا بلا الله من أحب بحب ، … وشفى كل عاشق مهجور\nيا أخي ' يا أبا زهير ' ألي عن … دك عون على الغزال الغرير ؟\nإن لي ، مذء نأيت ، جسم مريض … وبكا ثاكل ، وذل أسير\nلم تزل مشتكاي ، في كل أمر ، … ومعيني ، وعدتي ، ونصيري\nوردت منك ، يا بن عمي ، هدايا … تتهادى في سندس ، وحرير\nبفواف ، ألذ من بارد الما … ء ، ولفظ كاللؤلؤ المنثور\nمحكم ، قصر ' الفرزدق ' و' الأخ … طل عنه ، وفاق شعر جرير\nأنت ليث الوغى ، وحتف الأعادي … وغياث الملهوف والمستجير\nطلت ، في الضرب للطلى عن شبيه … وتعاليت ، في العلا ، عن نظير\nكنت جربتني ، وأنت كثير ال … كيس ، طب بكل أمر كبير\nوإذا كنت ، ' يابن عمي ' ، قنوعا … بجوابي ، قنعت بالميسور"},{"id":"diwan-abufiras:116","bookId":"diwan-abufiras","type":"poem","seq":116,"chapter":"البحر: وافر تام","title":"عذيري من طوالع في عذاري ،","page":"","text":"عذيري من طوالع في عذاري ، … ومن رد الشباب المستعار !\nوثوب ، كنت ألبسه ، أنيق … أجرر ذيله ، بين الجواري\nوما زادت على العشرين سني … فما عذر المشيب إلى عذاري ؟\nوما استمتعت من داعي التصابي … إلى أن جاءني داعي الوقار\nأيا شيبي ، ظلمت ! ويا شبابي … لقد جاورت ، منك ، بشر جار !\nيرحل كل من يأوي إليه … ويختمها بترحيل الديار\nأمرت بقصه ، وكففت عنه ، … وقر على تحمله قراري\nوقلت : الشيب أهون ما ألاقي … من الدنيا وأيسر ما أداري !\nولا يبقى رفيقي الفجر حتى … يضم إليه منبلج النهار '\n' وإني ما فجعت به لألقى … به ملقى العثار من الشعار '\nوكم من زائر بالكره مني … كرهت فراقه بعد المزار !\nمتى أسلو بلا خل وصول … يوافقني ، ولا قدح مدار ؟\nوكنت ، إذا الهموم تناوبتني ، … فزعت من الهموم إلى القفار\nأنخت وصاحباي بذي طلوح … طلائح ، شفها وخد القفار\nولا ماء سوى نطف الأداوي ، … ولا زاد سوى القنص المثار\nفلما لاح بعد الأين سلع ، … ذكرت منازلي وعرفت داري\nألم بنا ، وجنح الليل داج ، … خيال زار وهنا من نوار\nأباخلة علي ، وأنت جار ، … وواصلة على بعد المزار !\nتلاعب بي ، على هوج المطايا ، … خلائق لا تقر على الصغار\nونفس ، دون مطلبها الثريا … وكف دونها فيض البحار\nأرى نفسي تطالبني بأمر … قليل ، دون غايته ، اقتصاري\nوما يغنيك من همم طوال … إذا قرنت بأعمار قصار ؟\nومعتكف على حلب بكي ، … يقوت عطاش آمال غزار\nيقول لي : ' انتظر فرجا ' ومن لي … بأن الموت ينتظر انتظاري ؟ !\nعلي لكل هم ، كل عيس … أمون الرحل موخدة القفار\nوخراج من الغمرات خرق ، … أبو شبلين ، محمي الذمار\nشديد تجنب الآثام واف ، … على علاته ، عف الإزار\nفلا نزلت بي الجيران إن لم … أجاورها مجاورة البحار\n … أصاحبها بمأمون الفرار\nولا صحبتني الأملاك إن لم … أصبحها بملتف الغبار\nبجيش لا يحل بهم مغير … ورأي لا يغبهم مغار\nشددت على الحمامة كور رحل … بعيد حله ، دون اليسار\nتحف به الأسنة ، والعوالي ، … ومضمرة المهاري ، والمهاري\nيعدن ، بعيد طول الصون ، سعيا … لما كلفن من بعد المغار\nوتخفق حولي الرايات حمرا ، … وتتبعني الخضارم من ' نزار '\nوإن طرقت بداهية نآد … تدافعها الرجال بكل جار\nعزيز حيث حط السير رحلي ، … تداريني الأنام ولا أداري !\nوأهلي من أنخت إليه عيسي ، … وداري حيث كنت من الديار"},{"id":"diwan-abufiras:117","bookId":"diwan-abufiras","type":"poem","seq":117,"chapter":"البحر: هزج","title":"تواعدنا بآذار","page":"","text":"تواعدنا بآذار … لمسعى غير مختار\nوقمنا ، نسحب الريط ، … إلى حانة خمار ؛\nفلم ندر ، وقد فاحت … لنا من جانب الدار\nبخمار ، من القوم ، … نزلنا ، أم بعطار ؟\nفلما ألبس الليل ، … لنا ثوبا من القار\nوقلنا : أوقد النار … لطراق وزوار\nوجا خاصرة الدن … فأغنانا عن النار\nوما في طلب اللهو ، … على الفتيان ، من عار !"},{"id":"diwan-abufiras:118","bookId":"diwan-abufiras","type":"poem","seq":118,"chapter":"البحر: وافر تام","title":"صبرت على اختيارك واضطراري","page":"","text":"صبرت على اختيارك واضطراري … وقل ، مع الهوى ، فيك انتصاري\nوكان يعاف حمل الضيم قلبي ، … فقر على تحمله قراري\nفديتك ، طال ظلمك واحتمالي … كما كثرت ذنوبك واعتذاري"},{"id":"diwan-abufiras:119","bookId":"diwan-abufiras","type":"poem","seq":119,"chapter":"البحر: مجزوء الكامل","title":"ما آن أن أرتاع للش","page":"","text":"ما آن أن أرتاع للش … يب ، المفوف في عذاري ؟\nوأكف عن سبل الضلا … ل ، وأكتسي ثوب الوقار\nأم قد أمنت الحادثا … ت من الغوادي والسواري\nإني أعوذ ، بحسن عف … والله ، من سوء اختياري"},{"id":"diwan-abufiras:120","bookId":"diwan-abufiras","type":"poem","seq":120,"chapter":"البحر: مجزوء الرمل","title":"هل ترى النعمة دامت","page":"","text":"هل ترى النعمة دامت … لصغير أو كبير ؟\nأو ترى أمرين جاءا … أولا مثل أخير\nإنما تجري التصاري … ف بتقليب الدهور\nففقير من غني ؛ … وغني من فقير !"},{"id":"diwan-abufiras:121","bookId":"diwan-abufiras","type":"poem","seq":121,"chapter":"البحر: كامل تام","title":"من أين للرشإ ، الغرير ، الأحور ،","page":"","text":"من أين للرشإ ، الغرير ، الأحور ، … في الخد ، مثل عذاره المتحدر ؟ !\nقمر ، كأن بعارضيه كليهما … مسكا ، تساقط فوق ورد أحمر"},{"id":"diwan-abufiras:122","bookId":"diwan-abufiras","type":"poem","seq":122,"chapter":"البحر: بسيط تام","title":"ووارد مورد أنسا ، يؤكده","page":"","text":"ووارد مورد أنسا ، يؤكده … صدوره عن سليم الورد والصدر\nشدت سحائبه منه على نزه … تقسم الحسن بين السمع والبصر\nعذوبة ، صدرت عن منطق جدد ؛ … كالماء يخرج ينبوعا من الحجر\nوروضة من رياض الفكر ، دبجها … صوب القرائح لا صوب من المطر\nكأنما نشرت أيدي الربيع بها … بردا من الوشي أو ثوبا من الحبر"},{"id":"diwan-abufiras:123","bookId":"diwan-abufiras","type":"poem","seq":123,"chapter":"البحر: متقارب تام","title":"ولي منة في رقاب الضباب ،","page":"","text":"ولي منة في رقاب الضباب ، … وأخرى تخص بني جعفر\nعشية روحن من ' عرقة ' … وأصبحن فوضى ، على شيزر\nوقد طال ما وردت ' بالجباة ' … وعاودت الماء في تدمر\nقددن البقيعة ، قد الأدي … م ، والغرب في شبه الأشقر\nوجاوزن ' حمص ' ؛ فلم ينتظر … ن على مورد أو على مصدر\nوبالرستن استلبت موردا ، … كورد الحمامة أو أنزر\nوجزن المروج ، وقرني حماة … و' شيزر ' ، والفجر لم يسفر\nوغامضت الشمس إشراقها … فلفت كفرطاب بالعسكر\nولاقت بها عصب الدارعي … ن بكل منيع الحمى مسعر\nعلى كل سابقة بالرديف ، … وكل شبيه بها مجفر\nولما اعتفرن ولما عرقن … خرجن ، سراعا ، من العثير\nننكب عنهن فرسانهن ، … ونبدأ بالأخير الأخير\nفلما سمعت ضجيج النسا … ء ناديت : ' حار ' ، ألا فاقصر !\nأ' حارث ' من صافح ، غافر … لهن ، إذا أنت لم تغفر ؟ !\nرأى ابن عليان ما سره … فقلت : رويدك لا تسرر !\nفإني أقوم بحق الجوا … ر ثم أعود إلى العنصر"},{"id":"diwan-abufiras:124","bookId":"diwan-abufiras","type":"poem","seq":124,"chapter":"البحر: طويل","title":"ويوم جلا فيه الربيع بياضه","page":"","text":"ويوم جلا فيه الربيع بياضه … بأنواع حلي ، فوق أثوابه الخضر\nكأن ذيول الجلنار ، مطلة ، … فضول ذيول الغانيات من الأزر"},{"id":"diwan-abufiras:125","bookId":"diwan-abufiras","type":"poem","seq":125,"chapter":"البحر: طويل","title":"ووالله ، ما أضمرت في الحب سلوة ،","page":"","text":"ووالله ، ما أضمرت في الحب سلوة ، … ووالله ، ماحدثت نفسي بالصبر\nوإنك في عيني ، لأبهى من الغنى ، … وإنك ، في قلبي ، لأحلى من النصر\nفيا حكمي المأمول جرت مع الهوى ! … وياثقتي المأمون ، خنت مع الدهر !"},{"id":"diwan-abufiras:126","bookId":"diwan-abufiras","type":"poem","seq":126,"chapter":"البحر: طويل","title":"سأثني على تلك الثنايا ، لأنني","page":"","text":"سأثني على تلك الثنايا ، لأنني … أقول على علم ، وأنطق عن خبر\nوأنصفها ، لا أكذب الله ، أنني … "},{"id":"diwan-abufiras:127","bookId":"diwan-abufiras","type":"poem","seq":127,"chapter":"البحر: بسيط تام","title":"يا طيب ليلة ميلاد ، لهوت بها","page":"","text":"يا طيب ليلة ميلاد ، لهوت بها … بأحور ، ساحر العينين ، ممكور\nوالجو ينشر درا ، غير منتظم ، … والأرض بارزة في ثوب كافور\nوالنرجس الغض يحكي حسن منظره … صفراء صافية في كأس بلور"},{"id":"diwan-abufiras:128","bookId":"diwan-abufiras","type":"poem","seq":128,"chapter":"البحر: وافر تام","title":"ولي في كل يوم منك عتب ولي في كل يوم منك عتب","page":"","text":"ولي في كل يوم منك عتب ولي في كل يوم منك عتب … أقوم به مقام الاعتذار\nحملت جفاك ، لا جلدا ، ولكن … صبرت على اختيارك واضطراري"},{"id":"diwan-abufiras:129","bookId":"diwan-abufiras","type":"poem","seq":129,"chapter":"البحر: وافر تام","title":"جنى جان ، وأنت عليه حان ،","page":"","text":"جنى جان ، وأنت عليه حان ، … وعاد ، فعدت بالكرم الغزير\nصبرت عليه حتى جاء ، طوعا ، … إليك ، وتلك عاقبة الصبور\nفإن تك عدلة في الجسم كانت … فما عدل الضمير عن الضمير\nومثل ' أبي فراس ' من تجافى … له عن فعله ، مثل الأمير"},{"id":"diwan-abufiras:130","bookId":"diwan-abufiras","type":"poem","seq":130,"chapter":"البحر: طويل","title":"بكيت ، فلما لم أر الدمع نافعي ،","page":"","text":"بكيت ، فلما لم أر الدمع نافعي ، … رجعت إلى صبر ، أمر من الصبر\nوقدرت أن الصبر ، بعد فراقهم ، … يساعدني ، وقتا ، فعزيت عن صبري"},{"id":"diwan-abufiras:131","bookId":"diwan-abufiras","type":"poem","seq":131,"chapter":"البحر: كامل تام","title":"ما زال معتلج الهموم بصدره","page":"","text":"ما زال معتلج الهموم بصدره … حتى أباحك ما طوى من سره\nأضمرت حبك ، والدموع تذيعه ، … وطويت وجدك ، والهوى في نشره\nترد الدموع ، لما تجن ضلوعه ، … تترى إلى وجناته أو نحره\nمن لي بعطفة ظالم ، من شأنه … نسيان مشتغل اللسان بذكره ؟\nيا ليت مؤمنه سلوى - ما دعت … ورق الحمام - مؤمني من هجره\nمن لي برد الدمع ، قسرا ، والهوى … يغدو عليه ، مشمرا ، في نصره ؟\nأعيا علي أخ ، وثقت بوده ، … وأمنت في الحالات عقبى غدره\nوخبرت هذا الدهر خبرة ناقد … حتى أنست بخيره وبشره\nلا أشتري بعد التجرب صاحبا … إلا وددت بأنني لم أشره\nمن كل غدار يقر بذنبه … فيكون أعظم ذنبه في عذره\nويجيء ، طورا ، ضره في تفعه ، … جهلا ، وطورا ، نفعه في ضره\nفصبرت لم أقطع حبال وداده … وسترت منه ، مااستطعت ، بستره\nوأخ أطعت فما رأى لي طاعتي … حتى خرجت ، بأمره ، عن أمره\nوتركت حلو العيش لم أحفل به … لما رأيت أعزه في مره\nوالمرء ليس ببالغ في أرضه ، … كالصقر ليس بصائد في وكره\nأنفق من الصبر الجميل ، فإنه … لم يخش فقرا منفق من صبره\nواحلم وإن سفه الجليس ، وقل له … حسن المقال إذا أتاك بهجره\nوأحب إخواني إلي أبشهم … بصديقه في سره أو جهره\nلا خير في بر الفتى ما لم يكن … أصفى مشارب بره في بشره\nألقى الفتى فأريد فائض بشره … وأجل أن أرضى بفائض بره\nيارب مضطغن الفؤاد ، لقيته … بطلاقة ، فسللت ما في صدره"},{"id":"diwan-abufiras:132","bookId":"diwan-abufiras","type":"poem","seq":132,"chapter":"البحر: طويل","title":"وما كنت أخشى أن أبيت وبيننا","page":"","text":"وما كنت أخشى أن أبيت وبيننا … خليجان و' الدرب ' الأشم و' آلس '\nولا أنني أستصحب الصبر ساعة … ولي عنك مناع ودونك حابس\nينافسني فيك الزمان وأهله … وكل زمان لي عليك منافس\nشريتك من دهري بذي الناس كلهم … فلا أنا مبخوس ولا الدهر باخس\nوملكتك النفس النفيسة طائعا ، … وتبذل للمولى النفوس النفائس\nتشوقني الأهل الكرام وأوحشت … مواكب بعدي عندهم ومجالس\nوربتما زان الأماجد ماجد ، … وربتما زان الفوارس فارس !\nرفعت على الحساد نفسي ؛ وهل هم … وما جمعوا لو شئت إلا فرائس ؟\nأيدرك ما أدركت إلا ابن همة … يمارس في كسب العلى ما أمارس ؟\nيضيق مكاني عن سواي لأنني … على قمة المجد المؤثل جالس\nسبقت وقومي بالمكارم والعلا … وإن زعمت من آخرين المعاطس"},{"id":"diwan-abufiras:133","bookId":"diwan-abufiras","type":"poem","seq":133,"chapter":"البحر: بسيط تام","title":"سقى ثرى ' حلب ' ما دمت ساكنها","page":"","text":"سقى ثرى ' حلب ' ما دمت ساكنها … يا بدر ، غيثان منهل ومنبجس\nأسير عنها وقلبي في المقام بها ، … كأن مهري لثقل السير محتبس\nهذا ولولا الذي في قلب صاحبه … من البلابل لم يقلق به فرس\nكأنما الأرض والبلدان موحشة ، … وربعها دونهن العامر الأنس\nمثل الحصاة التي يرمى بها أبدا … إلى السماء فترقى ثم تنعكس"},{"id":"diwan-abufiras:134","bookId":"diwan-abufiras","type":"poem","seq":134,"chapter":"البحر: بسيط تام","title":"لمن أعاتب ؟ ما لي ؟ أين يذهب بي ؟","page":"","text":"لمن أعاتب ؟ ما لي ؟ أين يذهب بي ؟ … قد صرح الدهر لي بالمنع والياس\nأبغي الوفاء بدهر لا وفاء له ، … كأنني جاهل بالدهر والناس !"},{"id":"diwan-abufiras:135","bookId":"diwan-abufiras","type":"poem","seq":135,"chapter":"البحر: كامل تام","title":"لما رأت أثر السنان بخده","page":"","text":"لما رأت أثر السنان بخده … ظلت تقابله بوجه عابس !\nخلف السنان به موقع لثمها ، … بئس الخلافة للمحب البائس !"},{"id":"diwan-abufiras:136","bookId":"diwan-abufiras","type":"poem","seq":136,"chapter":"البحر: كامل تام","title":"ما أنس قولتهن ، يوم لقينني :","page":"","text":"ما أنس قولتهن ، يوم لقينني : … ' أزرى السنان بوجه هذا البائس ! '\nقالت لهن ، وأنكرت ما قلنه : … أجميعكن على هواه منافسي ؟\nإني ليعجبني ، إذا عاينته ، … أثر السنان بصحن خد الفارس"},{"id":"diwan-abufiras:137","bookId":"diwan-abufiras","type":"poem","seq":137,"chapter":"البحر: كامل تام","title":"المرء رهن مصائب لا تنقضي","page":"","text":"المرء رهن مصائب لا تنقضي … حتى يوارى جسمه في رمسه\nفمؤجل يلقى الردى في أهله ، … ومعجل يلقى الردى في نفسه"},{"id":"diwan-abufiras:138","bookId":"diwan-abufiras","type":"poem","seq":138,"chapter":"البحر: مخلع البسيط","title":"تناهض القوم للمعالي","page":"","text":"تناهض القوم للمعالي … لما رأوا نحوها نهوضي\nتكلفوا المكرمات ، كدا ، … تكلف الشعر بالعروض"},{"id":"diwan-abufiras:139","bookId":"diwan-abufiras","type":"poem","seq":139,"chapter":"البحر: هزج","title":"أيا قلبي ، أما تخشع ؟","page":"","text":"أيا قلبي ، أما تخشع ؟ … ويا علمي ، أما تنفع ؟\nأما حقي بأن أنظ … ر للدنيا ، وما تصنع ؟\nأما شيعت أمثالي … إلى ضيق من المضجع\nأما أعلم أن لا ب … د لي من ذلك المصرع ؟\nأيا غوثاه ، يا الل … ه هذا الأمر ما أفظع ! !"},{"id":"diwan-abufiras:140","bookId":"diwan-abufiras","type":"poem","seq":140,"chapter":"البحر: طويل","title":"أبى غرب هذا الدمع إلا تسرعا","page":"","text":"أبى غرب هذا الدمع إلا تسرعا … ومكنون هذا الحب إلا تضوعا\nوكنت أرى أني مع الحزم واحد ، … إذا شئت لي ممضى وإن شئت مرجعا\nفلما استمر الحب في غلوائه ، … رعيت مع المضياعة الحب ما رعى\nفحزني حزن الهائمين مبرحا ، … وسري سر العاشقين مضيعا\nخليلي ، لم لا تبكياني صبابة ، … أأبدلتما بالأجرع الفرد أجرعا ؟\nعلي ، لمن ضنت علي جفونه … غوارب دمع يشمل الحي أجمعا\nوهبت شبابي ، والشباب مضنة ، … لأبلج من أبناء عمي ، أروعا !\nأبيت ، معنى ، من مخافة عتبه ، … وأصبح ، محزونا ، وأمسي ، مروعا !\nفلما مضى عصر الشبيبة كله ، … وفارقني شرخ الشباب ، مودعا\nتطلبت بين الهجر والعتب فرجة ، … فحاولت أمرا ، لا يرام ، ممنعا\nوصرت إذا ما رمت في الخير لذة … تتبعتها بين الهموم ، تتبعا\nوها أنا قد حلى الزمان مفارقي ، … وتوجني بالشيب تاجا مرصعا\nفلو أنني مكنت مما أريده … من العيش ، يوما ، لم يجد في موضعا !\nأما ليلة تمضي ولا بعض ليلة ! … أسر بها هذا الفؤاد المفجعا ؟\nأما صاحب فرد يدوم وفاؤه ! … فيصفي لمن أصفى ويرعى لمن رعى ؟\nأفي كل دار لي صديق أوده ، … إذا ما تفرقنا حفظت وضيعا ؟\nأقمت بأرض الروم ، عامين ، لا أرى … من الناس محزونا ولا متصنعا\nإذا خفت من أخوالي الروم خطة … تخوفت من أعمامي العرب أربعا\nوإن أوجعتني من أعادي شيمة … لقيت من الأحباب أدهى وأوجعا\nولو قد رجوت الله لا شيء غيره … رجعت إلى أعلى وأملت أوسعا\nلقد قنعوا بعدي من القطر بالندى ، … ومن لم يجد إلا القنوع تقنعا\nوما مر إنسان فأخلف مثله ؛ … ولكن يزجي الناس أمرا موقعا\nتنكر ' سيف الدين ' لما عتبته ، … وعرض بي ، تحت الكلام ، وقرعا\nفقولا له : من أصدق الود أنني … جعلتك مما رابني ، الدهر مفزعا\nولو أنني أكننته في جوانحي … لأورق ما بين الضلوع وفرعا\nفلا تغترر بالناس ، ما كل من ترى … أخوك إذا أوضعت في الأمر أوضعا\nولا تتقلد ما يروعك حليه … تقلد ، إذا حاربت ، ما كان أقطعا !\nولا تقبلن القول من كل قائل ! … سأرضيك مرأى لست أرضيك مسمعا\n … ولله صنع قد كفاني التصنعا\nأراني طريق المكرمات ، كما أرى ، … علي وأسماني على كل من سعى\nفإن يك بطء مرة فلطالما … تعجل ، نحوي ، بالجميل وأسرعا\nوإن يحف في بعض الأمور فانني … لأشكره النعمى التي كان أودعا\nوإن يستجد الناس بعدي فلم يزل … بذاك البديل ، المستجد ، ممتعا !"},{"id":"diwan-abufiras:141","bookId":"diwan-abufiras","type":"poem","seq":141,"chapter":"البحر: بسيط تام","title":"وما تعرض لي يأس سلوت به","page":"","text":"وما تعرض لي يأس سلوت به … إلا تجدد لي في إثره طمع\nولا تناهبت في شكوى محبته … إلا وأكثر مما قلت ما أدع"},{"id":"diwan-abufiras:142","bookId":"diwan-abufiras","type":"poem","seq":142,"chapter":"البحر: مجزوء الكامل","title":"ما للعبيد من الذي","page":"","text":"ما للعبيد من الذي … يقضي به الله امتناع\nذدت الأسود عن الفرا … ئس ، ثم تفرسني الضباع"},{"id":"diwan-abufiras:143","bookId":"diwan-abufiras","type":"poem","seq":143,"chapter":"البحر: سريع","title":"المجد بالرقة مجموع ،","page":"","text":"المجد بالرقة مجموع ، … والفضل مرئي ومسموع\nإن بها كل عميم الندى … يداه للجود ينابيع\nوكل مبذول القرى ، بيته ، … على علا العلياء ، ، مرفوع\nلكن أتاني خبر رائع … يضيق عنه السمع والروع\nأن بني عمي ، وحاشاهم ، … شعبهم بالخلف مصدوع\nمالعصا قومي قد شقها … تفارط منهم وتضييع ؟\nبني أبي ، فرق ما بينكم … واش ، على الشحناء مطبوع !\nعودوا إلى أحسن ما كنتم ، … فأنتم الغر المرابيع !\nلا يكمل السؤدد في ماجد ، … ليس له عود ومرجوع\nأنبذل الود لأعدائنا ، … وهو عن الإخوة ممنوع ؟ !\nأو نصل الأبعد من قومنا ، … والنسب الأقرب مقطوع ؟\nلا يثبت العز على فرقة ، … غيرك بالباطل مخدوع !"},{"id":"diwan-abufiras:144","bookId":"diwan-abufiras","type":"poem","seq":144,"chapter":"البحر: طويل","title":"هي الدار من سلمى وهاتي المرابع ،","page":"","text":"هي الدار من سلمى وهاتي المرابع ، … فحتى متى ياعين ، دمعك هامع ؟ !\nألم ينهك الشيب الذي حل نازلا ؟ … وللشيب بعد الجهل للمرء رادع !\nلئن وصلت ' سلمى ' حبال مودتي … فإن وشيك البين ، لا شك ، قاطع\nوإن حجبت عنا النوى ' أم مالك ' … لقد ساعدتها كلة وبراقع !\nوإن ظمئت نفسي إلى طيب ريقها … لقد رويت بالدمع مني المدامع\nوإن أفلت تلك البدور عشية ، … فإن نحوسي بالفراق طوالع\nولما وقفنا للوداع ، غدية ، … أشارت إلينا أعين وأصابع\nوقالت : أتنسى العهد بالجزع واللوى … وما ضمه منا النقا والأجارع ؟\nوأجرت دموعا من جفون لحاظها … شفار ، على قلب المحب قواطع\nفقلت لها : مهلا ! فماالدمع رائعي ، … وما هو للقرم المصمم رائع !\nلئن لم أخل العيس وهي لواغب … حدابير ، من طول السرى ، وظوالع\nفما أنا من ' حمدان ' في الشرف الذي … له منزل بين السماكين طالع"},{"id":"diwan-abufiras:145","bookId":"diwan-abufiras","type":"poem","seq":145,"chapter":"البحر: كامل تام","title":"ولقد أبيت ، وجل ما أدعو به ،","page":"","text":"ولقد أبيت ، وجل ما أدعو به ، … حتى الصباح ، وقد أقض المضجع\nلا هم ، إن أخي لديك وديعة … مني وليس يضيع ما تستودع !"},{"id":"diwan-abufiras:146","bookId":"diwan-abufiras","type":"poem","seq":146,"chapter":"البحر: سريع","title":"محلك الجوزاء ، بل أرفع ،","page":"","text":"محلك الجوزاء ، بل أرفع ، … وصدرك الدهناء ، بل أوسع\nوقلبك الرحب الذي لم يزل ، … للجد والهزل ، به موضع\nرفه بقرع العود سمعا ، غدا … قرع العوالي جل ما يسمع"},{"id":"diwan-abufiras:147","bookId":"diwan-abufiras","type":"poem","seq":147,"chapter":"البحر: طويل","title":"لئن جمعتنا ، غدوة ، أرض ' بالس '","page":"","text":"لئن جمعتنا ، غدوة ، أرض ' بالس ' … فإن لها عندي يدا لا أضيعها\nأحب بلاد الله ، أرض تحلها ، … إلي ؛ ودار تحتويك ربوعها\nأفي كل يوم ، رحلة بعد رحلة … تجرع نفسي ، حسرة ، وتروعها ؟\nفلي ، أبدا ، قلب كثير نزاعه ، … ولي ، أبدا ، نفس قليل نزوعها\nلحى الله قلبا لا يهيم صبابة … إليك ، وعينا لا تفيض دموعها"},{"id":"diwan-abufiras:148","bookId":"diwan-abufiras","type":"poem","seq":148,"chapter":"البحر: مجزوء الكامل","title":"أنظر إلى زهر الربيع ،","page":"","text":"أنظر إلى زهر الربيع ، … والماء في برك البديع ،\nوإذا الرياح جرت علي … ه في الذهاب وفي الرجوع ،\nنثرت على بيض الصفا … ئح بيننا حلق الدروع"},{"id":"diwan-abufiras:149","bookId":"diwan-abufiras","type":"poem","seq":149,"chapter":"البحر: خفيف تام","title":"كيف أرجو الصلاح من أمر قوم","page":"","text":"كيف أرجو الصلاح من أمر قوم … ضيعوا الحزم فيه أي ضياع ؟\nفمطاع المقال غير سديد ، … وسديد المقال غير مطاع"},{"id":"diwan-abufiras:150","bookId":"diwan-abufiras","type":"poem","seq":150,"chapter":"البحر: مجزوء الكامل","title":"من بحر شعرك أغترف ،","page":"","text":"من بحر شعرك أغترف ، … وبفضل علمك أعترف\nأنشدتني ؛ فكأنما … شققت عن در صدف\nشعرا ، إذا ما قسته … بجميع أشعار السلف\nقصرن ، دون قراه تق … صير الحروف عن الألف"},{"id":"diwan-abufiras:151","bookId":"diwan-abufiras","type":"poem","seq":151,"chapter":"البحر: مجزوء الكامل","title":"إني أقول بما علمت","page":"","text":"إني أقول بما علمت … ولا أجور ولا أخيف\nأما علي الجعفري … ي فإنه الحر العفيف\nنسب شريف ، زانه … في أهله خلق شريف"},{"id":"diwan-abufiras:152","bookId":"diwan-abufiras","type":"poem","seq":152,"chapter":"البحر: طويل","title":"أيا ظالما ، أمسى يعاتب منصفا !","page":"","text":"أيا ظالما ، أمسى يعاتب منصفا ! … أتلزمني ذنب المسيء تعجرفا ؟\nبدأت بتنميق العتاب ، مخافة ال … عتاب ، وذكري بالجفا ، خشية الجفا !\nأوافي ، على علات عتبك ، صابرا … وألفى ، على حالات ظلمك ، منصفا\nوكنت ، إذا صافيت خلا ، منحته … بهجرانه وصلا ، ومن غدره وفا\nفهيج بي هذا الكتاب صبابة ، … وجدد لي هذا العتاب تأسفا\nفإن أدنت الأيام دارا بعيدة … شفى القلب مظلوم من العتب واشتفى !\nفإن كنته أقررت بالذنب ، تائبا ، … وإن لم أكن أمسكت عنه ، تألفا !"},{"id":"diwan-abufiras:153","bookId":"diwan-abufiras","type":"poem","seq":153,"chapter":"البحر: مجزوء الوافر","title":"غلام فوق ما أصف ،","page":"","text":"غلام فوق ما أصف ، … كأن قوامه ألف\nإذا ما مال يرعبني … أخاف عليه ينقصف\nوأشفق من تأوده ، … أخاف يذيبه الترف\nسروري عنده لمع ، … ودهري ، كله ، أسف\nوأمري ، كله ، أمم ، … وحبي وحده سرف"},{"id":"diwan-abufiras:154","bookId":"diwan-abufiras","type":"poem","seq":154,"chapter":"البحر: كامل تام","title":"غيري يغيره الفعال الجافي ،","page":"","text":"غيري يغيره الفعال الجافي ، … ويحول عن شيم الكريم الوافي\nلا أرتضي ودا ، إذا هو لم يدم … عند الجفاء ، وقلة الإنصاف\nتعس الحريص ، وقل ما يأتي به … عوضا من الإلحاح والإلحاف\nإن الغني هو الغني بنفسه … ولو أنه عاري المناكب ، حاف\nما كل ما فوق البسيطة كافيا ، … فإذا قنعت فكل شيء كاف\nوتعاف لي طمع الحريص أبوتي ، … ومروءتي ، وفتوتي ، وعفافي\nما كثرة الخيل الجياد بزائدي … شرفا ، ولا عدد السوام الضافي\nخيلي ، وإن قلت ، كثير نفعها … بين الصوارم ، والقنا الرعاف\nومكارمي عدد النجوم ؛ ومنزلي … مأوى الكرام ، ومنزل الأضياف\nلا أقتني لصروف دهري عدة … حتى كأن صروفه أحلافي\nشيم عرفت بهن ، مذ أنا يافع ، … ولقد عرفت بمثلها أسلافي"},{"id":"diwan-abufiras:155","bookId":"diwan-abufiras","type":"poem","seq":155,"chapter":"البحر: مجزوء الرجز","title":"ومرتد بطرة ،","page":"","text":"ومرتد بطرة ، … مسبلة الرفارف\nكأنها مرسلة … من زرد مضاعف"},{"id":"diwan-abufiras:156","bookId":"diwan-abufiras","type":"poem","seq":156,"chapter":"البحر: بسيط تام","title":"بعض الجفاة إلى المجفو مشتاق","page":"","text":"بعض الجفاة إلى المجفو مشتاق … ودون ما أمل المعشوق معتاق\nأعصي الهوى ، وأطيع الرأي في ولد … بعد النصيحة رابت منه أخلاق\nفما نظرت بعين السوء معتمدا … إليه إلا وللأحشاء إطراق\nوما دعاني إلى ما ساءه سخط … إلا ثناني إلى ما شاء إشفاق"},{"id":"diwan-abufiras:157","bookId":"diwan-abufiras","type":"poem","seq":157,"chapter":"البحر: بسيط تام","title":"الحزن مجتمع ، والصبر مفترق ،","page":"","text":"الحزن مجتمع ، والصبر مفترق ، … والحب مختلف ، عندي ومتفق\nولي ، إذا كل عين نام صاحبها ، … عين تحالف فيها الدمع والأرق\nلولاك يا ظبية الإنس ، التي نظرت ، … لما وصلن إلى مكروهي الحدق\nلكن نظرت ، وقد سار الخليط ضحى ، … بناظر كل حسن منه مسترق"},{"id":"diwan-abufiras:158","bookId":"diwan-abufiras","type":"poem","seq":158,"chapter":"البحر: وافر تام","title":"ولما عز دمع العين فاضت","page":"","text":"ولما عز دمع العين فاضت … دماء ، عند ترحال الفريق\nوقد نظمت على خدي سموطا … من الدر المفصل بالعقيق"},{"id":"diwan-abufiras:159","bookId":"diwan-abufiras","type":"poem","seq":159,"chapter":"قصائد","title":"يا أخي قد وهبت ذنب زمان","page":"","text":"يا أخي قد وهبت ذنب زمان … طرقتني صروفه بالمهالك\nلم يهب لي صبابة من رقاد … لم يجد لي فيها بطيف خيالك\nقد قنعنا بذلك النزر منه ، … وغفرنا له الذنوب لذلك"},{"id":"diwan-abufiras:160","bookId":"diwan-abufiras","type":"poem","seq":160,"chapter":"البحر: خفيف تام","title":"يا غلامي ، بل سيدي ، لن أملك ،","page":"","text":"يا غلامي ، بل سيدي ، لن أملك ، … هب لمولاك ، لا عدمتك ، عدلك\nخوف أن يصطفيك غيري بعدي … لا أرى أن أقول قدمت قبلك"},{"id":"diwan-abufiras:161","bookId":"diwan-abufiras","type":"poem","seq":161,"chapter":"البحر: مجزوء الكامل","title":"بالكره مني واختيارك ،","page":"","text":"بالكره مني واختيارك ، … أن لا أكون حليف دارك\nيا تاركي ، إني لذك … رك ، ما حييت ، لغير تارك !\nكن كيف شئت ، فإنني … ذاك المواسي والمشارك"},{"id":"diwan-abufiras:162","bookId":"diwan-abufiras","type":"poem","seq":162,"chapter":"البحر: سريع","title":"أليك أشكو منك ، يا ظالمي ،","page":"","text":"أليك أشكو منك ، يا ظالمي ، … إذ ليس ، في العالم ، معد عليك\nأعانك الله بخير ، أعن … من ليس يشكو منك إلا إليك"},{"id":"diwan-abufiras:163","bookId":"diwan-abufiras","type":"poem","seq":163,"chapter":"البحر: متقارب تام","title":"أيا سافرا ! ورداء الخجل","page":"","text":"أيا سافرا ! ورداء الخجل … مقيم بوجنته ، لم يزل !\nبعيشك ، رد عليك اللثام ! … أخاف عليك جراح المقل\nفما حق حسنك أن يجتلى ، … ولا حق وجهك أن يبتذل\nأمنت عليك صروف الزمان ، … كما قد أمنت علي الملل"},{"id":"diwan-abufiras:164","bookId":"diwan-abufiras","type":"poem","seq":164,"chapter":"البحر: مجتث","title":"ما زلت تسعى بجد ،","page":"","text":"ما زلت تسعى بجد ، … برغم شانيك ، مقبل\nترى لنفسك أمرا ، … وما يرى الله أفضل"},{"id":"diwan-abufiras:165","bookId":"diwan-abufiras","type":"poem","seq":165,"chapter":"البحر: سريع","title":"قد عذب الموت بأفواهنا","page":"","text":"قد عذب الموت بأفواهنا … والموت خير من مقام الذليل\nإنا إلى الله ، لما نابنا ، … وفي سبيل الله خير السبيل !"},{"id":"diwan-abufiras:166","bookId":"diwan-abufiras","type":"poem","seq":166,"chapter":"البحر: مجزوء الكامل","title":"قف في رسوم المستجا","page":"","text":"قف في رسوم المستجا … ب وحي أكناف المصلى !\nف ' الجوسق ' الميمون ، ف ' الس … قيا ' بها ، فالنهر أعلى !\nتلك المنازل ، والملا … عب ، لا أراها الله محلا !\nأوطنتها زمن الصبا ؛ … وجعلت منبج لي محلا\nحيث التفت رأيت ما … ء سابحا ، وسكنت ظلا\nتر دار ' وادي عين قا … صر ' منزلا رحبا ، مطلا\nوتحل بالجسر الجنا … ن ، وتسكن الحصن المعلى\nتجلو عرائسه لنا … هزج الذباب إذا تجلى\nوإذا نزلنا ب ' السوا … جير ' اجتنينا العيش سهلا\nوالماء يفصل بين زه … ر الروض ، في الشطين ، فصلا\nكبساط وشي ، جردت … أيدي القيون عليه نصلا\nمن كان سر بما عرا … ني ، فليمت ضرا وهزلا\nلم أخل ، فيما نابني ، … من أن أعز ، وأن أجلا\nرعت القلوب ، مهابة ، … وملأتها ، فضلا ونبلا\nما غض مني حادث ؛ … والقرم قرم ، حيث حلا\nأنى حللت فإنما … يدعوني السيف المحلى\nفلئن خلصت فإنني … شرق العدا ، طفلا وكهلا\nما كنت إلا السيف ، زا … د على صروف الدهر صقلا\nولئن قتلت ، فإنما … موت الكرام الصيد قتلا\nيغتر بالدنيا الجهو … ل ، وليس في الدنيا مملا !"},{"id":"diwan-abufiras:167","bookId":"diwan-abufiras","type":"poem","seq":167,"chapter":"البحر: مجزوء الرمل","title":"أجملي يا أم عمر و،","page":"","text":"أجملي يا أم عمر و، … زادك الله جمالا\nلا تبيعيني برخص ؛ … إن في مثلي يغالى !\nأنا ، إن جدت بوصل ، … أحسن العالم حالا !"},{"id":"diwan-abufiras:168","bookId":"diwan-abufiras","type":"poem","seq":168,"chapter":"البحر: كامل تام","title":"أأبا العشائر ، إن أسرت فطالما","page":"","text":"أأبا العشائر ، إن أسرت فطالما … أسرت لك البيض الخفاف رجالا !\nلما أجلت المهر ، فوق رؤوسهم ، … نسجت له حمر الشعور عقالا\nيا من إذا حمل الحصان على الوجى … قال : اتخذ حبك التريك نعالا\nما كنت نهزة آخذ ، يوم الوغى ، … لو كنت أوجدت الكميت مجالا\nحملتك نفس حرة وعزائم ، … قصرن من قلل الجبال طوالا\nورأين بطن العير ظهر عراعر ، … والروم وحشا ، والجبال رمالا\nأخذوك في كبد المضايق ، غيلة ، … مثل النساء ، تربب الرئبالا\nألا دعوت أخاك ، وهو مصاقب … يكفي العظيم ، ويدفع ، الأهوالا ؟\nألا دعوت أبا فراس ، إنه … ممن إذا طلب الممنع نالا ؟\nوردت ، بعيد الفوت ، أرضك خيله ، … سرعى ، كأمثال القطا أرسالا\nزلل من الأيام فيك ، يقيله … ملك إذا عثر الزمان أقالا\nما زال ' سيف الدولة ' القرم ، الذي … يلقى العظيم ، ويحمل الأثقالا\nبالخيل ضمرا ، والسيوف قواضبا ، … والسمر لدنا ، والرجال عجالا\nومعود فك العناة ، معاود … قتل العداة ، إذا استغار أطالا\nصفنا ' بخرشنة ' وقطعنا الشتا ، … وبنو البوادي في ' قمير ' حلالا\nوسمت بهم همم إليك منيفة … لكنه حجر الخليج وجالا\nوغدا تزورك بالفكاك خيوله ، … متثاقلات ، تنقل الأبطالا\nإن ابن عمك ليس يغفل ، إنه … ملك الملوك ، وفكك الأغلالا !"},{"id":"diwan-abufiras:169","bookId":"diwan-abufiras","type":"poem","seq":169,"chapter":"البحر: مجزوء الكامل","title":"في الناس إن فتشتهم ،","page":"","text":"في الناس إن فتشتهم ، … من لا يعزك أو تذله\nفاترك مجاملة اللئي … م ، فإن فيها العجز كله"},{"id":"diwan-abufiras:170","bookId":"diwan-abufiras","type":"poem","seq":170,"chapter":"البحر: وافر تام","title":"أيا عجبا لأمر ' : بني قشير ' !","page":"","text":"أيا عجبا لأمر ' : بني قشير ' ! … أراعونا ؛ وقالوا القوم قل\nوكانوا الكثر ، يومئذ ؛ ولكن … كثرنا ، إذ تعاركنا ، وقلوا\nوقال الهام للأجساد : هذا … يفرق يننا إن لم تولوا !\nفولوا ، للقنا والبيض فيهم … وفي جيرانهم نهل وعل\nورحنا بالقلائع ، كل نهد … مطل ، فوقه نهد مطل"},{"id":"diwan-abufiras:171","bookId":"diwan-abufiras","type":"poem","seq":171,"chapter":"البحر: بسيط تام","title":"يا عمر الله سيف الدين مغتبطا ،","page":"","text":"يا عمر الله سيف الدين مغتبطا ، … فكل حادثة يرمى بها جلل\nمن كان من كل مفقود لنا بدلا … فليس منه على حالاته بدل\nيبكي الرجال ، و' سيف الدين ' مبتسم ، … حتى عن ابنك تعطى الصبر ، يا جبل\nلم يجهل القوم منه فضل ما عرفوا … لكن عرفت من التسليم ما جهلوا\nهل تبلغ القمر المدفون رائعة … من المقال ، عليها للأسى حلل ؟\nما بعد فقدك ، في أهل ، ولا ولد ، … ولا حياة ، ولا دنيا ، لنا ، أمل\nيا من أتته المنايا ، غير حافلة ! … أين العبيد وأين الخيل والخول ؟\nأين الليوث ، التي حوليك ، رابضة ؟ … أين الصنائع ؟ أين الأهل ؟ ما فعلوا ؟\nأين السيوف التي يحميك أقطعها ؟ … أين السوابق ؟ أين البيض والأسل ؟\nياويح خالك ! بل يا ويح كل فتى ! … أكل هذا تخطى ، نحوك ، الأجل ؟"},{"id":"diwan-abufiras:172","bookId":"diwan-abufiras","type":"poem","seq":172,"chapter":"البحر: سريع","title":"يا قرح ، لم يندمل الأول !","page":"","text":"يا قرح ، لم يندمل الأول ! … فهل بقلبي لكما محمل ؟\nجرحان ، في جسم ضعيف القوى ، … حيث أصابا فهو المقتل !\nتقاسم الأيام أحبابنا ، … وقسمها الأفضل والأجمل\nوليتها ، إذ أخذت قسمها ، … عن قسمنا تغمض أو تغفل\nوقيت في الآخر من صرفها ال … جائر ، ما جرعك الأول\nففدية المأسور مقبولة ، … وفدية الميت لا تقبل\nلا تعدمن الصبر في حالة ، … فإنه للخلق الأجمل\nوعشت في عز وفي نعمة ، … وجدك المقتبل المقبل"},{"id":"diwan-abufiras:173","bookId":"diwan-abufiras","type":"poem","seq":173,"chapter":"البحر: طويل","title":"نعم ! تلك ، بين الواديين ، الخواتل","page":"","text":"نعم ! تلك ، بين الواديين ، الخواتل … وذلك شاء ، دونهن ، وجامل\nفما كنت ، إذ بانوا ، بنفسك فاعلا … فدونك مت ؛ إن الخليط لزائل\nكأن ابنة القيسي ، في أخواتها ، … خذول ، تراعيها الظباء الخواذل\nقشيرية ، قترية ، بدوية ، … لها ، بين أثناء الضلوع ، منازل\nوهبت سلوي ، ثم جئت أرومه ، … ومن دون ما رمت القنا والقنابل\nهوانا غريب ؛ شزب الخيل والقنا … لنا كتب ، والباترات رسائل\nأغرن على قلبي بخيل من الهوى … فطارد عنهن الغزال المغازل\nبأسهم لفظ ، لم تركب نصالها ، … وأسياف لحظ ، ما جلتها الصياقل\nوقائع قتلى الحب فيها كثيرة ، … ولم يشتهر سيف ، ولا هز ذابل\nأراميتي ! كل السهام مصيبة ؛ … وأنت لي الرامي ؛ وكلي مقاتل\nوإني لمقدام وعندك هائب ، … وفي الحي ' سحبان ' ؛ وعندك ' باقل '\nيضل علي القول ، إن زرت دارها ، … ويعزب عني وجه ما أنا فاعل\nوحجتها العليا ، على كل حالة … فباطلها حق ، وحقي باطل\nتطالبني بيض الصوارم والقنا … بما وعدت حدي في المخايل\nولا ذنب لي ، إن الفؤاد لصارم ، … وإن الحسام المشرفي لفاصل\nوإن الحصان الوالقي لضامر ، … وإن الأصم السمهري لعاسل\nولكن دهرا دافعتني خطوبه … كما دفع الدين الغريم المماطل\nوأخلاف أيام ، إذا ما انتجعتها ، … حلبت بكيات ، وهن حوافل\nولو نيلت الدنيا بفضل منحتها … فضائل تحويها وتبقى فضائل\nولكنهما الأيام ، تجري بما جرت ، … فيسفل أعلاها ، ويعلو الأسافل\nلقد قل أن تلقى من الناس مجملا … وأخشى ، قريبا ، أن يقل المجامل\nولست بجهم الوجه في وجه صاحبي … ولا قائل للضيف : هل أنت راحل ؟\nولكن قراه ما تشهى ، ورفده ، … ولو سأل الأعمار ما هو سائل\nينال اختيار الصفح عن كل مذنب … له عندنا ما لا تنال الوسائل\nلنا عقب الأمر ، الذي في صدوره … تطاول أعناق العدا ، والكواهل\nأصاغرنا ، في المكرمات ، أكابر … أواخرنا ، في المأثرات ، أوائل\nإذا صلت ، يوما ، لم أجد لي مصاولا ؛ … وإن قلت ، يوما ، لم أجد من يقاول !"},{"id":"diwan-abufiras:174","bookId":"diwan-abufiras","type":"poem","seq":174,"chapter":"البحر: بسيط تام","title":"يا من أتانا بظهر الغيب ، قولهم","page":"","text":"يا من أتانا بظهر الغيب ، قولهم … لو شئت ، غاظتكم منا الأقاويل\nلكن أرى أن في الأقوال منقصة … ما لم تسد الأقاويل الأفاعيل"},{"id":"diwan-abufiras:175","bookId":"diwan-abufiras","type":"poem","seq":175,"chapter":"البحر: بسيط تام","title":"أحل بالأرض يخشى الناس جانبها","page":"","text":"أحل بالأرض يخشى الناس جانبها … ولا أسائل أنى يسرح المال\nفهيبتي في طراد الخيل واقعة … والناس فوضى ، ومال الحي إهمال\nكذاك نحن ؛ إذا ما أزمة طرقت … حيا ، بحيث يخاف الناس ، حلال !"},{"id":"diwan-abufiras:176","bookId":"diwan-abufiras","type":"poem","seq":176,"chapter":"البحر: بسيط تام","title":"ألعذر منك ، على الحالات مقبول ؛","page":"","text":"ألعذر منك ، على الحالات مقبول ؛ … والعتب منك ، على العلات ، محمول\nلولا اشتياقي لم أقلق لبعدكم ، … ولا غدا في زماني ، بعدكم ، طول\nوكل منتظر ، إلاك ، محتقر ، … وكل شيء ، سوى لقياك ، مملول !"},{"id":"diwan-abufiras:177","bookId":"diwan-abufiras","type":"poem","seq":177,"chapter":"البحر: طويل","title":"إذا لم يعنك الله فيما ترومه ،","page":"","text":"إذا لم يعنك الله فيما ترومه ، … فليس لمخلوق إليه سبيل\nوإن هو لم ينصرك لم تلق ناصرا … وإن عز أنصار وجل قبيل\nوإن هو لم يرشدك في كل مسلك … ضللت ، ولو أن السماك دليل !"},{"id":"diwan-abufiras:178","bookId":"diwan-abufiras","type":"poem","seq":178,"chapter":"البحر: طويل","title":"مصابي جليل ، والعزاء جميل ،","page":"","text":"مصابي جليل ، والعزاء جميل ، … وظني بأن الله سوف يديل\nجراح ، تحاماها الأساة ، مخوفة ، … وسقمان : باد ، منهما ودخيل\nوأسر أقاسيه ، وليل نجومه ، … أرى كل شيء ، غيرهن ، يزول\nتطول بي الساعات ، وهي قصيرة ؛ … وفي كل دهر لا يسرك طول !\nتناساني الأصحاب ، إلا عصيبة … ستلحق بالأخرى ، غدا ، وتحول !\nومن ذا الذي يبقى على العهد ؟ إنهم ، … وإن كثرت دعواهم ، لقليل !\nأقلب طرفي لا أرى غير صاحب ، … يميل مع النعماء حيث تميل\nوصرنا نرى : أن المتارك محسن ؛ … وأن صديقا لا يضر خليل\nفكل خليل ، هكذا ، غير منصف ! … وكل زمان بالكرام بخيل !\nنعم ، دعت الدنيا إلى الغدر دعوة ، … أجاب إليها عالم ، وجهول\nوفارق عمرو بن الزبير شقيقه ، … وخلى أمير المؤمنين عقيل !\nفيا حسرتا ، من لي بخل موافق … أقول بشجوي ، مرة ، ويقول !\nوإن ، وراء الستر ، أما بكاؤها … علي ، وإن طال الزمان ، طويل !\nفيا أمتا ، لا تعدمي الصبر ، إنه … إلى الخير والنجح القريب رسول !\nويا أمتا ، لا تخطئي الأجر ! إنه … على قدر الصبر الجميل جزيل\nأما لك في ' ذات النطاقين ' أسوة ، … ب ' مكة ' والحرب العوان تجول ؟\nأراد ابنها أخذ الأمان فلم تجب … وتعلم ، علما أنه لقتيل !\nتأسي ! كفاك الله ما تحذرينه ، … فقد غال هذا الناس قبلك غول !\nوكوني كما كانت ب ' أحد ' ' صفية ' … ولم يشف منها بالبكاء غليل !\nولو رد ، يوما ' حمزة الخير ' حزنها … إذا ما علتها رنة وعويل\nلقيت نجوم الأفق وهي صوارم ، … وخضت سواد الليل ، وهو خيول\nولم أرع للنفس الكريمة خلة ، … عشية لم يعطف علي خليل\nولكن لقيت الموت ، حتى تركتها ، … وفيها وفي حد الحسام فلول\nومن لم يوق الله فهو ممزق ! … ومن لم يعز الله ، فهو ذليل !\nومن لم يرده الله ، في الأمر كله ، … فليس لمخلوق إليه سبيل"},{"id":"diwan-abufiras:179","bookId":"diwan-abufiras","type":"poem","seq":179,"chapter":"البحر: وافر تام","title":"ومغض ، للمهابة ، عن جوابي !","page":"","text":"ومغض ، للمهابة ، عن جوابي ! … وإن لسانه العضب الصقيل\nأطلت عتابه ، عنتا وظلما ، … فجمجم ، ثم قال : ' كما تقول ! '"},{"id":"diwan-abufiras:180","bookId":"diwan-abufiras","type":"poem","seq":180,"chapter":"البحر: طويل","title":"وما لي لا أثني عليك ، وطالما","page":"","text":"وما لي لا أثني عليك ، وطالما … وفيت بعهدي ، والوفاء قليل ؟\nوأوعدتني حتى إذا ما ملكتني … صفحت ، وصفح المالكين جميل !"},{"id":"diwan-abufiras:181","bookId":"diwan-abufiras","type":"poem","seq":181,"chapter":"البحر: متقارب تام","title":"بقلبي ، على ' جابر ' ، حسرة","page":"","text":"بقلبي ، على ' جابر ' ، حسرة … تزول الجبال ، وليست تزول\nله ، ما بقيت ، طويل البكاء … وحسن الثناء ؛ وهذا قليل"},{"id":"diwan-abufiras:182","bookId":"diwan-abufiras","type":"poem","seq":182,"chapter":"البحر: بسيط تام","title":"الدهر يومان : ذا ثبت ، وذا زلل ،","page":"","text":"الدهر يومان : ذا ثبت ، وذا زلل ، … والعيش طعمان : ذا صاب وذا عسل\nكذا الزمان ؛ فما في نعمة بطر … للعارفين ؛ ولا في نقمة فشل\nسعادة المرء في السراء إن رجحت ، … والعدل أن يتساوى الهم والجذل\nوما الهموم ، وإن حاذرت ، ثابتة … ولا السرور ، وإن أملت يتصل\nفما الأسى لهموم ، لابقاء لها ، … وما السرور بنعمى ، سوف تنتقل\nلكن في الناس مغرورا بنعمته ، … ما جاءه اليأس حتى جاءه الأجل"},{"id":"diwan-abufiras:183","bookId":"diwan-abufiras","type":"poem","seq":183,"chapter":"البحر: وافر تام","title":"وعطاف على الغمرات نحوي ،","page":"","text":"وعطاف على الغمرات نحوي ، … تحف به المثقفة الطوال\nتركت الرمح ، يخطر في حشاه ، … له ، ما بين أضلعه ، مجال\nيقول ، وقد تعدل فيه ، رمحي : … ' لأمر ما تحاماك الرجال ! '"},{"id":"diwan-abufiras:184","bookId":"diwan-abufiras","type":"poem","seq":184,"chapter":"البحر: بسيط تام","title":"قد ضج جيشك ، من طول القتال به ،","page":"","text":"قد ضج جيشك ، من طول القتال به ، … وقد شكتك إلينا الخيل والإبل !\nوقد درى الروم مذ جاورت أرضهم … أن ليس يعصمهم سهل ولا جبل\nفي كل يوم تزور الثغر ، لا ضجر … يثنيك عنه ، ولا شغل ولا ملل\nفالنفس جاهدة ، والعين ساهدة ، … والجيش منهمك ، والمال مبتذل\nتوهمتك كلاب غير قاصدها ، … وقد تكنفك الأعداء والشغل\nحتى رأوك ، أمام الجيش ، تقدمه … وقد طلعت عليهم دون ما أملوا\nفاستقبلوك بفرسان ، أسنتها … سود البراقع ، والأكوار ، والكلل\nفكنت أكرم مسؤول وأفضله ، … إذا وهبت فلا من ولا بخل"},{"id":"diwan-abufiras:185","bookId":"diwan-abufiras","type":"poem","seq":185,"chapter":"البحر: كامل تام","title":"ويقول في الحاسدون ، تكذبا ،","page":"","text":"ويقول في الحاسدون ، تكذبا ، … ويقال في المحسود ما لا يفعل\nيتطلبون إساءتي لا ذمتي ، … إن الحسود ، بما يسوء ، موكل"},{"id":"diwan-abufiras:186","bookId":"diwan-abufiras","type":"poem","seq":186,"chapter":"البحر: طويل","title":"أقلي ، فأيام المحب قلائل ،","page":"","text":"أقلي ، فأيام المحب قلائل ، … وفي قلبه شغل عن اللوم شاغل\nولعت بعذل المستهام على الهوى ، … وأولع شيء بالمحب العواذل\nأريتك ، هل لي من جوى الحب مخلص ، … وقد نشبت ، للحب في ، حبائل ؟\nوبين بنيات الخدور وبيننا … حروب ، تلظى نارها وتطاول\nأغرن على قلبي بجيش من الهوى … وطارد عنهن الغزال المغازل\nتعمد بالسهم المصيب مقاتلي ، … ألا كل أعضائي ، لديه ، مقاتل\nووالله ، ماقصرت في طلب العلا ؛ … ولكن كأن الدهر عني غافل\nمواعيد آمال ، تماطلني بها … مراماة أزمان ، ودهر مخاتل\nتدافعني الأيام عما أريده ، … كما دفع الدين الغريم المماطل\nخليلي ، أغراضي بعيد منالها ! … فهل فيكما عون على ما أحاول ؟\nخليلي ! شدا لي على ناقتيكما … إذا مابدا شيب من العجز ناصل\nفمثلي من نال المعالي بسيفه ، … وربتما غالته ، عنها ، الغوائل\nوما كل طلاب ، من الناس ، بالغ … ولا كل سيار ، إلى المجد ، واصل !\nوإن مقيما منهج العجز خائب … وإن مريغا ، خائب الجهد ، نائل\nوما المرء إلا حيث يجعل نفسه … وإني لها ، فوق السماكين ، جاعل\nوللوفر متلاف ، وللحمد جامع ، … وللشر تراك ، وللخير فاعل\nوما لي لا تمسي وتصبح في يدي … كرائم أموال الرجال العقائل ؟\nأحكم في الأعداء منها صوارما … أحكمها فيها إذا ضاق نازل\nومانال محمي الرغائب ، عنوة ، … سوى ما أقلت في الجفون الحمائل"},{"id":"diwan-abufiras:187","bookId":"diwan-abufiras","type":"poem","seq":187,"chapter":"البحر: بسيط تام","title":"سكرت من لحظه لا من مدامته","page":"","text":"سكرت من لحظه لا من مدامته … ومال بالنوم عن عيني تمايله\nوما السلاف دهتني بل سوالفه ، … ولا الشمول ازدهرني بل شمائله\nوغال صبري ما تحوي غلائله … وغال قلبي ما تحوي غلائله"},{"id":"diwan-abufiras:188","bookId":"diwan-abufiras","type":"poem","seq":188,"chapter":"البحر: طويل","title":"لحبك من قلبي حمى لا يحله","page":"","text":"لحبك من قلبي حمى لا يحله … سواك ، وعقد ليس خلق يحله\nوقد كنت أطلقت المنى لي بموعد … وقدرت لي وقتا ، وهذا محله !\nففي أي حكم ؟ أو على أي مذهب … تحل دمي ؟ والله ليس يحله !"},{"id":"diwan-abufiras:189","bookId":"diwan-abufiras","type":"poem","seq":189,"chapter":"البحر: متقارب تام","title":"أفر من السوء لا أفعله","page":"","text":"أفر من السوء لا أفعله … ومن موقف الضيم لا أقبله\nوقربى القرابة أرعى لها ، … وفضل أخي الفضل لا أجهله\nوأبذل عدلي للأضعفين ؛ … وللشامخ الأنف لا أبذله\nوأحسن ما كنت بقيا إذا … أنالني الله ما آمله\nوقد علم الحي ، حي الضباب ، … وأصدق قيل الفتى أفضله\nبأني كففت ، وأني عففت ، … وإن كره الجيش ما أفعله\nوقد أرهق الحي ، من خلفه … وأوقف ، خوف الردى ، أوله\nفعادت ' عدي ' بأحقادها ، … وقد عقل الأمر من يعقله"},{"id":"diwan-abufiras:190","bookId":"diwan-abufiras","type":"poem","seq":190,"chapter":"البحر: منسرح","title":"يا حسرة ما أكاد أحملها ،","page":"","text":"يا حسرة ما أكاد أحملها ، … آخرها مزعج ، وأولها !\nعليلة ، بالشآم مفردة ، … بات ، بأيدي العدا ، معللها\nتمسك أحشاءها ، على حرق … أنت ، على يأسها ، مؤملها\nإذا اطمأنت - وأين ؟ - أو هدأت ؛ … عنت لها ذكرة تقلقلها\nتسأل عنا الركبان ، جاهدة … بأدمع ما تكاد تمهلها :\n' يامن رأى لي ، بحصن ' خرشنة ' … أسد شرى ، في القيود أرجلها ! '\n' يامن رأى لي الدروب ، شامخة … دون لقاء الحبيب أطولها '\nيامن رأى لي القيود ، موثقة ، … على حبيب الفؤاد أثقلها ! '\nيا أيها الراكبان ، هل لكما … في حمل نجوى ، يخف محملها ؟ !\nقولا لها ، إن وعت مقالكما ، … وإن ذكري لها ليذهلها :\nيا أمتا ، هذه منازلنا … نتركها تارة ، وننزلها !\nيا أمتا ، هذه مواردنا … نعلها تارة ، وننهلها ! '\n' أسلمنا قومنا إلى نوب … أيسرها في القلوب أقتلها '\n' واستبدلوا ، بعدنا ، رجال وغى … يود أدنى علاي أمثلها '\nيا سيدا ، ما تعد مكرمة ، … إلا وفي راحتيه أكملها\nليست تنال القيود من قدمي ، … وفي اتباعي رضاك ، أحملها\nلاتتيمم ، والماء تدركه ! … غيرك يرضى الصغرى ويقبلها\nإن بني العم لست تحلفهم ؛ … إن عادت الأسد عاد أشبلها\nأنت سماء ، ونحن أنجمها ، … أنت بلاد ، ونحن أجبلها !\nأنت سحاب ، ونحن وابله ، … أنت يمين ، ونحن أنملها !\nبأي عذر ، رددت والهة ، … عليك ، دون الورى ، معولها\nجاءتك ، تمتاح رد واحدها ، … ينتظر الناس كيف تقفلها !\nسمحت مني بمهجة كرمت … أنت ، على يأسها ، مؤلمها\nإن كنت تبذل الفداء لها ! … فلم أزل ، في رضاك ، أبذلها\nتلك المودات ، كيف تهملها ؟ … تلك المواعيد ، كيف تغفلها ؟\nتلك العقود ، التي عقدت لنا ، … كيف ، وقد أحكمت ، تحللها ؟\nأرحامنا منك ؛ لم تقطعها ؟ … \nأين المعالي التي عرفت بها ، … تقولها ، دائما ، وتفعلها ؟\nيا واسع الدار ، كيف توسعها … ونحن في صخرة نزلزلها !\nيا ناعم الثوب ! كيف تبدله ؟ … ثيابنا الصوف ما نبدلها !\nيا راكب الخيل ! لو بصرت بنا … نحمل أقيادنا ، وننقلها !\nرأيت ، في الضر ، أوجها كرمت … فارق فيك الجمال أجملها !\nقد أثر الدهر في محاسنها ، … تعرفها ، تارة ، وتجهلها\nفلا تكلنا ، فيها ، إلى أحد ، … معلها محسن يعللها\nلا يفتح الناس باب مكرمة … صاحبها المستغاث يقفلها\nأينبري ، دونك ، الكرام لها … وأنت قمقامها ، وأحملها !\nوأنت ، إن عن حادث جلل ، … قلبها المرتجى ، وحولها !\nمنك تردى بالفضل أفضلها ، … منك أفاد النوال أنولها\nفإن سألنا سواك عارفة ، … فبعد قطع الرجاء نسألها\nإذا رأينا أولى الكرام بها … يضيعها ، جاهدا ، ويهملها\nلم يبق ، في الناس ، أمة عرفت … إلا وفضل ' الأمير ' يشملها\nنحن أحق الورى برأفته ، … فأين عنا ؟ وأين معدلها ؟\nيا منفق المال ، لا يريد به … إلا المعالي التي يؤثلها\nأصبحت تشري مكارما فضلا … فداؤنا ، قد علمت ، أفضلها !\nلا يقبل الله ، قبل فرضك ذا ، … نافلة عنده تنفلها !"},{"id":"diwan-abufiras:191","bookId":"diwan-abufiras","type":"poem","seq":191,"chapter":"البحر: سريع","title":"أي اصطبار ليس بالزائل ؟","page":"","text":"أي اصطبار ليس بالزائل ؟ … وأي دمع ليس بالهامل ؟\nإنا فجعنا بفتى ' وائل … لما فجعنا ' بأبي وائل '\nالمشتري الحمد بأمواله ، … والبائع النائل بالنائل\nماذا أرادت سطوات الردى … بالأسد ابن الأسد ، الباسل ؟\nالسيد ابن السيد ، المرتجى ، … والعالم ابن العالم ، الفاضل !\nأقسمت : لو لم يحكه ذكره … رجعن عنه بشبا ثاكل\nكأنما دمعي ، من بعده … صوب سحاب واكف ، وابل\nما أنا أبكيه ، ولكنما … تبكيه أطراف القنا الذابل\nما كان إلا حدثا نازلا ، … موكلا بالحدث النازل\nدان إلى سبل الندى والعلا ، … ناء عن الفحشاء والباطل\nأرى المعالي ، إذ قضى نحبه ، … تبكي بكاء الواله ، الثاكل\nالأسد الباسل ، والعارض ال … هاطل ، عند الزمن الماجل\nلو كان يفدي معشر هالكا … فداه من حاف ، ومن ناعل\nفكم حشا قبرك من راغب ! … وكم حشا تربك من آمل !\nسقى ثرى ، ضم ' أبا وائل ' ، … صوب عطايا كفه الهاطل !\nلا در در الدهر - ما باله … حملني ما لست بالحامل ؟\nكان ابن عمي ، إن عرا حادث ، … كالليث ، أو كالصارم الصاقل\nكان ابن عمي عالما ، فاضلا ، … والدهر لا يبقي على فاضل\nكان ابن عمي بحر جود طمى … لكنه بحر بلا ساحل\nمن كان أمسى قلبه خاليا … فإنني في شغل شاغل"},{"id":"diwan-abufiras:192","bookId":"diwan-abufiras","type":"poem","seq":192,"chapter":"البحر: وافر تام","title":"ضلال مارأيت من الضلال","page":"","text":"ضلال مارأيت من الضلال … معاتبة الكريم على النوال\nوإن مسامعي ، عن كل عذل ، … لفي شغل بحمد أو سؤال\nولا والله ، ما بخلت يميني ، … ولا أصبحت أشقاكم بمالي\nولا أمسي يحكم فيه يعدي … قليل الحمد ، مذموم الفعال\nولكني سأفنيه ، وأقني … ذخائر من ثواب أو جمال\nوللوراث إرث أبي وجدي ، … جياد الخيل والأسل الطوال\nوما تجني سراة بني أبينا … سوى ثمرات أطراف العوالي\nممالكنا مكاسبنا ، إذا ما … توارثها رجال عن رجال\nإذا لم تمس لي نار فإني … أبيت ، لنار غيري ، غير صال\nأوينا ، بين أطناب الأعادي ، … إلى بلد ، من النصار خال\nنمد بيوتنا ، في كل فج ، … به بين الأراقم والصلال\nنعاف قطونه ، ونمل منه ، … ويمنعنا الإباء من الزيال\nمخافة أن يقال ، بكل أرض : … بنو حمدان كفوا عن قتال\nأسيف الدولة المأمول ، إني … عن الدنيا ، إذا ما عشت ، سال\nومن ورد المهالك لم ترعه … رزايا الدهر في أهل ومال\nإذا قضي الحمام علي ، يوما … ففي نصر الهدى بيد الضلال\nمخافة أن يقال ، بكل أرض : … فليس عليك خائنة الليالي\nوأنت أشد هذا الناس بأسا ، … به بين الأراقم والصلال\nوأهجمهم على جيش كثيف … وأغورهم على حي حلال\nضربت فلم تدع للسيف حدا … وجلت بحيث ضاق عن المجال\nفقلت ، وقد أظل الموت : صبرا ! … وإن الصبر عند سواك غال\nألا هل منكر يابني نزار ، … مقامي ، يوم ذلك ، أو مقالي ؟\nألم أثبت لها ، والخيل فوضى ، … بحيث تخف أحلام الرجال ؟\nتركت ذوابل المران فيها … مخضبة ، محطمة الأعالي\nوعدت أجر رمحي عن مقام ، … تحدث عنه ربات الحجال\nوقائلة تقول : جزيت خيرا … لقد حاميت عن حرم المعالي !\nومهري لا يمس الأرض ، زهوا ، … كأن ترابها قطب النبال\nكأن الخيل تعرف من عليها ، … ففي بعض على بعض تعالي\n … رخيص عنده المهج الغوالي\nفإن عشنا ذخرناها لأخرى ، … وإن متنا فموتات الرجال"},{"id":"diwan-abufiras:193","bookId":"diwan-abufiras","type":"poem","seq":193,"chapter":"البحر: طويل","title":"فلما رأتنا اجفلت كل مجفل فبين قتيل بالدماء مضرج ، إباء إباء البكر ، غير مذلل ،","page":"","text":"فلما رأتنا اجفلت كل مجفل فبين قتيل بالدماء مضرج ، إباء إباء البكر ، غير مذلل ، … وعزم كحد السيف ، غير مفلل\nأأغضي على الأمر ، الذي لا أريده ، … ولما يقم بالعذر رمحي ومنصلي\nأبى الله ، والمهر المنيعي ، والقنا ، … وأبيض وقاع على كل مفصل\nوفتيان صدق من غطاريف وائل … إذا قيل ركب الموت قالوا له : انزل\nيسوسهم بالخير والشر ماجد ، … جرور لأذيال الخميس المذيل\nله بطش قاس ، تحته قلب راحم ، … ومنع بخيل ، بعده بذل مفضل\nوعزمة خراج من الضيم ، فاتك ، … وفي ، أبي ، يأخذ الأمر من عل\nعزوف ، أنوف ، ليس يقرع سنه ، … جريء ، متى يعزم على الأمر يفعل\nشديد على طي المنازل صبره ، … إذا هو لم يظفر بأكرم منزل\nبكل محلاة السراة بضيغم ، … وكل معلاة الرحال بأحدل\nكأن أعالي رأسها وسنامها … منارة قسيس ، قبالة هيكل\nسريت بها ، من ساحل … على ' كفر طاب ' ، صوبها لم يحول\nوقدمت نذري أن يقولوا : غدرتنا … وأقبلت ، لم أرهق ، ولم أتحيل\nإلى عرب ، لا تختشي غلب غالب ، … وفي ، أبي ، يأخذ الأمر من عل\nتواصت بمر الصبر ، دون حريمها … \n … وفي ، أبي ، يأخذ الأمر من عل\nفلما أطعت الجهل والغيظ ، ساعة ، … دعوت بحلمي : أيها الحلم أقبل !\nبنيات عمي هن ، ليس يرينني : … بعيد التجافي ، أو قليل التفضل\nشفيع النزاريات ، غير مخيب ، … وداعي النزاريات ، غير مخذل\nرددت ، برغم الجيش ، ما حاز كله ، … وكلفت مالي غرم كل مضلل\nفأصبحت ، في الأعداء ، أي ممدح … وإن كنت في الأصحاب ، أي معذل\nمضى فارس الحيين ' زيد بن منعة ' … ومن يدن من نار الوقيعة يصطل\nوقرما ' بني البنا : تميم بن غالب ' … همامان ، طعانان في كل جحفل\nولو لم تفتني سورة الحرب فيهما … جريت على رسم من الصفح أول\nوعدت ، كريم البطش ، والعفو ، ظافرا ، … أحدث عن يوم أغر ، محجل"},{"id":"diwan-abufiras:194","bookId":"diwan-abufiras","type":"poem","seq":194,"chapter":"البحر: مجزوء الكامل","title":"هل تعطفان على العليل ؟","page":"","text":"هل تعطفان على العليل ؟ … لا بالأسير ، ولا القتيل !\nباتت تقبله الأك … ف ، سحابة الليل الطويل\nيرعى الندجوم السائرا … ت من الطلوع إلى الأفول\nفقد الضيوف مكانه ، … وبكاه أبناء السبيل\nواستوحشت لفراقه ، … يوم الوغى ، سرب الخيول\nوتعطلت سمر الرما … ح ، وأغمدت بيض النصول\nيا فارج الكرب العظي … م ، وكاشف الخطب الجليل\nكن ، يا قوي ، لذا الضعي … ف ، ويا عزيز ، لذا الذليل !\nقربه من سيف الهدى ، … في ظل دولته الظليل !\nأوما كشفت عن ابن دا … ود ' ثقيلات الكبول ؟ !\nلم أرو منه ولا شفي … ت بطول خدمته ، غليلي\nألله يعلم : أنه … أملي من الدنيا وسولي\nولئن حننت إلى ذرا … ه لقد حننت إلى وصول\nلا بالغضوب ، ولا الكذو … ب ، ولا القطوب ، ولا الملول\nيا عدتي في النائبا … ت ، وظلتي عند المقيل !\nأين المحبة ، والذما … م وما وعدت من الجميل ؟ !\nأجمل على النفس الكري … مة في ، والقلب الحمول !\nأما المحب فليس يص … غي في هواه إلى عذول\nيمضي بحال وفائه ، … ويصد عن قال وقيل !"},{"id":"diwan-abufiras:195","bookId":"diwan-abufiras","type":"poem","seq":195,"chapter":"البحر: رجز تام","title":"أروح القلب ببعض الهزل ،","page":"","text":"أروح القلب ببعض الهزل ، … تجاهلا مني ، بغير جهل !\nأمزح فيه ، مزح أهل الفضل ، … والمزح ، أحيانا ، جلاء العقل\nقل لأحبابنا الجفاة : رويدا ! … درجونا على احتمال الملال !\nإن ذاك الصدود ، من غير جرم … لم يدع في مطمعا بالوصال\nأحسنوا في فعالكم أو أسيئوا ! … لا عدمناكم على كل حال !"},{"id":"diwan-abufiras:196","bookId":"diwan-abufiras","type":"poem","seq":196,"chapter":"البحر: خفيف تام","title":"قاتلي شادن ، بديع الجمال ،","page":"","text":"قاتلي شادن ، بديع الجمال ، … أعجمي الهوى ، فصيح الدلال\nسل سيف الهوى علي ونادى : … يا لثأر الأعمام والأخوال !\nكيف أرجو ممن يرى الثأر عندي … خلقا من تعطف أو وصال ؟\nبعدما كرت السنون ، وحالت … دون ذي قار الدهور الخوالي\nأيها الملزمي جرائر قومي ، … بعدما قد مضت عليها الليالي !\nلم أكن من جناتها ، علم الله ، … وإني لحرها ، اليوم ، صال"},{"id":"diwan-abufiras:197","bookId":"diwan-abufiras","type":"poem","seq":197,"chapter":"البحر: كامل تام","title":"الفكر فيك مقصر الآمال ،","page":"","text":"الفكر فيك مقصر الآمال ، … والحرص بعدك غاية الجهال\nلو كان يخلد بالفضائل فاضل … وصلت لك الآجال بالآجال !\nأو كنت تفدى لافتدتك سراتنا … بنفائس الأرواح والأموال\nأو كان يدفع عنك بأس أقبلت ، … شرعا ، تكدس بالقنا العسال\nأعزز ، على سادات قومك ، أن ترى … فوق الفراش ، مقلب الأوصال\nوالسابغات مصونة ، لم تبتذل ، … والبيض سالمة مع الأبطال\nوإذا المنية أقيلت لم يثنها … حرص الحريص ، وحيلة المحتال\nما للخطوب ؟ وما لأحداث الردى … أعجلن جابر غاية الإعجال ؟\nلما تسربل بالفضائل ، وارتدى … برد العلا ، وأعتم بالإقبال\nوتشاهدت صيد الملوك بفضله … وأرى المكارم ، من مكان عال\nأأبا المرجى ! غير حزني دارس ، … أبدا عليك ، وغير قلبي سال\nلا زلت مغدو الثرى ، مطروقه ، … بسحابة مجرورة الأذيال\nوحجبن عنك السيئات ولم يزل … لك صاحب من صالح الأعمال"},{"id":"diwan-abufiras:198","bookId":"diwan-abufiras","type":"poem","seq":198,"chapter":"البحر: وافر تام","title":"سلي عنا سراة بني كلاب","page":"","text":"سلي عنا سراة بني كلاب … ببالس ، عند مشتجر العوالي !\nلقيناهم بأسياف قصار ، … كفين مؤونة الأسل الطوال\nوولى ب ' آبن عوسجة كثير ' … وساع الخطو في ضنك المجال\nيرى ' البرغوث ' إذ نجاه منا ، … أجل عقيلة ، وأحب مال\nتدور به إماء من ' قريظ ' ؛ … وتسأله النساء عن الرجال !\nيقلن له : السلامة خير غنم ! … وإن الذل في ذاك المقال\nو' جهمان ' تجافت عنه بيض ، … عدلن عن الصريح إلى الموالي\nوعادوا ، سامعين لنا ، فعدنا … إلى المعهود من شرف الفعال\nونحن متى رضينا بعد سخط … أسونا ما جرحنا بالنوال"},{"id":"diwan-abufiras:199","bookId":"diwan-abufiras","type":"poem","seq":199,"chapter":"البحر: مجزوء الكامل","title":"نفسي فداؤك قد بعث","page":"","text":"نفسي فداؤك قد بعث … ت بعهدتي بيد الرسول\nأهديت نفسي ، إنما … يهدى الجليل إلى الجليل\nوجعلت ما ملكت يدي ، … بشرى المبشر بالقبول"},{"id":"diwan-abufiras:200","bookId":"diwan-abufiras","type":"poem","seq":200,"chapter":"البحر: هزج","title":"غنى النفس ، لمن يعق","page":"","text":"غنى النفس ، لمن يعق … ل ، خير من غنى المال !\nوفضل الناس ، في الأنف … س ، ليس الفضل في الحال"},{"id":"diwan-abufiras:201","bookId":"diwan-abufiras","type":"poem","seq":201,"chapter":"البحر: طويل","title":"يلوح بسيماه الفتى من بني أبي ،","page":"","text":"يلوح بسيماه الفتى من بني أبي ، … وتعرفه من غيره بالشمائل\nمفدى ، مردى ؛ يكثر الناس حوله … طويل نجاد السيف ، سبط الأنامل"},{"id":"diwan-abufiras:202","bookId":"diwan-abufiras","type":"poem","seq":202,"chapter":"البحر: وافر تام","title":"ألا لله ، يوم الدار يوما","page":"","text":"ألا لله ، يوم الدار يوما … بعيد الذكر ، محمود المآل\nتركت به نساء ' بني كلاب ' ، … فوارك ، ما يرغن إلى الرجال\nتركنا الشبخ ، شيخ ' بني قريظ ' … ببطن القاع ممنوع الذمال\nمقاطعة أحبته ، ولكن … يبيت من الخوامع في وصال\nتخف إذا تطاردنا ' كلاب ' ؛ … فكيف بها إذا قلنا نزال\nتركناها ، ولم يتركن إلا … لأبناء العمومة ، والخوالي !\nفلم ينهضن عن تلك الحشايا ؛ … ولم يبرزن من تلك الحجال"},{"id":"diwan-abufiras:203","bookId":"diwan-abufiras","type":"poem","seq":203,"chapter":"البحر: طويل","title":"إذا كان فضلي لا أسوغ نفعه","page":"","text":"إذا كان فضلي لا أسوغ نفعه … فأفضل منه أن أرى غير فاضل\nومن أضيع الأشياء مهجة عاقل ، … يجوز على حوبائها حكم جاهل !"},{"id":"diwan-abufiras:204","bookId":"diwan-abufiras","type":"poem","seq":204,"chapter":"البحر: متقارب تام","title":"هواك هواي ، على كل حال","page":"","text":"هواك هواي ، على كل حال … وإن مسني فيك بعض الملال\nوكم لك عندي من غدرة ، … وقول ، تكذبه بالفعال !\nووعد يعذب فيه الكريم … إما بخلف ، وإما مطال\nصبرنا لسخطك ، صبر الكرام ، … فهذا رضاك ، فهل من نوال ؟\nوذقنا مرارة كأس الصدود ، … فأين حلاوة كأس الوصال ؟"},{"id":"diwan-abufiras:205","bookId":"diwan-abufiras","type":"poem","seq":205,"chapter":"البحر: طويل","title":"أقول وقد ناحت بقربي حمامة :","page":"","text":"أقول وقد ناحت بقربي حمامة : … أيا جارتا هل بات حالك حالي ؟\nمعاذ الهوى ! ماذقت طارقة النوى ، … ولا خطرت منك الهموم ببال\nأتحمل محزون الفؤاد قوادم … على غصن نائي المسافة عال ؟\nأيا جارتا ، ما أنصف الدهر بيننا ! … تعالي أقاسمك الهموم ، تعالي !\nتعالي تري روحا لدي ضعيفة ، … تردد في جسم يعذب بالي\nأيضحك مأسور ، وتبكي طليقة ، … ويسكت محزون ، ويندب سال ؟\nلقد كنت أولى منك بالدمع مقلة ؛ … ولكن دمعي في الحوادث غال !"},{"id":"diwan-abufiras:206","bookId":"diwan-abufiras","type":"poem","seq":206,"chapter":"البحر: طويل","title":"ولله عندي في الإسار وغيره","page":"","text":"ولله عندي في الإسار وغيره … مواهب ، لم يخصص بها أحد قبلي !\nحللت عقودا ، أعجز الناس حلها ، … وما زال عقدي لا يذم ولا حلي\nإذا عاينتني الروم كفر صيدها ، … كأنهم أسرى لدي وفي كبلي\nوأوسع ، أيا ما حللت ، كرامة ، … كأنني من أهلي نقلت إلى أهلي\nفقل لبني عمي ، وأبلغ بني أبي : … بأني في نعماء يشكرها مثلي\nوما شاء ربي غير نشر محاسني ، … وأن يعرفوا ما قد عرفت من الفضل"},{"id":"diwan-abufiras:207","bookId":"diwan-abufiras","type":"poem","seq":207,"chapter":"البحر: مجزوء الكامل","title":"إنا ، إذا اشتد الزما","page":"","text":"إنا ، إذا اشتد الزما … ن ، وناب خطب وادلهم\nألفيت ، حول بيوتنا ، … عدد الشجاعة ، والكرم\nللقا العدى بيض السيو … ف ، وللندى حمر النعم\nهذا وهذا دأبنا ، … يودى دم ، ويراق دم\nقل لابن ورقا جعفر ، … حتى يقول بما علم\nإني ، وإن شط المزا … ر ولم تكن داري أمم\nأصبو إلى تلك الخلا … ل ، وأصطفي تلك الشيم '\n' وألوم عادية الفرا … ق ، وبين أحشائي ألم\n' ولعل دهرا ينثني ، … ولعل شعبا يلتئم '\n' هل أنت ، يوما ، منصفي … من ظلم عمك ؟ يا بن عم\nأبلغه عني ما أقو … ل ، فأنت من لا يتهم ! '\nأني رضيت ، وإن كره … ت ، أبا محمد الحكم"},{"id":"diwan-abufiras:208","bookId":"diwan-abufiras","type":"poem","seq":208,"chapter":"البحر: مجزوء الكامل","title":"يهني الأمير بشارة ،","page":"","text":"يهني الأمير بشارة ، … قرت بها عين المكارم\nأعلى الورى شرفا ، ومن … قد بشروه بخير قادم\nإني ، وإن كنت المشا … رك في الأبوة ، والمساهم\nلأقول قولا لا يرد ، … ولا يرى لي فيه لاثم :\nلأبي المعالي ، في العلا ، … و' أبي المكارم ' في المكارم\nبيت ، رفيع سمكه ، … عالي الذرى ، ثبت الدعائم"},{"id":"diwan-abufiras:209","bookId":"diwan-abufiras","type":"poem","seq":209,"chapter":"البحر: كامل تام","title":"إبنان ، أم شبلان ذان ؟ فإنني","page":"","text":"إبنان ، أم شبلان ذان ؟ فإنني … لأرى دماء الدارعين غذاهما\nتنبي الفراسة : أن في ثوبيهما … ليثين ، تجتنب الليوث حماهما\nلم لا يفوقان الأنام ، مكارما ! … والسيدان ، كلاهما ، جداهما\nتلقى ' أبا الهيجاء ' في هيجاهما ، … ويريك فضل أبي العلاء علاهما\nزدناهما ، شرفا رفيعا سمكه ، … ثبت الدعائم ، إذ تخولناهما\nميزت بينهما فلم يتفاضلا … كالفرقدين تشاكلت حالاهما\nإني ، وإن كان التعصب شيمتي ، … لا أدفع الشرف المنيف أخاهما !\nأنى يقصر عن مكان في العلا … والمجد ، من أضحى أبوه أباهما ؟\nلكن لذين بنا مكان باذخ ، … لايدعيه ، من الأنام ، سواهما"},{"id":"diwan-abufiras:210","bookId":"diwan-abufiras","type":"poem","seq":210,"chapter":"البحر: وافر تام","title":"أسرت فلم أذق للنوم طعما ،","page":"","text":"أسرت فلم أذق للنوم طعما ، … ولا حل الطعان لنا حزاما\nوسرنا ، معلمين ، إليك حتى … ضربنا ، خلف ' خرشنة ' الخياما !"},{"id":"diwan-abufiras:211","bookId":"diwan-abufiras","type":"poem","seq":211,"chapter":"البحر: مجزوء الكامل","title":"يا سيدي ! أراكما","page":"","text":"يا سيدي ! أراكما … لا تذكران أخاكما !\nأوجدتما بدلا به ، … يبني سماء علاكما ؟\nأوجدتما بدلا به ، … يفري نحور عداكما ! ؟\nما كان بالفعل الجمي … ل ، بمثله ، أولاكما !\nمن ذا يعاب ، بما لقي … ت من الورى ، إلا كما ؟\nلا تقعدا بي ، بعدها ، … وسلا ' الأمير ' ، أباكما !\nوخذا فداي ، جعلت من … ريب الزمان فداكما !"},{"id":"diwan-abufiras:212","bookId":"diwan-abufiras","type":"poem","seq":212,"chapter":"البحر: بسيط تام","title":"وشادن قال لي ، لما رأى سقمي","page":"","text":"وشادن قال لي ، لما رأى سقمي … وضعف جسمي والدمع الذي انسجما\nأخذت دمعك من خدي ، وجسمك من … خصري وسقمك من طرفي الذي سقما"},{"id":"diwan-abufiras:213","bookId":"diwan-abufiras","type":"poem","seq":213,"chapter":"البحر: وافر تام","title":"ألا من مبلغ سروات قومي","page":"","text":"ألا من مبلغ سروات قومي … وسيف الدولة الملك ، الهماما !\nبأني لم أدع فتيات قومي ، … إذا حدثن ، جمجمن الكلاما\nشريت ثناءهن ببذل نفسي ، … ونار الحرب تضطرم اضطراما\nولما لم أجد إلا فرارا … أشد من المنية أو حماما\nحملت ، على ورود الموت ، نفسي … وقلت لعصبتي : ' موتوا كراما ! '\nولم أبذل ، لخوفهم ، مجنا ، … ولم ألبس حذار الموت ، لاما\nوعذت بصارم ، ويد ، وقلب … حماني أن ألام ، وأن أضاما\nألفهم وأنشرهم كأني … أطرد منهم الإبل السواما\nوأنتقد الفوارس ، بيد أني … رأيت اللوم أن ألقى اللئاما\nومدعو إلى أجاب لما … رأى أن قد تذمم واستلاما\nعقدت على مقلده يميني ، … وأعفيت المثقف والحساما\nوهل عذر ، و' سيف الدين ركني ، … إذا لم أركب الخطط العظاما ؟\nوأتبع فعله ، في كل أمر ، … وأجعل فضله ، أبدا ، إماما\nوقد أصبحت منتسبا إليه ، … وحسبي أن أكون له غلاما\nأراني كيف أكتسب المعالي ، … وأعطاني ، على الدهر ، الذماما\nورباني ففقت به البرايا ، … وأنشأني فسدت به الأناما\nفعمره الإله لنا طويلا ، … وزاد الله نعمته دواما !"},{"id":"diwan-abufiras:214","bookId":"diwan-abufiras","type":"poem","seq":214,"chapter":"البحر: بسيط تام","title":"لمثلها يستعد البأس والكرم ،","page":"","text":"لمثلها يستعد البأس والكرم ، … وفي نظائرها تستنفد النعم\nهي الرئاسة لا تقنى جواهرها ، … حتى يخاض إليها الموت والعدم\nتقاعس الناس عنها فانتدبت لها … كالسيف ، لا نكل فيه ولا سأم\nما زال يجحدها قوم ، وينكرها … حتى أقروا ، وفي آنافهم رغم\nشكرا فقد وفت الأيام ما وعدت ، … أقر ممتنع ؛ وانقاد معتصم !\nوما الرئاسة إلا ما تقر به … شمس الملوك ، وتعنو تحته الأمم\nمغارم المجد يعتد الملوك بها … مغانما في العلا ، في طيها نعم\nهذي شيوخ ' بني حمدان ' قاطبة ، … لاذوا بدارك عند الخوف واعتصموا\nحلوا بأكرم من حل العباد به … بحيث حل الندى واستوثق الكرم\nفكنت منهم وإن أصبحت سيدهم ، … تواضع الملك في أصحابه عظم !\nشيخوخة سبقت ، لا فضل يتبعها … وليس يفضل فينا الفاضل الهرم\nولم يفضل ' عقيلا ' في ولادته … على علي أخيه ، السن والقدم\nوكيف يفضل من أزرى به بخل … وقعدة اليد ، والرجلين ، والصمم\nلا تنكروا ، يا بنيه ، ما أقول فلن … تنسى الترات ولا إن حال شيخكم\nكادت مخازيه ترديه فأنقذه … منها ، بحسن دفاع عنه ، عمكم\nأستودع الله قوما ، لا أفسرهم ، … الظالمين ، ولو شئنا لما ظلموا\nالقائلين ، ونغضي عن جوابهم , … والجائرين ، ونرضى بالذي حكموا\nإني ، على كل حال ، لست أذكرهم ؛ … إلا وللشوق دمعي واكف ، سجم\nالأنفس اجتمعت يوما ، أو افترقت … إذا تأملت ، نفس ، والدماء دم\nرعاهم الله ، ما ناحت مطوقة ، … وحاطهم ، أبدا ، ما أورق السلم"},{"id":"diwan-abufiras:215","bookId":"diwan-abufiras","type":"poem","seq":215,"chapter":"البحر: طويل","title":"يقولون لا تخرق بحلمك هيبة","page":"","text":"يقولون لا تخرق بحلمك هيبة … وأحسن شيء زين الهيبة الحلم\nفلا تتركن العفو عن كل زلة … فما العفو مذموم ، وإن عظم الجرم"},{"id":"diwan-abufiras:216","bookId":"diwan-abufiras","type":"poem","seq":216,"chapter":"البحر: طويل","title":"نفى النوم عن عيني خيال مسلم","page":"","text":"نفى النوم عن عيني خيال مسلم … تأوب من أسماء ، والركب نوم\nظللت وأصحابي عباديد في الدجى … ألذ بجوال الوشاح ، وأنعم\nوسائلة عني فقلت ، تعجبا : … كأنك لا تدرين كيف المتيم ؟\nأعرني ، أقيك السوء ، نظرة وامق … لعلك ترثي ، أو لعلك ترحم !\nفما أنا إلا عبدك القن في الهوى ، … وما أنت إلا المالك ، المتحكم\nوأرضى بما ترضى على السخط والرضا … وأغضي ، على علم بأنك تظلم\nيئست من الإنصاف بيني وبينه ، … ومن لي بالإنصاف والخصم يحكم ؟\nوخطب من الأيام أنساني الهوى ، … وأحلى بفي الموت ، والموت علقم\nووالله ، ماشببت إلا علاله ، … ومن نار غير الحب قلبي يضرم\nألا مبلغ عني الحسين ألوكة ، … تضمنها در الكلام المنظم\nلذيذ الكرى ، حتى أراك ، محرم … ونار الأسى بين الحشا تتضرم\nوأترك أن أبكي عليك ، تطيرا ، … وقلبي يبكي ، والجوانح تلطم\nوإن جفوني إن ونت للئيمة ، … وإن فؤادي إن سلوت لألأم\nوأظهر للأعداء فيك جلادة ، … وأكتم ما ألقاه والله يعلم\nسأبكيك ، ما أبقى لي الدهر مقلة ، … فإن عزني دمع ، فما عزني دم\nوحكمي بكاء الدهر فيما ينوبني ، … وحكم لبيد فيه حول مجرم\nوما نحن إلا ' وائل ' و' مهلهل ' … صفاء ، وإلا مالك ومتمم !\nوإني وإياه لعين وأختها ، … وإني وإياه لكف ومعصم\nتصاحبنا الأيام في ثوب ناصح … ويختلنا منها ، على الأمن ، أرقم\nوما أغربت فيك الليالي ، وإنها … لتصدعنا من كل شعب وتثلم\nطوارق خطب ، ما تغب وفودها ، … وأحداث أيام تغذ وتتئم\nفما عرفتني غير ما أنا عارف … ولا علمتني غير ما كنت أعلم\nمتى لم تصب من الليالي ابن همة … يجشمها صرف الردى فتجشم\nتهين علينا الحرب نفسا عزيزة … إذا عاضنا منها الثناء المنمنم\nوإني لغر إن رضيت بصاحب … يبش ، وفيه جانب متجهم\nونحن أناس ، لا تزال سراتنا … لها مشرب ، بين المنايا ، ومطعم\nنظرناإلى هذا الزمان ، وأهله … فهان علينا ما يشت وينظم\nوندعو كريما من يجود بماله ، … ومن يبذل النفس الكريمة أكرم\nوما لي لا أمضي حميدا ومطلبي … بعيد ، وما فعلي بحال مذمم\nإذا لم يكن ينجي الفرار من الردى ، … على حالة ، فالصبر أرجى وأحزم\nلك الله إنا بين غاد ورائح … نعد المغازي في البلاد ونغنم\nوأرماحنا في كل لبة فارس … تثقب تثقيب الجمان وتنظم\nسنضربهم ، مادام للسيف قائم ، … ونطعنهم ، مادام للرمح لهذم\nونقفوهم ، خلف الخليج بضمر … تخوض بحارا بعض خلجانها دم\nبكل غلام من ' نزار ' وغيرها … عليه من الماذي درع مختم\nونجنب ما ألقى ' الوجيه ' و' لاحق ' … إلى كل ما أبقى الجديل وشدقم\nونعتقل الصم العوالي إنها … طريق إلى نيل المعالي وسلم\nرأيتهم يرجون ثأرا بسالف ، … وفي كل يوم يأخذ السيف منهم\nفقل ل ' ابن فقاس ' : دع الحرب جانبا ! … فإنك رومي ، وخصمك مسلم\nفوجهك مضروب ، وأمك ثاكل ، … وسبطك مأسور ، وعرسك أيم\nولم تنب عنك البيض في كل مشهد … ولكن قتل الشيخ فينا محرم\nإذا ضربت فوق الخليج قبابنا ، … وأمسى عليك الذل ، وهو مخيم\nوأدى إلينا ' الملك ' جزية رأسه ، … وفك عن الأسرى الوثاق وسلموا\nفإن ترغبوا في الصلح فالصلح صالح … وإن تجنحوا للسلم فالسلم أسلم\nأعادات سيف الدولة القرم إنها … لإحدى الذي كشفت بل هي أعظم !\nوإن لسيف الدولة القرم عادة … تروم علوق المعجزات فترأم\nوقيل لها : سيف الهدى ، قلت : إنه … ليفعل خير الفاعلين ويكرم\nأما انتاش من مس الحديد وثقله … ' أبا وائل ' والبيض في البيض تحكم\nتجر عليه الحرب ، من كل جانب ، … فلا ضجر جاف ، ولا متبرم\nأخو عزمات في الحروب إذا أتى … أتى حادث ، من جانب الله مبرم\nنخف ، إذا ضاقت علينا أمورنا ، … بأبيض وجه الرأي والخطب مظلم\nونرمي بأمر لا نطيق احتماله … إلى قرمنا ، والقرم بالأمر أقوم\nإلى رجل يلقاك في شخص واحد … ولكنه في الحرب جيش عرمرم\nنثيل على الأعداء أعقاب وطئه ، … صليب على أفواهها حين تعجم\nونمسك عن بعض الأمور مهابة ، … فيعلم ما يخفي الضمير ، ويفهم\nونجني جنايات عليه يقيلها ، … ونخطيء أحيانا إليه فيحلم\nيسوموننا فيك الفداء ، وإننا … لنرجوك قسرا والمعاطس ترغم\nأترضى بأن نعطى السواء قسيمنا … إذا المجد بين الأغلبين يقسم ؟\nوما الأسر غرم ، والبلاء محمد ، … ولا النصر غنم ، والهلاك مذمم\n … وأقدمت لو أن الكتائب تقدم\nدعوت خلوفا ، حين تختلف القنا ، … وناديت صما عنك ، حين تصمم\nوما عابك ، ابن السابقين إلى العلا ، … تأخر أقوام وأنت مقدم\nومالك لا تلقى بمهجتك الردى ، … وأنت من القوم الذين هم هم !\nلعا ، يا أخي ! - لامسك السوء - إنه … هو الدهر في حاليه : بؤس وأنعم\nوما ساءني أني مكانك ، عانيا … وأسلم نفسي للإسار وتسلم\nطلبتك حتى لم أجد لي مطلبا ، … وأقدمت حتى قل من يتقدم\n … ولكن قضاء فاتني فيك مبرم !\nفإن جل هذا الأمر فالله فوقه ، … وإن عظم المطلوب فالله أعظم !\nوإني أخفي فيك ، ماليس خافيا … وأكتم وجدا ، مثله لا يكتم\nولو أنني وفيت رزءك حقه … لما خط لي كف ، ولا فاه لي فم !"},{"id":"diwan-abufiras:217","bookId":"diwan-abufiras","type":"poem","seq":217,"chapter":"البحر: وافر تام","title":"وراءك يا ' نمير ' ! فلا إمام","page":"","text":"وراءك يا ' نمير ' ! فلا إمام … فقد حرم الجزيرة والشآم\nلنا الدنيا ، فما شئنا حلال … لساكنها ، وما شئنا حرام\nوينفذ أمرنا ، في كل حي ، … فيدنيه ويقصيه الكلام\nأراجية خويلفة ذماما … وراءك ، لا أمان ولا ذمام !\nألم تخبرك خيلك عن مقامي … ببالس يوم ضاق بها المقام !\nوولت تتقي ، بعضا ببعض ، … لهم - والأرض واسعة - زحام\nسروا والليل يجمعنا ، ولمن … يبوح بهم ، ويكتمنا الظلام\nإلى أن صبحتهم بالمنايا … كرائم ، فوق أظهرها كرام\nمن العرشات تلحق ما رأته … إذا طلبت ، وتعطى ما تسام\nتنازع بي وبالفرسان حولي … تجفلهم ، كما جفل النعام\nبطحنا منهم ' مرج بن جحش ' … فلم يقفوا عليه ، ولم يحاموا\nأقول لمطعم لما التقينا ، … وقد ولى وفي يدي الحسام\nأتجعل بيننا عشرين كعبا … وتهرب ! سوءة لك يا غلام !\nأحلكم بدار الضيم ، قسرا ، … همام لا يضام ، ولا يرام !"},{"id":"diwan-abufiras:218","bookId":"diwan-abufiras","type":"poem","seq":218,"chapter":"البحر: بسيط تام","title":"أشدة ، ما أراه منك ، أم كرم !","page":"","text":"أشدة ، ما أراه منك ، أم كرم ! … تجود بالنفس ، والأرواح تصطلم\nيا باذل النفس والأموال مبتسما ، … أما يهولك لا موت ، ولا عدم ؟ !\nلقد ظننتك ، بين الجحفلين ، ترى … أن السلامة ، من وقع القنا ، تصم\nنشدتك الله ، لا تسمح بنفس علا ، … حياة صاحبها تحيا بها الأمم\nهي الشجاعة إلا أنها سرف ، … وكل فضلك لا قصد ولا أمم\nإذا لقيت رقاق البيض ، منفردا ، … تحت العجاجة لم تستكثر الخدم\nتفدي بنفسك أقواما صنعتهم … وكان حقهم أن يفتدوك هم\nومن يقاتل من تلقى القتال به ، … وليس يفضل عنك الخيل والبهم\nتضن بالحرب عنا ، ضن ذي بخل ، … ومنك ، في كل حال ، يعرف الكرم !\nلا تبخلن على قوم إذا قتلوا … أثنى عليك بنو الهيجاء ، دونهم\nألبست ما لبسوا ، أركبت ما ركبوا … عرفت ما عرفوا ، علمت ما علموا\nكما أريت ببيض ، أنت واهبها ، … على خيولك خاضوا\nهم الفوارس ، في أيديهم أسل ، … فإن رأوك فأسد ، والقنا أجم\nقالوا المسير ! فهز الرمح عامله ، … وارتاح في جفنه الصمصامة الخذم\nفطالبتني بما ساء العداة ، وقد … عودتها ما تشاء الذئب والرخم\nحقا ، لقد ساءني أمر ، ذكرت له ، … لولا فراقك لم يوجد له ألم\nلا تشغلني بأمر ' الشام ' أحرسه … إن الشآم على من حله حرم\nفإن للثغر سورا من مهابته ، … صخوره من أعادي أهله قمم\nلا يحرمني ' سيف الدين ' صحبته … فهي الحياة التي تحيا بها النسم\nوماا عترضت عليه في أوامره … لكن سألت ، ومن عاداته ، نعم !"},{"id":"diwan-abufiras:219","bookId":"diwan-abufiras","type":"poem","seq":219,"chapter":"البحر: بسيط تام","title":"الدين مخترم ، والحق مهتضم ،","page":"","text":"الدين مخترم ، والحق مهتضم ، … وفيء آل ' رسول الله ' مقتسم\nوالناس عندك لا ناس ، فيحفظهم … سوم الرعاة ، ولا شاء ، ولا نعم\nإني أبيت قليل النوم ، أرقني … قلب ، تصارع فيه الهم والهمم !\nوعزمة ، لا ينام الليل صاحبها … إلا على ظفر ، في طيه كرم\nيصان مهري لأمر لا أبوح به ، … والدرع ، والرمح ، والصمصامة الخذم\nوكل مائرة الضبعين ، مسرحها … رمث الجزيرة ، والخذراف والغنم\nوفتية ، قلبهم قلب إذا ركبوا … يوما ؛ ورأيهم رأي إذا عزموا\nيا للرجال ! أما لله منتصف … من الطغاة ؟ أما للدين منتقم ؟ !\n' بنو علي ' رعايا في ديارهم ، … والأمر تملكه النسوان ، والخدم !\nمحلؤون ، فأصفى شربهم وشل ، … عند الورود ؛ وأوفى ودهم لمم\nفالأرض ، إلا على ملاكها ، سعة ، … والمال ، إلا أربابه ، ديم\nوما السعيد بها إلا الذي ظلموا ، … وما الغني بها إلا الذي حرموا\nللمتقين ، من الدنيا ، عواقبها … وإن تعجل منها الظالم الأثم\nلا يطغين ' بني العباس ' ملكهم ! … ' بنو علي ' مواليهم وإن زعموا\nأتفخرون عليهم ؟ - لا أبا لكم - … حتى كأن ' رسول الله ' جدكم\nوما توازن ، يوما ، بينكم شرف ، … ولا تساوت بكم ، في موطن ، قدم\nولا لكم مثلهم ، في المجد ، متصل … ولا لجدكم مسعاة جدهم\nولا لعرقكم من عرقهم شبه … ولا ' نفيلتكم ' من أمهم أمم\nقام النبي بها ' يوم الغدير ' لهم … والله يشهد ، والأملاك ، والأمم\nحتى إذا أصبحت في غير صاحبها … باتت تنازعها الذؤبان والرخم\nوصيرت بينهن شورى كأنهم … لا يعرفون ولاة الحق أيهم !\nتالله ، ماجهل الأقوام موضعها … لكنهم ستروا وجه الذي علموا\nثم ادعاها بنو العباس إرثهم ، … ومالهم قدم ، فيها ، ولا قدم\nلا يذكرون ، إذا ما معشر ذكروا ، … ولا يحكم ، في أمر ، لهم حكم\nولا رآهم ' أبو بكر ' وصاحبه … أهلا لما طلبوا منها ، وما زعموا\nفهل هم مدعوها غير واجبة … أم هل أئمتهم في أخذها ظلموا ؟\nأما ' علي ' فقد أدنى قرابتكم ، … عند الولاية ، إن لم تكفر النعم !\nهل جاحد ، يا ' بني العباس ' نعمته ! … أبوكم ، أم عبيد الله ، أم قثم ؟\nبئس الجزاء جزيتم في بني ' حسن ' ! … أباهم العلم الهادي وأمهم\nلا بيعة ردعتكم عن دمائهم ، … ولا يمين ، ولا قربى ، ولا ذمم\nهلا صفحتم عن الأسرى بلا سبب ، … للصافحين ببدر عن أسيركم ؟\nهلا كففتم عن ' الديباج ' سوطكم ؟ … وعن بنات رسول الله شتمكم ؟\nما نزهت لرسول الله مهجته … عن السياط ! فهلا نزه الحرم ؟\nما نال منهم بنو حرب ، وإن عظمت … تلك الجرائر ، إلا دون نيلكم\nكم غدرة لكم في الدين واضحة ! … وكم دم ل ' رسول الله ' عندكم ؟ !\nأأنتم آله فيما ترون ، وفي … أظفاركم ، من بنيه الطاهرين ، دم ؟\nهيهات ! لاقربت قربى ، ولا رحم ، … يوما ، إذا أقصت الأخلاق والشيم !\nكانت مودة سلمان له رحما ، … ولم يكن بين نوح وابنه رحم !\nياجاهدا في مساويهم يكتمها ! … غدر الرشيد ب ' يحيى ' كيف ينكتم ؟\nليس الرشيد كموسى في القياس ولا … ' مأمونكم ك ' الرضا ' إن أنصف\nذاق الزبيري غب الحنث وانكشفت … عن ' ابن فاطمة ' الأقوال والتهم\nباؤوا بقتل ' الرضا ' من بعد بيعته … وأبصروا بعض يوم رشدهم وعموا\nيا عصبة شقيت ، من بعدما سعدت ، … ومعشرا هلكوا من بعدما سلموا !\nلبئس ما لقيت منهم ، وإن بليت … بجانب ' الطف ' تلك الأعظم الرمم !\nلاعن ' أبي مسلم ' في نصحه صفحوا ، … ولا الهبيري نجى الحلف والقسم\nولاالأمان لأزد ' الموصل ' اعتمدوا … فيه الوفاء ، ولاعن عمهم حلموا\nأبلغ لديك بني العباس مألكة : … لاتدعوا ملكها ! ملاكها العجم !\nأي المفاخر أمست في منابركم ، … وغيركم آمر فيهن ، محتكم ؟\nوهل يزيدكم من مفخر علم ، … وفي الخلاف ، عليكم يخفق العلم ؟\nخلوا الفخار لعلامين ، إن سئلوا … يوم السؤال ، وعمالين إن علموا\nلايغضبون لغيرالله ، إن غضبوا ، … ولا يضيعون حكم الله إن حكموا\nتبدوا التلاوة من أبياتهم ، أبدا ، … وفي بيوتكم الأوتار ، والنغم\nمافي ديارهم للخمر معتصر ؛ … ولا بيوتهم للسوء معتصم\nولا تبيت لهم خنثى ، تنادمهم ؛ … ولا يرى لهم قرد ، له حشم\nالركن ، والبيت ، والأستار منزلهم ، … وزمزم ، والصفا ، والحجر ، والحرم\nصلى الإله عليهم ، أينما ذكروا ، … لأنهم للورى كهف ، ومعتصم"},{"id":"diwan-abufiras:220","bookId":"diwan-abufiras","type":"poem","seq":220,"chapter":"البحر: مخلع البسيط","title":"أللوم للعاشقين لوم ،","page":"","text":"أللوم للعاشقين لوم ، … لأن خطب الهوى عظيم\nفكيف ترجون لي سلوا … وعندي المقعد المقيم ؟\nومقلتي ، ملؤها دموع ؛ … وأضلعي ، حشوها كلوم !\nيا قوم ! إني امرؤ كتوم ، … تصحبني مقلة نموم\nألليل للعاشقين ستر ، … يا ليت أوقاته تدوم !\nنديمي النجم ، طول ليلي ، … حتى إذا غارت النجوم\nأسلمني الصبح للبلايا ، … فلا حبيب ، ولا نديم\nب ' رملتي عالج ' رسوم ، … يطول من دونها الرسيم !\nأنخت فيهن يعملات ، … ما عهد إرقالها ذميم !\nآجدها قطع كل واد ، … أخصبه نبته العميم\nردت على الدهر ، في سراها ، … ما وهب النجم ، والنجوم !\nتلك سجايا من الليالي ، … للبؤس ما يخلق النعيم\nبين ضلوعي هوى مقيم … لآل ' ورقاء ' لا يريم\nيغير الدهر كل شيء ، … وهو صحيح لهم ، سليم !\nأمنع من رامه سواهم … منه ، كما تمنع الحريم\nوهل يساويهم قريب ؟ … أم هل يدانيهم حميم ؟\nونحن في عصبة وأهل ، … تضم أغصاننا أروم\nلم تتفرق بنا خؤول ، … في جذم عز ، ولا عموم !\nسمت بنا وائل ، وفازت … بالعز أخوالنا ' تميم ' !\nودادهم خالص ، صحيح ، … وعهدهم ثابت ، مقيم !\nفذاك منهم بنا حديث ، … وهو لآبائنا قديم\nنرعاه ، ما طرقت بحمل … أنثى ، وما أطفلت بغوم\nندني بني عمنا إلينا ، … فضلا ، كما يفعل الكريم\nأيد لهم ، عند كل خطب ، … يثني بها الفادح الجسيم !\nوألسن ، دونهم ، حداد … لد إذا قامت الخصوم\nلم تنأ ، عنا ، لهم قلوب ، … وإن نأت منهم ، جسوم\nفلا عدمنا لهم ثناء ، … كأنه اللؤلؤ النظيم\nلقد نمتنا لهم أصول ، … ما مس أعراقهن لوم\nتبقى ويبقون في نعيم … ما بقي الركن ، والحطيم !"},{"id":"diwan-abufiras:221","bookId":"diwan-abufiras","type":"poem","seq":221,"chapter":"البحر: سريع","title":"لما تبينت بأني له","page":"","text":"لما تبينت بأني له … أزداد حبا ، كلما لاموا ،\nوددت إذ ذاك ، بأن الورى … فيك ، مدى الأيام ، لوام"},{"id":"diwan-abufiras:222","bookId":"diwan-abufiras","type":"poem","seq":222,"chapter":"البحر: طويل","title":"أما إنه ربع الصبا ومعالمه","page":"","text":"أما إنه ربع الصبا ومعالمه … فلا عذر إن لم ينفذ الدمع ساجمه\nلئن بت تبكيه خلاء فطالما … نعمت به ، دهرا ، وفيه نواعمه\nرياح عفته ، وهي أنفاس عاشق … ووبل سقاه ، والجفون غمائمه\nوظلامة ، قلدتها حكم مهجتي ، … ومن ينصف المظلوم والخصم حاكمه ؟\nمهاة ، لها من كل وجه مصونه ، … وخود لها من كل دمع كرائمه\nوليل كفرعيها قطعت وصاحبي … رقيق غرار ، مخذم الحد صارمه\nتغذ بي القفر الفضاء شملة … سواء عليها نجده وتهائمه\nتصاحبني آرامه وظباؤه ، … وتؤنسني أصلاله وأراقمه\nوأي بلاد الله لم أنتقل بها ! … ولا وطئتها من بعيري مناسمه !\nونحن أناس ، يعلم الله أننا ، … وخود لها من كل دمع كرائمه\nإذا ولد المولود منا فإنما ال … وتؤنسني أصلاله وأراقمه\nإلا مبلغ عني ، ابن عمي ، رسالة … بثثت بها بعض الذي أنا كاتمه\nأيا جافيا ! ما كنت أخشى جفاؤه … وإن كثرت عذاله ، ولوائمه\nكذلك حظي من زماني وأهله … يصارمني الخل الذي لا أصارمه\nوإن كنت مشتاقا إليك فإنه … ليشتاق صب إلفه ، وهو ظالمه\nأودك ودا ، لا الزمان يبيده ، … ولا النأي يفنيه ، ولا الهجر ثالمه\nوأنت وفي لا يذم وفاؤه ، … وأنت كريم ليس تحصى مكارمه\nأقيم به أصل الفخار وفرعه ، … وشد به ركن العلا ، ودعائمه\nأخو السيف تعديه نداوة كفه … فيحمر خداه ، ويخضر قائمه\nأعندك لي عتبى فأحمل ما مضى … وأبني رواق الود ، إذ أنت هادمه"},{"id":"diwan-abufiras:223","bookId":"diwan-abufiras","type":"poem","seq":223,"chapter":"البحر: مجزوء الرمل","title":"أيها الغازي ، الذي يغ","page":"","text":"أيها الغازي ، الذي يغ … زو بجيش الحب جسمي !\nما يقوم الأجر في غز … وك للروم بإثمي !\nكم ليلة شهباء ، إذ برزت لنا ، … سقتك الغوادي من متون الغمائم\nمن ثغرها في جنح ليل مظلم … \nكتمت هواي وقابلته بهجرة ، … في جمرها المتلهب المتضرم"},{"id":"diwan-abufiras:224","bookId":"diwan-abufiras","type":"poem","seq":224,"chapter":"البحر: كامل تام","title":"وأديبة إخترتها عربية","page":"","text":"وأديبة إخترتها عربية … تعزى إلى الجد الكريم ، وتنتمي\nمحجوبة لم تبتذل ، أمارة … لم تأتمر ، مخدومة لم تخدم\nلو لم يكن لي فيك إلا أنني … بك قد غنيت عن ارتكاب المحرم\nولقد نزلت فلا تظني غيره … مني بمنزلة المحب المكرم"},{"id":"diwan-abufiras:225","bookId":"diwan-abufiras","type":"poem","seq":225,"chapter":"البحر: وافر تام","title":"تسمع ، في بيوت بني كلاب ،","page":"","text":"تسمع ، في بيوت بني كلاب ، … بني البنا تنوح على تميم\nبكرهي إن حملت بني أبيه … وأسرته على النأي العظيم\nرجعت ، وقد ملكتهم جميعا ، … إلى الأعراق والأصل الكريم"},{"id":"diwan-abufiras:226","bookId":"diwan-abufiras","type":"poem","seq":226,"chapter":"البحر: وافر تام","title":"يعز على الأحبة ، ب ' الشام ' ،","page":"","text":"يعز على الأحبة ، ب ' الشام ' ، … حبيب ، بات ممنوع المنام\nوإني للصبور على الرزايا ، … ولكن الكلام على الكلام\nجروح لا يزلن يردن مني … على جرح قريب العهد ، دام\nتاملني ' الدمستق ' إذ رآني ، … فأبصر صيغة الليث ، الهمام\nأتنكرني كأنك لست تدري … بأني ذلك البطل ، المحامي\nوأني إذ نزلت على دلوك ، … تركتك غير متصل النظام\nولما أن عددت صليب رأيي … تحلل عقد رأيك في المقام\nوكنت ترى الأناة ، وتدعيها ، … فأعجلك الطعان عن الكلام\nوبت مؤرقا ، من غير سهد ، … حمى جفنيك طيب النوم حام\nولا أرضى الفتى ما لم يكمل ، … برأي الكهل ، إقدام الغلام\nفلا هنئتها نعمى بأسري ، … ولا وصلت سعودك بالتمام\nأما من أعجب الأشياء علج ، … يعرفني الحلال من الحرام\nوتكنفه بطارقة تيوس ، … تباري بالعثانين الضخام\nلهم خلق الحمير فلست تلقى … فتى منهم يسير بلا حزام\nيريغون العيوب ، وأعجزتهم ، … وأي العيب يوجد في الحسام ! ؟\nوأصعب خطة ، وأجل أمر … مجالسة اللئام على الكرام\nأبيت مبرأ من كل عيب ، … وأصبح ، سالما من كل ذام\nومن لقي الذي لاقيت هانت … عليه موارد الموت الزؤام\nثناء طيب ، لا خلف فيه ، … وآثار كآثار الغمام\nوعلم فوارس الحيين أني … قليل من يقوم لهم مقامي\nوفي طلب الثناء مضى بجير … وجاد بنفسه كعب بن مام\nألام على التعرض للمنايا ، … ولي سمع أصم عن الملام\nبنو الدنيا إذا ماتوا سواء … ولو عمر المعمر ألف عام\nإذا ما لاح لي لمعان برق … بعثت إلى الأحبة بالسلام"},{"id":"diwan-abufiras:227","bookId":"diwan-abufiras","type":"poem","seq":227,"chapter":"البحر: خفيف تام","title":"لست بالمستضيم من هو دوني ،","page":"","text":"لست بالمستضيم من هو دوني ، … اعتداء ، ولست بالمستضام\nأبذل الحق للخصوم ، إذا ما … عجزت عنه قدرة الحكام\nلا تخطى إلى المظالم كفي ، … حذرا من أصابع الأيتام"},{"id":"diwan-abufiras:228","bookId":"diwan-abufiras","type":"poem","seq":228,"chapter":"البحر: خفيف تام","title":"ودعوا ، خشية الرقيب ، بإيما","page":"","text":"ودعوا ، خشية الرقيب ، بإيما … ء ، فودعت ، خشية اللوام\nلم أبح بالوداع ، جهرا ولكن … كان جفني فمي ، ودمعي كلامي !"},{"id":"diwan-abufiras:229","bookId":"diwan-abufiras","type":"poem","seq":229,"chapter":"البحر: سريع","title":"أيا معافي من رسيس الهوى !","page":"","text":"أيا معافي من رسيس الهوى ! … يهنيك حال السالم الغانم\nأعانك الله بخير ، أما … تكون لي عونا على الظالم ؟ !"},{"id":"diwan-abufiras:230","bookId":"diwan-abufiras","type":"poem","seq":230,"chapter":"البحر: كامل تام","title":"وخريدة ، كرمت على آبائها ؛","page":"","text":"وخريدة ، كرمت على آبائها ؛ … وعلى بوادر خيلنا لم تكرم\nخطبت بحد السيف حتى زوجت … كرها ، وكان صداقها للمقسم\nراحت وصاحبها بعرس حاضر ، … يرضي الآله ، وأهلها في مأتم"},{"id":"diwan-abufiras:231","bookId":"diwan-abufiras","type":"poem","seq":231,"chapter":"البحر: وافر تام","title":"لنا بيت ، على عنق الثريا ،","page":"","text":"لنا بيت ، على عنق الثريا ، … بعيد مذاهب الأطناب ، سام\nتظلله الفوارس بالعوالي ، … وتفرشه الولائد بالطعام"},{"id":"diwan-abufiras:232","bookId":"diwan-abufiras","type":"poem","seq":232,"chapter":"البحر: مجزوء الكامل","title":"يا من رضيت بفرط ظلمه","page":"","text":"يا من رضيت بفرط ظلمه … ودخلت ، طوعا ، تحت حكمه\nألله يعلم ما لقي … ت من الهوى ، وكفى بعلمه !\nهب للمقر بذنبه ! … واصفح له عن عظم جرمه\nإني أعيذك أن تبو … ء بقتله ، وبحمل إثمه"},{"id":"diwan-abufiras:233","bookId":"diwan-abufiras","type":"poem","seq":233,"chapter":"البحر: كامل تام","title":"هبه أساء ، كما زعمت ، فهب له","page":"","text":"هبه أساء ، كما زعمت ، فهب له … وارحم تضرعه ، وذل مقامه !\nبالله ، ربك ، لم فتكت بصبره … ونصرت بالهجران جيش سقامه ؟\nفرقت بين جفونه ومنامه … وجمعت بين نحوله وعظامه"},{"id":"diwan-abufiras:234","bookId":"diwan-abufiras","type":"poem","seq":234,"chapter":"البحر: بسيط تام","title":"إذا مررت بواد ، جاش غاربه","page":"","text":"إذا مررت بواد ، جاش غاربه … فاعقل قلوصك وانزل ، ذاك وادينا\nوإن عبرت بناد لا تطيف به … أهل السفاهة ، فاجلس ، ذاك نادينا !\nنغير في الهجمة الغراء ننحرها … حتى ليعطش ، في الأحيان ، راعينا\nوتجفل الشول بعد الخمس صادية … إذا سمعن على الأمواه حادينا\nونفتدي الكوم أشتاتا مروعة … لا تأمن الدهر إلا من أعادينا\nويصبح الضيف أولانا بمنزلنا ، … نرضى بذاك ، ويمضي حكمه فينا"},{"id":"diwan-abufiras:235","bookId":"diwan-abufiras","type":"poem","seq":235,"chapter":"البحر: كامل تام","title":"وكنى الرسول عن الجواب تظرفا","page":"","text":"وكنى الرسول عن الجواب تظرفا … ولئن كنى ، فلقد علمنا ما عنى\nقل يا رسول ، ولا تحاش ! فإنه … لا بد منه أساء بي أم أحسنا !\nألذنب لي فيما جناه ، لأنني … مكنته من مهجتي فتمكنا"},{"id":"diwan-abufiras:236","bookId":"diwan-abufiras","type":"poem","seq":236,"chapter":"البحر: طويل","title":"ويغتابني من لو كفاني غيبه","page":"","text":"ويغتابني من لو كفاني غيبه … لكنت له العين البصيرة والأذنا\nوعندي من الأخبار ما لو ذكرته … إذا قرع المغتاب من ندم سنا"},{"id":"diwan-abufiras:237","bookId":"diwan-abufiras","type":"poem","seq":237,"chapter":"البحر: مجزوء الرمل","title":"اطرحوا الأمر إلينا ،","page":"","text":"اطرحوا الأمر إلينا ، … واحملوا الكل علينا\nإننا قوم ، إذا ما … صعب الأمر ، كفينا\nوإذا ما ريم منا … موطن الذل أبينا\nوإذا ما هدم ال … عز بنو العز بنينا"},{"id":"diwan-abufiras:238","bookId":"diwan-abufiras","type":"poem","seq":238,"chapter":"البحر: وافر تام","title":"يعيب علي أن سميت نفسي","page":"","text":"يعيب علي أن سميت نفسي … وقد أخذ القنا منهم ومنا\nفقل للعلج : لو لم أسم نفسي … لسماني السنان لهم وكنى"},{"id":"diwan-abufiras:239","bookId":"diwan-abufiras","type":"poem","seq":239,"chapter":"البحر: خفيف تام","title":"قد أعانتني الحمية لما","page":"","text":"قد أعانتني الحمية لما … لم أجد من عشيرتي أعوانا\nلا أحب الجميل من سر مولى … لم يدع ما كرهته إعلانا\nإن يكن صادق الوداد فهلا … ترك الهجر للوصال مكانا ! ؟"},{"id":"diwan-abufiras:240","bookId":"diwan-abufiras","type":"poem","seq":240,"chapter":"البحر: وافر تام","title":"فإن أهلك فعن أجل مسمى سلي فتيات هذا الحي عني","page":"","text":"فإن أهلك فعن أجل مسمى سلي فتيات هذا الحي عني … يقلن بما رأين وما سمعنه\nألست أمدهم ، لذوي ، ظلا ، … ألست أعدهم ، للقوم ، جفنه\nألست أقرهم بالضيف ، عينا … ألست أمرهم ، في الحرب لهنه\nرضيت العاذلات ، وما يقلنه ، … وإن أصبحت عصاء لهنه\nوكم فجر سبقن إلى ملامي … فعدت ضحى ولم أحفل بهنه\nوراجعة إلي ، تقول سرا : … أعود إلى نصيحته لعنه\nفلما لم تجد طمعا تولت ، … وقالت في ، عاتبة وقلنه\nأريتك ما تقول بنات عمي … إذا وصف النساء رجالهنه\nأما والله لا يمسين ، حسرى ، … يلفقن الكلام ، ويعتذرنه\nولكن سوف أوجدهن وصفا … وأبسط في المديح كلامهنه\nمتى ما يدن من أجل كتابي … أمت ، بين الأعنة والأسنه"},{"id":"diwan-abufiras:241","bookId":"diwan-abufiras","type":"poem","seq":241,"chapter":"البحر: وافر تام","title":"بكرن يلمنني ، ورأين جودي","page":"","text":"بكرن يلمنني ، ورأين جودي … على الأرماح بالنفس المضنه\nفقلت لهن : هل فيكن باق … على نوب الزمان ، إذا طرقنه ؟\nوإن يكن الحذار من المنايا … سبيلا للحياة ، فلم تمتنه ؟\nسأشهدها على ما كان مني … ببسطي في الندى ، بكلامهنه\nوأجعلكن أصدق في قولا … إذا وصف النساء رجالهنه\nفإن أهلك فعن أجل مسمى … سيأتيني ، ولو ما بينكنه\nوإن أسلم فقرض سوف يوفى ، … وأتبعكن إن قدمتكنه\nفلا يأمرنني بمقام ذل … فما أنا بالمطيع إذا أمرنه\nوموت في مقام العز أشهى ، … إلى الفرسان ، من عيش بمهنه"},{"id":"diwan-abufiras:242","bookId":"diwan-abufiras","type":"poem","seq":242,"chapter":"البحر: بسيط تام","title":"يا من رجعت ، على كره ، لطاعته ،","page":"","text":"يا من رجعت ، على كره ، لطاعته ، … قد خالف القلب لما طاوع البدن\nوكل ما شئت من أمر رضيت به ، … وكل ما اخترته ، عندي هو الحسن\nوكلما سرني أو ساءني سبب … فأنت فيه علي ، الدهر ، مؤتمن"},{"id":"diwan-abufiras:243","bookId":"diwan-abufiras","type":"poem","seq":243,"chapter":"البحر: طويل","title":"وإني لأنوي هجره فيردني وإني لأنوي هجره فيردني","page":"","text":"وإني لأنوي هجره فيردني وإني لأنوي هجره فيردني … هوى ، بين أثناء الضلوع ، دفين\nفيغلظ قلبي ، ساعة ثم ينثني … وأقسو عليه ، تارة ، ويلين\nوقد كان لي عن وده كل مذهب ، … ولكن مثلي بالإخاء ضنين\nولا غرو أن أعنو له ، بعد عزة ، … فقدري ، في عز الحبيب ، يهون !"},{"id":"diwan-abufiras:244","bookId":"diwan-abufiras","type":"poem","seq":244,"chapter":"البحر: طويل","title":"بخلت بنفسي أن يقال مبخل ،","page":"","text":"بخلت بنفسي أن يقال مبخل ، … وأقدمت جبنا أن يقال جبان\nوملكي بقايا ما وهبت : مفاضة ، … "},{"id":"diwan-abufiras:245","bookId":"diwan-abufiras","type":"poem","seq":245,"chapter":"البحر: طويل","title":"أيا راكبا ، نحو الجزيرة ، جسرة","page":"","text":"أيا راكبا ، نحو الجزيرة ، جسرة … عذافرة ، إن الحديث شجون !\nمن الموخدات الضمر اللاء وخدها … كفيل بحاجات الرجال ضمين\nتحمل إلى ' القاضي ' سلامي وقل له : … ألا إن قلبي ، مذ حزنت ، حزين\nوإن فؤادي ، لافتقاد أسيره ، … أسير ، بأيدي الحادثات ، رهين\nأحاول كتمان الذي بي من الأسى … وتأبى غروب ثرة وشؤون\nبمن أنا في الدنيا على السر واثق ، … وطرفي نموم ، والدموع تخون\nيضن زماني بالثقات ؛ وإنني … بسري ، على غير الثقات ، ضنين\nلعل زمانا بالمسرة ينثني ؛ … وعطفة دهر باللقاء تكون\nألا لا يرى الأعداء فيك غضاضة ، … فللدهر بؤس ، قد علمت ، ولين\nوأعظم ما كانت همومك تنجلي ، … وأصعب ما كان الزمان يهون\nألا ليت شعري هل أنا الدهر ، واجد … قرينا ، له حسن الوفاء قرين ؟\nفأشكو ويشكو ما بقلبي وقلبه ، … كلانا ، على نجوى أخيه ، أمين\nوفي بعض من يلقي إليك مودة … عدو ، إذا كشفت عنه ، مبين\nإذا غير البعد الهوى فهوى أبي … حصين منيع ، في الفؤاد ، حصين\nفلا برحت بالحاسدين كآبة ، … ولا هجعت للشامتين عيون"},{"id":"diwan-abufiras:246","bookId":"diwan-abufiras","type":"poem","seq":246,"chapter":"البحر: مجزوء الكامل","title":"أشفقت من هجري فغل","page":"","text":"أشفقت من هجري فغل … بت الظنون على اليقين\nوضننت بي ، فظننت بي ، … والظن من شيم الضنين !"},{"id":"diwan-abufiras:247","bookId":"diwan-abufiras","type":"poem","seq":247,"chapter":"البحر: مخلع البسيط","title":"لطيرتي بالصداع نالت","page":"","text":"لطيرتي بالصداع نالت … فوق منال الصداع مني\nوجدت فيه اتفاق سوء … صدعني مثل صد عني"},{"id":"diwan-abufiras:248","bookId":"diwan-abufiras","type":"poem","seq":248,"chapter":"البحر: كامل تام","title":"الحر يصبر ، ما أطاق تصبرا","page":"","text":"الحر يصبر ، ما أطاق تصبرا … في كل آونة وكل زمان\nويرى مساعدة الكرام مروءة ، … ما سالمته نوائب الحدثان\nويذوب بالكتمان إلا أنه … أحواله تنبي عن الكتمان\nفإذا تكشف ، واضمحلت حاله … ألفيته يشكو بكل لسان\nوإذا نبا بي منزل فارقته ؛ … والله يلطف بي بكل مكان"},{"id":"diwan-abufiras:249","bookId":"diwan-abufiras","type":"poem","seq":249,"chapter":"البحر: مجزوء الكامل","title":"لا غرو إن فتنتك بال","page":"","text":"لا غرو إن فتنتك بال … لحظات فاترة الجفون\nفمصارع العشاق ما … بين الفتور إلى الفتون\nاصبر ! فمن سنن الهوى … صبر الظنين على الظنين"},{"id":"diwan-abufiras:250","bookId":"diwan-abufiras","type":"poem","seq":250,"chapter":"البحر: سريع","title":"علي من عيني عينان","page":"","text":"علي من عيني عينان … تبوح للناس بكتمان\nيا ظالمي ، للشرب سكر ولي … من غنج ألحاظك سكران\nوجهك والبدر ، إذا أبرزا ، … لأعين العالم ، بدران"},{"id":"diwan-abufiras:251","bookId":"diwan-abufiras","type":"poem","seq":251,"chapter":"البحر: متقارب تام","title":"أنافس فيك بعلق ثمين ،","page":"","text":"أنافس فيك بعلق ثمين ، … ويغلبني فيك ظن الظنين\nوكنت حلفت على غضبة … فعدت ، وكفرت عنها يميني"},{"id":"diwan-abufiras:252","bookId":"diwan-abufiras","type":"poem","seq":252,"chapter":"البحر: متقارب تام","title":"حللت من المجد أعلى مكان ،","page":"","text":"حللت من المجد أعلى مكان ، … وبلغك الله أقصى الأماني\nفإنك ، لا عدمتك العلا ، … أخ لا كإخوة هذا الزمان\nصفاؤك في البعد مثل الدنو ، … وودك في القلب مثل اللسان\nكسونا أخوتنا بالصفاء … كما كسيت بالكلام المعاني"},{"id":"diwan-abufiras:253","bookId":"diwan-abufiras","type":"poem","seq":253,"chapter":"البحر: بسيط تام","title":"ما كنت مذ كنت إلا طوع خلاني ،","page":"","text":"ما كنت مذ كنت إلا طوع خلاني ، … ليست مؤاخذة الإخوان من شاني\nيجني الخليل ، فأستحلي جنايته … حتى أدل على عفوي وإحساني\nويتبع الذنب ذنبا حين يعرفني … عمدا ، وأتبع غفرانا بغفران\nيجني علي وأحنو ، صافحا أبدا ، … لا شيء أحسن من حان على جان"},{"id":"diwan-abufiras:254","bookId":"diwan-abufiras","type":"poem","seq":254,"chapter":"البحر: بسيط تام","title":"بني زرارة لو صحت طرائقكم","page":"","text":"بني زرارة لو صحت طرائقكم … لكنتم عندنا في المنزل الداني\nلكن جهلتهم لدينا حق أنفسكم ، … وباع بائعكم ربحا بخسران\nفإن تكونوا براء ، من جنايته ؛ … فإن من رفد الجاني هو الجاني\nما بالكم ! يا أقل الله خيركم … لا تغضبون لهذا الموثق العاني ؟\nجار نزعناه قسرا في بيوتكم ، … والخيل تعصب فرسانا بفرسان\nإذ لاتردون عن أكناف أهلكم … شوازب الخيل من مثنى ووحدان\nب ' المرج ' ، إذ ' أم بسام ' تناشدني : … بنات عمك ! يا ' حار بن حمدان '\nفظلت أثني صدور الخيل ساهمة … بكل مضطغن بالحقد ، ملآن\nونحن قوم ، إذا عدنا بسيئة … على العشيرة ، أعقبنا بإحسان"},{"id":"diwan-abufiras:255","bookId":"diwan-abufiras","type":"poem","seq":255,"chapter":"البحر: كامل تام","title":"أتعز أنت على رسوم مغان ،","page":"","text":"أتعز أنت على رسوم مغان ، … فأقيم للعبرات سوق هوان\nفرض علي ، لكل دار وقفة … تقضي حقوق الدار والأجفان\nلولا تذكر من هويت ب ' حاجر ' … لم أبك فيه مواقد النيران\nولقد أراه ، قبيل طارقة النوى ، … مأوى الحسان ، ومنزل الضيفان\nومكان كل مهند ، ومجر ك … ل مثقف ، ومجال كل حصان\nنشر الزمان عليه ، بعد أنيسه ، … حلل الفناء ؛ وكل شيء فان !\nولقد وقفت فسرني ما ساءني … فيه ، وأضحكني الذي أبكاني\nورأيت في عرصاته مجموعة … أسد الشرى ، وربائب الغزلان\nيا واقفان ، معي ، على الدار اطلبا … غيري لها ، إن كنتما تقفان !\nمنع الوقوف ، على المنازل ، طارق … أمر الدموع بمقلتي ونهاني\nفله ، إذا ونت المدامع أو همت ، … عصيان دمعي ، فيه ، أو عصياني\nإنا لجمعنا البكاء ، وكلنا … يبكي على شجن من الأشجار\nولقد جعلت الحب ستر مدامعي … ولغيره عيناي تنهملان\nأبكي الأحبة بالشآم ، وبيننا … قلل الدروب وشاطئا جيحان\nوحسبت فيما أشعلت نيراني … مثلي على كنف من الأحزان\nفضلت لدي مدامع فبكيت لل … باكي بها ، وولهت للولهان\nما لي جزعت من الخطوب وإنما … أخذ المهيمن بعض ما أعطاني\nولقد سررت كما غممت عشائري … زمنا ، وهنأني الذي عناني\nوأسرت في مجرى خيولي غازيا … وحبست فيما أشعلت نيراني\nيرمي بنا ، شطر البلاد ، مشيع … صدق الكريهة ، فائض الإحسان\nبلد ، لعمرك ، لم أزل زواره … مع سيد قرم أغر ، هجان\nإنا لنلقى الخطب فيك وغيره … بموفق عند الخطوب ، معان\nولطالما حطمت صدر مثقف ، … ولطالما أرعفت أنف سنان\nولطالما قدت الجياد إلى الوغى … قب البطون ، طويلة الأرسان\nوأنا الذي ملأ البسيطة كلها … ناري ، وطنب في السماء دخاني\nإن لم تكن طالت سني فإن لي … رأي الكهول ونجدة الشبان\nقمن ، بما ساء الأعادي ، موقفي ، … والدهر يبرز لي مع الأقران\nيمضي الزمان ، وما ظفرت بصاحب … إلا ظفرت بصاحب خوان\nيا دهر خنت مع الأصادق خلتي … وغدرت بي في جملة الإخوان\nلكن سيف الدولة المولى الذي … لم أنسه وأراه لا ينساني\nأيضيعني من لم يزل لي حافظا ، … كرما ، ويخفضني الذي أعلاني !\nخدن الوفاء ، ولا وفي غيره ، … يرضى أعاني ضيق حالة عان\nإني أغار على مكاني أن أرى … فيه رجالا لا تسد مكاني\nأو أن تكون وقيعة أو غارة … ما لي بها أثر مع الفتيان\nإقرا السلام ، على الذين سيوفهم … ما أحرجوا ، عطفوا على هامان\nسيف الهدى من حد سيفك يرتجى … يوم ، يذل الكفر للإيمان\nهذي الجيوش ، تجيش نحو بلادكم … محفوفة بالكفر والصلبان\nألبغي أكثر ما تقل خيولهم … والبغي شر مصاحب الإنسان\nليسوا ينون ، فلا تنوا في أمركم ، … لا ينهض الواني لغير الواني\nغضبا لدين الله أن لا تغضبوا … لم يشتهر في نصره سيفان\nحتى كأن الوحي فيكم منزل ، … ولكم تخص فضائل القرآن\nقد أغضبوكم فاغضبوا ، وتأهبوا … للحرب أهبة ثائر ، غضبان\nف ' بنو كلاب ' وهي قل أغضبت … فدهت قبائل ' مسهر بن قنان '\nوبنو عباد ، حين أحرج حارث … جروا التخالف في ' بني شيبان '\nخلا ' عديا ' ، وهو صاحب ثأرهم … كرما ، ونالوا الثأر بابن أبان\nوالمسلمون ، بشاطيء ' اليرموك ' لم … \nوحماة ' هاشم ' حين أخرج صدرها … جروا البلاء على ' بني مروان '\nوالتغلبيون احتموا عن مثلها … فعدوا على العادين ب ' السلان '\nوبغى على ' عبس ' ' حذيفة ' فاشتفت … منه صوارمهم ومن ذبيان\nوسراة ' بكر ' ، بعد ضيق فرقوا … جمع الأعاجم عن ' أنوشروان '\nأبقت لبكر مفخرا ، وسما لها ، … من دون قومهما ، يزيد وهاني\nالمانعين العنقفير بطعنهم ، … والثائرين بمقتل ' النعمان ' !"},{"id":"diwan-abufiras:256","bookId":"diwan-abufiras","type":"poem","seq":256,"chapter":"البحر: كامل تام","title":"ما صاحبي إلا الذي من بشره","page":"","text":"ما صاحبي إلا الذي من بشره … عنوانه في وجهه ولسانه\nكم صاحب لم أغن عن إنصافه … في عسره ، وغنيت عن إحسانه"},{"id":"diwan-abufiras:257","bookId":"diwan-abufiras","type":"poem","seq":257,"chapter":"البحر: طويل","title":"","page":"","text":" … علاها ، وإن ضاق الخناق حماها\nوما اشتورت إلا وأصبح شيخها ، … ولا أحربت إلا وكان فتاها\nولا ضربت بين القباب قبابه ، … وأصبح مأوى الطارقين سواها"},{"id":"diwan-abufiras:258","bookId":"diwan-abufiras","type":"poem","seq":258,"chapter":"البحر: بسيط تام","title":"يا ليلة ، لست أنسى طيبها أبدا ،","page":"","text":"يا ليلة ، لست أنسى طيبها أبدا ، … كأن كل سرور حاضر فيها\nباتت ، وبت ، وبات الزق ثالثنا … حتى الصباح تسقيني وأسقيها\nكأن سود عناقيد بلمتها ، … أهدت سلافتها صرفا ، إلى فيها"},{"id":"diwan-abufiras:259","bookId":"diwan-abufiras","type":"poem","seq":259,"chapter":"البحر: وافر تام","title":"لقد علمت سراة الحي أنا","page":"","text":"لقد علمت سراة الحي أنا … لنا الجبل الممنع جانباه\nيفيء الرغبون إلى ذراه ، … ويأوي الخائفون إلى حماه"},{"id":"diwan-abufiras:260","bookId":"diwan-abufiras","type":"poem","seq":260,"chapter":"البحر: مخلع البسيط","title":"","page":"","text":" … خلوت ، يوم الفراق ، منه\nما تركت لي الجفون إلا … ما استنزلتني الخدود عنه\nقد طال يا قلب ما تلاقي ، … إن مات ذو صبوة فكنه"},{"id":"diwan-abufiras:261","bookId":"diwan-abufiras","type":"poem","seq":261,"chapter":"البحر: كامل تام","title":"خفض عليك ! ولا تبت قلق الحشا","page":"","text":"خفض عليك ! ولا تبت قلق الحشا … مما يكون ، وعله ، وعساه\nفالدهر أقصر مدة مما ترى ، … وعساك أن تكفى الذي تخشاه"},{"id":"diwan-abufiras:262","bookId":"diwan-abufiras","type":"poem","seq":262,"chapter":"البحر: خفيف تام","title":"لست أرجو النجاة ، من كل ما أخ","page":"","text":"لست أرجو النجاة ، من كل ما أخ … شاه ، إلا بأحمد وعلي\nوببنت الرسول فاطمة الطه … ر ، وسبطيه والإمام علي\nوالتقي النقي باقر علم ال … له فينا ، محمد بن علي\nوابنه ' جعفر ' و' موسى ' ومولا … نا علي ، أكرم به من علي !\nوأبي جعفر سمي رسول ال … له ، ثم ابنه الزكي ' علي '\nوابنه ' العسكري ' والقائم المظ … هر حقي محمد بن علي\nفيهم أرتجي بلوغ الأماني … "},{"id":"diwan-abufiras:263","bookId":"diwan-abufiras","type":"poem","seq":263,"chapter":"البحر: هزج","title":"عرفت الشر لا للشر","page":"","text":"عرفت الشر لا للشر … لكن لتوقيه\nومن لم يعرف الشر … من الناس يقع فيه"},{"id":"diwan-abufiras:264","bookId":"diwan-abufiras","type":"poem","seq":264,"chapter":"البحر: مجتث","title":"قلبي يحن إليه","page":"","text":"قلبي يحن إليه … نعم ، ويحنو عليه\nوما جنى أو تجنى … إلا اعتذرت إليه\nفكيف أملك قلبي ، … والقلب رهن لديه ؟\nوكيف أدعوه عبدي ، … وعهدتي في يديه ؟"},{"id":"diwan-abufiras:265","bookId":"diwan-abufiras","type":"poem","seq":265,"chapter":"البحر: مجتث","title":"ألورد في وجنتيه ،","page":"","text":"ألورد في وجنتيه ، … والسحر في مقلتيه !\nوإن عصاه لساني … فالقلب طوع يديه !\nيا ظالما ، لست أدري … أدعو له ، أم عليه !\nأنا إلى الله مما … دفعت منه إليه !"},{"id":"diwan-abufiras:266","bookId":"diwan-abufiras","type":"poem","seq":266,"chapter":"البحر: مجزوء الكامل","title":"لمن الجدود الأكرمو","page":"","text":"لمن الجدود الأكرمو … ن ، من الورى ، إلا ليه ؟\nمن ذا يعد ، كما أعد ، … من الجدود العاليه ؟\nمن ذا يقوم لقومه ، … بين الصفوف ، مقاميه ! ؟\nمن ذا يرد صدوره … ن ، إذا أغرن علانيه ؟\nأحمي حريمي أن يبا … ح ، ولست أحمي ماليه !\nوتخافني كوم اللقا … ح ، وقد أمن عداتيه\nتمسي ، إذا طرق الضيو … ف ، فناؤها بفنائيه\nناري ، على شرف تأج … ج ، للضيوف الساريه\nيا نار ، إن لم تجلبي … ضيفا ، فلست بناريه !\nوالعز مضروب السرا … دق والقباب الجاريه\nيجني ولا يجنى علي … ه ، ويتقي الجلى بيه !"},{"id":"diwan-abufiras:267","bookId":"diwan-abufiras","type":"poem","seq":267,"chapter":"البحر: مجزوء الكامل","title":"انظر لضعفي ، ياقوي !","page":"","text":"انظر لضعفي ، ياقوي ! … وكن لفقري ، يا غني !\nأحسن إلي ؛ فإنني … عبد إلى نفسي مسي !"},{"id":"diwan-abufiras:268","bookId":"diwan-abufiras","type":"poem","seq":268,"chapter":"البحر: مجزوء الكامل","title":"لولا العجوز بمنبج","page":"","text":"لولا العجوز بمنبج … ما خفت أسباب المنيه\nولكان لي ، عما سأل … ت من الفدا ، نفس أبيه\nلكن أردت مرادها ، … ولو انجذبت إلى الدنيه\nوأرى محاماتي علي … ها أن تضام من الحميه\nأمست ب ' منبج ' ، حرة … بالحزن ، من بعدي ، حريه\nلو كان يدفع حادث ، … أو طارق بجميل نيه\nلم تطرق نوب الحوا … دث أرض هاتيك التقيه\nلكن قضاء الله ، وال … أحكام تنفذ في البريه\nوالصبر يأتي كل ذي … رزء على قدر الرزيه\nلا زال يطرق منبجا ، … في كل غادية ، تحيه\nفيها التقى ، والدين مج … موعان في نفس زكيه\nيا أمتا ! لا تحزني ، … وثقي بفضل الله فيه !\nيا أمتا ! لا تيأسي ، … لله ألطاف خفيه\nكم حادث عنا جلا … ه ، وكم كفانا من بليه\nأوصيك بالصبر الجمي … ل ! فإنه خير الوصيه !"},{"id":"diwan-abufiras:269","bookId":"diwan-abufiras","type":"poem","seq":269,"chapter":"البحر: رجز تام","title":"ما العمر ما طالت به الدهور ،","page":"","text":"ما العمر ما طالت به الدهور ، … العمر ما تم به السرور !\nأيام عزي ، ونفاذ أمري … هي التي أحسبها من عمري\nما أجور الدهر على بنيه ! … وأغدر الدهر بمن يصفيه !\nلو شئت مما قد قللن جدا … عددت أيام السرور عدا\nأنعت يوما ، مر لي ب ' الشام ' ، … ألذ ما مر من الأيام\nدعوت بالصقار ، ذات يوم ، … عند انتباهي ، سحرا من نومي\nقلت له : اختر سبعة كبارا … كل نجيب يرد الغبارا\nيكون للأرنب منها اثنان ، … وخمسة تفرد للغزلان\nواجعل كلاب الصيد نوبتين … ترسل منها اثنين بعد اثنين\nولا تؤخر أكلب العراض ! … فهن حتف للظباء قاض\nثم تقدمت إلى الفهاد … والبازيارين بالاستعداد\nوقلت : إن خمسة لتقنع … والزرقان : الفرخ والملمع\nوأنت ، يا طباخ ، لا تباطا ! … عجل لنا اللبات والأوساطا !\nويا شرابي البلقسيات … تكون بالراح ميسرات\nبالله لا تستصحبوا ثقيلا ! … واجتنبوا الكثرة والفضولا !\nردوا فلانا ، وخذوا فلانا ! … وضمنوني صيدكم ضمانا !\nفاخترت ، لما وقفوا طويلا ، … عشرين ، أو فويقها قليلا\nعصابة ، أكرم بها عصابه ، … معروفة بالفضل والنجابه\nثم قصدنا صيد عين قاصر … مظنة الصيد لكل خابر\nجئناه والشمس ، قبيل المغرب … تختال في ثوب الأصيل المذهب\nوأخذ الدراج في الصياح ، … مكتنفا من سائر النواحي\nفي غفلة عنا وفي ضلال ، … ونحن قد زرناه بالآجال\nيطرب للصبح ، وليس يدري … أن المنايا في طلوع الفجر\nحتى إذا أحسست بالصباح … ناديتهم : ' حي على الفلاح ! '\nنحن نصلي والبزاة تخرج … مجردات ، والخيول تسرج\nفقلت للفهاد : فامض وانفرد … وصح بنا ، إن عن ظبي ، واجتهد\nفلم يزل ، غير بعيد عنا ، … إليه يمضي ما يفر منا\nوسرت في صف من الرجال ، … كأنما نزحف للقتال\nفما استوينا كلنا حتى وقف … لما رآنا مال بالأعناق\nثم أتاني عجلا ، قال : ألسبق ! … فقلت : إن كان العيان قد صدق\nسرت إليه فأراني جاثمه … ظننتها يقظى وكانت نائمه\nثم أخذت نبلة كانت معي ، … ودرت دورين ولم أوسع\nحتى تمكنت ، فلم أخط الطلب ، … لكل حتف سبب من السبب\nوضجت الكلاب في المقاود ، … تطلبها وهي بجهد جاهد\nوصحت بالأسود كالخطاف … ليس بأبيض ولا غطراف\nثم دعوت القوم : هذا بازي ! … فأيكم ينشط للبراز ؟\nفقال منهم رشأ : ' أنا ، أنا ! ' … ولو درى ما بيدي لأذعنا !\nفقلت : قابلني وراء النهر ، … أنت لشطر وأنا لشطر !\nطارت له دراجة فأرسلا … أحسن فيها بازه وأجملا\nعلقها فعطعطوا ، وصاحوا ، … والصيد من آلته الصياح !\nفقلت : ما هذا الصياح والقلق ؟ … أكل هذا فرح بذا الطلق ؟\nفقال : إن الكلب يشوي البازا … قد حرز الكلب ، فجز ، وجازا\nفلم يزل يزعق : يا مولائي ! … وهو كمثل النار في الحلفاء\nطارت ، فأرسلت فكانت سلوى … حلت بها قبل العلو البلوى\nفما رفعت الباز حتى طارا … آخر عودا يحسن الفرارا\nأسود ، صياح ، كريم ، كرز ، … مطرز ، مكحل ، ملزز\nعليه ألوان من الثياب … من حلل الديباج والعنابي\nفلم يزل يعلو وبازي يسفل … يحرز فضل السبق ليس يغفل\nيرقبه من تحته بعينه ، … وإنما يرقبه لحينه\nحتى إذا قارب ، فيما يحسب ، … معقله ؛ والموت منه أقرب\nأرخى له بنبجه رجليه ، … والموت قد سابقه إليه\nصحت وصاح القوم بالتكبير ، … وغيرنا يضمر في الصدور\nثم تصايحنا فطارت واحده … شيطانة من الطيور مارده\nمن قرب فأرسلوا إليها … ولم تزل أعينهم عليها\nفلم يعلق بازه وأدى … من بعد ما قاربها وشدا\nصحت : أهذا الباز أم دجاجه ؟ … ليت جناحيه على دراجه\nفاحمرت الأوجه والعيون … وقال : هذا موضع ملعون\nإن لزها الباز أصابت نبجا … أو سقطت لم تلق إلا مدرجا\nاعدل بنا للنبج الخفيف … والموضع المنفرد المكشوف\nفقثلت : هذي حجة ضعيفة … وغرة ظاهرة معروفه\nنحن جميعا في مكان واحد ، … فلا تعلل بالكلام البارد !\nقص جناحيه يكن في الدار … مع الدباسي ، ومع القماري !\nواعمد إلى جلجله البديع ، … فاجعله في عنز من القطيع !\nحتى إذا أبصرته ، وقد خجل ، … قلت : أراه ، فارها ، على الحجل\nدعه ، وهذا الباز فاطرد به … تفاديا من غمه وعتبه !\nوقلت للخيل ، التي حولينا : … تشاهدوا كلكم علينا !\nبأنه عارية مضمونه ، … يقيم فيها جاهه ودينه\nجئت بباز حسن مبهرج … دون العقاب وفويق الزمج\nزين لرائيه ، وفوق الزين ، … ينظر من نارين في غارين\nكأن فوق صدره والهادي … آثار مشي الذر في الرماد\nذي منسر فخم وعين غائره ، … وفخذ ملء اليمين وافره\nضخم ، قريب الدستبان جدا … يلقى الذي يحمل منه كدا\nوراحة تغمر كفي سبطه … زاد على قدر البزاة بسطه\nسر ، وقال : هات ! قلت : مهلا ! … احلف على الرد ! ' فقال : كلا !\nأما يميني ، فهي عندي غاليه … وكلمتي مثل يميني وافيه\nقلت : فخذه هبة بقبلة ! … فصد عني ، وعلته خجله\nفلم أزل أمسحه حتى انبسط … وهش للصيد قليلا ، ونشط\nصحت به : اركب ! فاستقل عن يد … مبادرا أسرع من قول : قد !\nوضم ساقيه وقال : قد حصل ! … قلت له : ' الغدرة من شر العمل ! '\nسرت ، وسار الغادر العيار … ليس لطير معنا مطار\nثم عدلنا نحونهر الوادي ، … والطير فيه عدد الجراد\nأدرت شاهينين في مكان … لكثرة الصيد مع الإمكان\nدارا علينا دورة وحلقا ، … كلاهما ، حتى إذا تعلقا\nتوازيا ، واطردا اطرادا ، … كالفارسين التقيا أو كادا\nثمت شدا فأصابا أربعا … ثلاثة خضرا ، وطيرا أبقعا\nثم ذبحناها ، وخلصناهما … وأمكن الصيد فأرسلناهما\nفجدلا خمسا من الطيور ، … فزادني الرحمن في سروري\nأربعة منها أنيسيان … وطائرا يعرف بالبيضاني\nخيل نناجيهن كيف شينا … طيعة ، ولجمها أيدينا\nوهي إذا ما استصعب القياده … صرفها الجوع على الإراده\n … تساقطت ما بيننا من الفرق\nحتى أخذنا ما أردنا منها … ثم انصرفنا راغبين عنها\nإلى كراكي بقرب النهر … عشرا نراها ، أو فويق العشر\nلما رآها الباز ، من بعد ، لصق … وحدد الطرف إليها وذرق\nفقلت : قد صاد ، ورب الكعبه ، … \nفدار حتى أمكنت ثم نزل … فحط منها أفرعا مثل الجمل\nما انحط إلا وأنا إليه … ممكنا رجلي من رجليه\nجلست كي أشبعه إذا هيه … قد سقطت من عن يمين الرابيه\nفشلته أرغب في الزيادة ، … وتلك للطراد شر عادة\nلم أجزه بأحسن البلاء ، … أطعت حرصي ، وعصيت دائي\nفلم أزل أختلها وتختتل ، … وإنما نختلها إلى أجل\nعمدت منها لكبير مفرد … يمشي بعنق كالرشاء المحصد\nطار ، وما طار ليأتيه القدر ، … وهل لما قد حان سمع أو بصر ! ؟\nحتى إذا جدله كالعندل ، … أيقنت أن العظم غير الفصل\nذاك ، على ما نلت منه ، أمر … عثرت فيه وأقال الدهر !\nخير من النجاح للإنسان … \nصحت إلى الطباخ : ماذا تنتظر ؟ … انزل عن المهر ، وهات ما حضر\nجاء بأوساط ، وجرد تاج ، … من حجل الصيد ومن دراج\nفما تنازلنا عن الخيول ، … يمنعنا الحرص عن النزول\nوجيء بالكأس وبالشراب ، … فقلت : وفرها على أصحابي !\nأشبعني اليوم ورواني الفرح ، … فقد كفاني بعض وسط وقدح\nثم عدلنا نطلب الصحراء ، … نلتمس الوحوش والظباء\nعن لنا سرب ببطن الوادي … \nقد صدرت عن منهل روي ، … من غبر الوسمي والولي\nليس بمطروق ولا بكي ، … ومرتع مقتبل جني\nرعين فيه ، غير مذعورات ، … \nمر عليه غدق السحاب … بواكف ، متصل الرباب\nمازال في خفض ، وحسن حال … حتى أصابته بنا الليالي\nسرب حماه الدهر ما حماه … لما رآنا ارتد ما أعطاه\nبادرت بالصقار والفهاد … حتى سبقناه إلى الميعاد\nفجدل الفهد الكبير الأقرنا ، … شد على مذبحه واستبطنا\nوجدل الآخر عنزا حائلا … رعت حمى الغورين حولا كاملا\nثم رميناهن بالصقور … فجئنها بالقدر المقدور\nأفردن منها في القراح واحدة … قد ثقلت بالخصر وهي جاهده\nمرت بنا ، والصقر في قذالها … يؤذنها بسيء من حالها\nثم ثناها وأتاها الكلب … هما ، عليها ، والزمان إلب\nفلم نزل نصيدها ونصرع … حتى تبقى في القطيع أربع\nثم عدلنا عدلة إلى الجبل … إلى الأراوي ، والكباش والحجل\nفلم نزل بالخيل والكلاب … نحوزها حوزا ، إلى الغياب\nثم انصرفنا ، والبغال موقره ، … في ليلة ، مثل الصباح ، مسفره\nحتى أتينا رحلنا بليل ، … وقد سبقنا بجياد الخيل\n … حتى عددنا مئة وزيدا\nفلم نزل نقلي ، ونشوي ، ونصب ، … حتى طلبنا صاحيا فلم نصب\nشربا ، كما عن ، من الزقاق … بغير ترتيب ، وغير ساق\nفلم نزل سبع ليال عددا … أسعد من راح ، وأحظى من غدا"}]};